-- Easy Professions (Forever): guide texts in ruRU (translated from wow-professions.com/forever)
local _, ns = ...
ns.AddTranslation("ruRU", {
  ["This WoW Forever Alchemy leveling guide will show you the fastest and cheapest way to level your Alchemy skill from 1 to 300. You will also find every trainer location and where to train Alchemy past 75, 150 and 225."] = "Это руководство по прокачке алхимии для WoW Forever покажет тебе самый быстрый и дешевый способ поднять навык алхимии с 1 до 300. Здесь же ты найдешь всех учителей и узнаешь, где учиться алхимии после 75, 150 и 225.",
  ["Below you will find the full shopping list, the Alchemy trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Alchemy is best combined with Herbalism, with these two you can save a lot of gold because you don't have to buy the herbs from the Auction House."] = "Ниже ты найдешь полный список покупок, учителей алхимии по стартовым зонам и столицам, а также самые дешевые рецепты для каждого диапазона навыка от Ученика до Мастера. Алхимию лучше всего сочетать с травничеством: так ты сэкономишь много золота, ведь травы не придется покупать на аукционе.",
  ["This is based on the Forever beta. Leveling takes a long time, so testing the higher levels on live will take a while. If you find something that's off, send me feedback."] = "Руководство основано на бете Forever. Прокачка занимает много времени, поэтому проверка высоких уровней на живом сервере займет время. Если найдешь неточность, напиши мне.",
  ["Shopping List"] = "Список покупок",
  ["These numbers are estimates. Once a recipe turns yellow you won't get a skill point from every craft, so you might need a few more or a few less."] = "Это примерные цифры. Когда рецепт становится желтым, не каждое изготовление дает очко навыка, так что может понадобиться чуть больше или чуть меньше.",
  ["Alchemy Trainer Locations"] = "Где найти учителей алхимии",
  ["Apprentice Alchemy has no level requirement in Forever, so you can learn it on a fresh character."] = "В Forever у алхимии уровня Ученик нет требований к уровню, так что ее можно выучить новым персонажем.",
  ["Every capital city has a trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Учитель есть в каждой столице. Можно также спросить стражника, и тогда учитель будет отмечен красным флажком на карте.",
  ["Horde"] = "Орда",
  ["Alliance"] = "Альянс",
  ["Capital Cities"] = "Столицы",
  ["Orgrimmar: {n:0:horde:Whuut}"] = "Оргриммар: {n:0:horde:Whuut}",
  ["Undercity: {n:0:horde:Doctor Martin Felben}"] = "Подгород: {n:0:horde:Doctor Martin Felben}",
  ["Thunder Bluff: {n:0:horde:Kray}"] = "Громовой Утес: {n:0:horde:Kray}",
  ["Starting Zones"] = "Стартовые зоны",
  ["Not every zone has a trainer, the table shows the closest one for each race."] = "Учитель есть не в каждой зоне, в таблице указан ближайший для каждой расы.",
  ["Race"] = "Раса",
  ["Zone"] = "Зона",
  ["Closest trainer"] = "Ближайший учитель",
  ["Orc, Troll"] = "Орк, тролль",
  ["Durotar"] = "Дуротар",
  ["{n:0:horde:Miao'zan} in Sen'jin Village"] = "{n:0:horde:Miao'zan} в деревне Сен'джин",
  ["Tauren"] = "Таурен",
  ["Mulgore"] = "Мулгор",
  ["There is no Alchemy trainer in Mulgore, go to {n:0:horde:Kray} on the middle rise in Thunder Bluff"] = "В Мулгоре нет учителя алхимии, иди к {n:0:horde:Kray} на средний уступ Громового Утеса",
  ["Undead"] = "Нежить",
  ["Tirisfal Glades"] = "Тирисфальские леса",
  ["{n:0:horde:Carolai Anise} in the small house at the north-west end of Brill"] = "{n:0:horde:Carolai Anise} в маленьком доме на северо-западной окраине Брилла",
  ["Skyborne"] = "Скайборн",
  ["Zephras Isle"] = "Остров Зефрас",
  ["{n:0::Iaadaria Bitterwind} or {n:0::Valiena Swiftgale} in Valanaar, {n:0::Nyassa Swiftdraught} in Shen'dar Village"] = "{n:0::Iaadaria Bitterwind} или {n:0::Valiena Swiftgale} в Валанааре, {n:0::Nyassa Swiftdraught} в деревне Шен'дар",
  ["Stormwind City: {n:0:alliance:Tel'Athir}"] = "Штормград: {n:0:alliance:Tel'Athir}",
  ["Ironforge: {n:0:alliance:Vosur Brakthel}"] = "Стальгорн: {n:0:alliance:Vosur Brakthel}",
  ["Darnassus: {n:0:alliance:Milla Fairancora}"] = "Дарнас: {n:0:alliance:Milla Fairancora}",
  ["Human"] = "Человек",
  ["Elwynn Forest"] = "Элвиннский лес",
  ["{n:0:alliance:Alchemist Mallory} in a cottage in the hills between Stormwind and Northshire"] = "{n:0:alliance:Alchemist Mallory} в домике на холмах между Штормградом и Североземьем",
  ["Dwarf, Gnome"] = "Дворф, гном",
  ["Dun Morogh"] = "Дун Морог",
  ["There is no Alchemy trainer in Dun Morogh, go to {n:0:alliance:Vosur Brakthel} in Tinker Town in Ironforge"] = "В Дун Мороге нет учителя алхимии, иди к {n:0:alliance:Vosur Brakthel} в Город Механиков в Стальгорне",
  ["Night Elf"] = "Ночной эльф",
  ["Teldrassil"] = "Тельдрассил",
  ["{n:0:alliance:Cyndra Kindwhisper} in a small house east of the inn in Dolanaar"] = "{n:0:alliance:Cyndra Kindwhisper} в маленьком доме к востоку от таверны в Доланааре",
  ["You can find every Alchemy trainer for Horde and Alliance on my WoW Forever Alchemy Trainers page."] = "Всех учителей алхимии Орды и Альянса ты найдешь на моей странице «WoW Forever Alchemy Trainers».",
  ["Apprentice Alchemy (1-55)"] = "Алхимия: Ученик (1-55)",
  ["9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Silverleaf, 9 Empty Vial"] = "9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Сребролист, 9 Пустой флакон",
  ["The vials are sold by Alchemy Supply and Trade Supply vendors, most trainers have one nearby. In Undercity the closest one is {n:0:horde:Algernon}, in Dolanaar it's {n:0:alliance:Narret Shadowgrove}."] = "Флаконы продают торговцы алхимическими и ремесленными товарами, обычно такой стоит рядом с учителем. В Подгороде ближайший из них {n:0:horde:Algernon}, в Доланааре это {n:0:alliance:Narret Shadowgrove}.",
  ["45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Silverleaf, 45 Peacebloom, 45 Empty Vial"] = "45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Сребролист, 45 Мироцвет, 45 Пустой флакон",
  ["Journeyman Alchemy (55-150)"] = "Алхимия: Подмастерье (55-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Alchemy. You need {b}Alchemy 50{/b} and {b}level 10{/b}:"] = "Чтобы учиться дальше 75, посети одного из этих учителей и выучи алхимию уровня Подмастерье. Нужно {b}Алхимия 50{/b} и {b}10-й уровень{/b}:",
  ["{b}Horde trainers:{/b}"] = "{b}Учителя Орды:{/b}",
  ["Orgrimmar: {n:0:horde:Yelmak}"] = "Оргриммар: {n:0:horde:Yelmak}",
  ["Undercity: {n:0:horde:Doctor Marsh}"] = "Подгород: {n:0:horde:Doctor Marsh}",
  ["Thunder Bluff: {n:0:horde:Bena Winterhoof}"] = "Громовой Утес: {n:0:horde:Bena Winterhoof}",
  ["{b}Alliance trainers:{/b}"] = "{b}Учителя Альянса:{/b}",
  ["Stormwind City: {n:0:alliance:Lilyssia Nightbreeze}"] = "Штормград: {n:0:alliance:Lilyssia Nightbreeze}",
  ["Ironforge: {n:0:alliance:Tally Berryfizz}"] = "Стальгорн: {n:0:alliance:Tally Berryfizz}",
  ["Darnassus: {n:0:alliance:Sylvanna Forestmoon}"] = "Дарнас: {n:0:alliance:Sylvanna Forestmoon}",
  ["10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Mageroyal, 10 Peacebloom, 10 Empty Vial"] = "10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Магороза, 10 Мироцвет, 10 Пустой флакон",
  ["28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Earthroot, 28 Peacebloom, 28 Empty Vial"] = "28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Земляной корень, 28 Мироцвет, 28 Пустой флакон",
  ["30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Mageroyal, 60 Briarthorn, 30 Empty Vial"] = "30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Магороза, 60 Остротерн, 30 Пустой флакон",
  ["Keep the elixirs if you also level Tailoring, you will need them for the Gloves of Meditation."] = "Если ты также качаешь портняжное дело, сохрани эликсиры: они понадобятся для Перчаток медитации.",
  ["10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Mageroyal, 10 Stranglekelp, 10 Empty Vial"] = "10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Магороза, 10 Удавник, 10 Пустой флакон",
  ["20x {s:7837:inv_potion_38:Fire Oil} - 40 Firefin Snapper, 20 Empty Vial"] = "20x {s:7837:inv_potion_38:Fire Oil} - 40 Огнеперый луциан, 20 Пустой флакон",
  ["You get 2 oils from every craft. Keep 30 of them, you will need them for the Elixir of Fire Power in the next part."] = "С каждого изготовления получается 2 масла. Сохрани 30 штук, они понадобятся для Эликсира огненной мощи в следующей части.",
  ["Expert Alchemy (150-225)"] = "Алхимия: Умелец (150-225)",
  ["To train past 150, visit {n:0:horde:Doctor Herbert Halsey} in Undercity (Horde) or {n:0:alliance:Ainethil} in Darnassus (Alliance) and learn Expert Alchemy. You need {b}Alchemy 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Чтобы учиться дальше 150, посети {n:0:horde:Doctor Herbert Halsey} в Подгороде (Орда) или {n:0:alliance:Ainethil} в Дарнасе (Альянс) и выучи алхимию уровня Умелец. Нужно {b}Алхимия 125{/b} и {b}20-й уровень{/b}, стоит 50 серебра.",
  ["15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Fire Oil, 15 Kingsblood, 15 Leaded Vial"] = "15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Огненное масло, 15 Королевская кровь, 15 Освинцованный флакон",
  ["These are the Fire Oils you kept."] = "Это те огненные масла, которые ты сохранил.",
  ["36x {s:3452:inv_potion_72:Mana Potion} - 36 Stranglekelp, 36 Kingsblood, 36 Leaded Vial"] = "36x {s:3452:inv_potion_72:Mana Potion} - 36 Удавник, 36 Королевская кровь, 36 Освинцованный флакон",
  ["36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Liferoot, 36 Stranglekelp, 36 Leaded Vial"] = "36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Корень жизни, 36 Удавник, 36 Освинцованный флакон",
  ["{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} is sold by these vendors, it's bind on pickup, so buy it with the character that levels Alchemy:"] = "{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} продают эти торговцы. Рецепт становится персональным при получении, так что покупай его тем персонажем, который качает алхимию:",
  ["{n:0:horde:Bronk} in Feralas"] = "{n:0:horde:Bronk} в Фераласе",
  ["{n:0:alliance:Logannas} in Feralas"] = "{n:0:alliance:Logannas} в Фераласе",
  ["{n:0::Glyx Brewright} in Stranglethorn Vale"] = "{n:0::Glyx Brewright} в Тернистой долине",
  ["{n:0::Alchemist Pestlezugg} in Tanaris"] = "{n:0::Alchemist Pestlezugg} в Танарисе",
  ["Artisan Alchemy (225-300)"] = "Алхимия: Мастер (225-300)",
  ["To train past 225, visit {n:0:horde:Rogvar} in Stonard, Swamp of Sorrows (Horde) or {n:0:alliance:Kylanna Windwhisper} in Feathermoon Stronghold, Feralas (Alliance) and learn Artisan Alchemy. You need {b}Alchemy 200{/b} and {b}level 35{/b}."] = "Чтобы учиться дальше 225, посети {n:0:horde:Rogvar} в Каменоре на Болоте Печали (Орда) или {n:0:alliance:Kylanna Windwhisper} в Крепости Оперенной Луны в Фераласе (Альянс) и выучи алхимию уровня Мастер. Нужно {b}Алхимия 200{/b} и {b}35-й уровень{/b}.",
  ["26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Liferoot, 26 Stranglekelp, 26 Leaded Vial"] = "26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Корень жизни, 26 Удавник, 26 Освинцованный флакон",
  ["15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Blindweed, 15 Khadgar's Whisker, 15 Crystal Vial"] = "15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Пастушья сумка, 15 Кадгаров ус, 15 Хрустальный флакон",
  ["47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Stonescale Eel, 47 Leaded Vial"] = "47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Каменночешуйчатый угорь, 47 Освинцованный флакон",
  ["{b}Keep all of them{/b}, one craft makes 2 and the elixirs at 265 need all 94."] = "{b}Сохрани все{/b}: одно изготовление дает 2 штуки, а для эликсиров на 265 нужны все 94.",
  ["Alternative recipe"] = "Альтернативный рецепт",
  ["If {i:13422:inv_misc_fish_11:Stonescale Eel} is expensive, skip this and keep making the Elixir of Greater Intellect until 265 (about 21), then make the Superior Mana Potions under 265-300."] = "Если {i:13422:inv_misc_fish_11:Stonescale Eel} дорогой, пропусти этот шаг и продолжай делать Эликсир высшего интеллекта до 265 (примерно 21 штука), а затем делай Превосходные зелья маны из раздела 265-300.",
  ["10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Blindweed, 10 Khadgar's Whisker, 10 Crystal Vial"] = "10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Пастушья сумка, 10 Кадгаров ус, 10 Хрустальный флакон",
  ["47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Stonescale Oil, 47 Sungrass, 47 Crystal Vial"] = "47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Масло каменной чешуи, 47 Солнечник, 47 Хрустальный флакон",
  ["{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} is sold by {n:0:horde:Kor'geld} in Orgrimmar and {n:0:alliance:Soolie Berryfizz} in Ironforge."] = "{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} продают {n:0:horde:Kor'geld} в Оргриммаре и {n:0:alliance:Soolie Berryfizz} в Стальгорне.",
  ["If you skipped the Stonescale Oil, make this:"] = "Если ты пропустил Масло каменной чешуи, делай вот это:",
  ["55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Sungrass, 110 Blindweed, 55 Crystal Vial."] = "55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Солнечник, 110 Пастушья сумка, 55 Хрустальный флакон.",
  ["{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} is sold by {n:0:horde:Algernon} in Undercity and {n:0:alliance:Ulthir} in Darnassus."] = "{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} продают {n:0:horde:Algernon} в Подгороде и {n:0:alliance:Ulthir} в Дарнасе.",
  ["This WoW Forever Blacksmithing leveling guide will show you the fastest and cheapest way to level your Blacksmithing skill from 1 to 300. You will also find every trainer location and where to train Blacksmithing past 75, 150 and 225."] = "Это руководство по прокачке кузнечного дела для WoW Forever покажет тебе самый быстрый и дешевый способ поднять навык кузнечного дела с 1 до 300. Здесь же ты найдешь всех учителей и узнаешь, где учиться кузнечному делу после 75, 150 и 225.",
  ["Below you will find the full shopping list, the Blacksmithing trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Blacksmithing uses a lot of ore, so I recommend leveling it together with Mining, you will need a lot of gold if you want to buy everything from the Auction House."] = "Ниже ты найдешь полный список покупок, учителей кузнечного дела по стартовым зонам и столицам, а также самые дешевые рецепты для каждого диапазона навыка от Ученика до Мастера. Кузнечное дело требует много руды, поэтому советую качать его вместе с горным делом: если покупать все на аукционе, понадобится очень много золота.",
  ["The Thorium Bars include the 140 you need for the four quests."] = "В число ториевых слитков входят 140 штук, нужных для четырех заданий.",
  ["Blacksmithing Trainer Locations"] = "Где найти учителей кузнечного дела",
  ["Apprentice Blacksmithing has no level requirement in Forever, so you can learn it on a fresh character."] = "В Forever у кузнечного дела уровня Ученик нет требований к уровню, так что его можно выучить новым персонажем.",
  ["Every capital city has a trainer except Darnassus. You can also ask a guard, then it will be marked with a red flag on your map."] = "Учитель есть в каждой столице, кроме Дарнаса. Можно также спросить стражника, и тогда учитель будет отмечен красным флажком на карте.",
  ["Orgrimmar: {n:0:horde:Ug'thok}"] = "Оргриммар: {n:0:horde:Ug'thok}",
  ["Undercity: {n:0:horde:Basil Frye}"] = "Подгород: {n:0:horde:Basil Frye}",
  ["Thunder Bluff: {n:0:horde:Thrag Stonehoof}"] = "Громовой Утес: {n:0:horde:Thrag Stonehoof}",
  ["{n:0:horde:Dwukk} at the forge in Razor Hill"] = "{n:0:horde:Dwukk} у кузни в Колючем Холме",
  ["There is no Blacksmithing trainer in Mulgore, go to {n:0:horde:Thrag Stonehoof} on the lower rise in Thunder Bluff"] = "В Мулгоре нет учителя кузнечного дела, иди к {n:0:horde:Thrag Stonehoof} на нижний уступ Громового Утеса",
  ["{n:0:horde:Angus Hammerhand} at Bandarion Keep. Nobody near him sells a {i:5956:inv_hammer_20:Blacksmith Hammer}, {b}buy one before you go{/b} from {n:0:horde:Walter Mason} in Deathknell or {n:0:horde:Abigail Shiel} in Brill."] = "{n:0:horde:Angus Hammerhand} в Цитадели Бандариона. Рядом с ним никто не продает {i:5956:inv_hammer_20:Blacksmith Hammer}, так что {b}купи его заранее{/b} у {n:0:horde:Walter Mason} в Похоронном Звоне или у {n:0:horde:Abigail Shiel} в Брилле.",
  ["{n:0::Daeann Steelwind} in Valanaar, {n:0::Aedi Thriceforged} in Shen'dar Village"] = "{n:0::Daeann Steelwind} в Валанааре, {n:0::Aedi Thriceforged} в деревне Шен'дар",
  ["Stormwind City: {n:0:alliance:Dane Lindgren}"] = "Штормград: {n:0:alliance:Dane Lindgren}",
  ["Ironforge: {n:0:alliance:Groum Stonebeard}"] = "Стальгорн: {n:0:alliance:Groum Stonebeard}",
  ["{n:0:alliance:Smith Argus} in Goldshire, across from the inn"] = "{n:0:alliance:Smith Argus} в Златоземье, напротив таверны",
  ["{n:0:alliance:Tognus Flintfire} in Kharanos, across from the Thunderbrew Distillery"] = "{n:0:alliance:Tognus Flintfire} в Караносе, напротив пивоварни Громоваров",
  ["There is no Blacksmithing trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Delfrum Flintbeard} in Auberdine, Darkshore"] = "В Тельдрассиле и Дарнасе нет учителя кузнечного дела, ближайший из них {n:0:alliance:Delfrum Flintbeard} в Аубердине на Темных берегах",
  ["You can find every Blacksmithing trainer for Horde and Alliance on my WoW Forever Blacksmithing Trainers page."] = "Всех учителей кузнечного дела Орды и Альянса ты найдешь на моей странице «WoW Forever Blacksmithing Trainers».",
  ["Apprentice Blacksmithing (1-75)"] = "Кузнечное дело: Ученик (1-75)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer} when you learn Blacksmithing, most recipes need it, so you can craft gear for yourself while you level. It costs a few copper, open your faction below to see who sells it closest to your trainer."] = "Когда выучишь кузнечное дело, купи {i:5956:inv_hammer_20:Blacksmith Hammer}: он нужен для большинства рецептов, и по ходу прокачки ты сможешь делать снаряжение для себя. Он стоит несколько медяков. Открой свою фракцию ниже, чтобы узнать, кто продает его ближе всего к твоему учителю.",
  ["Horde vendors"] = "Торговцы Орды",
  ["Vendor"] = "Торговец",
  ["Orgrimmar"] = "Оргриммар",
  ["{n:0:horde:Sumi}, right next to the trainer"] = "{n:0:horde:Sumi}, прямо рядом с учителем",
  ["Undercity"] = "Подгород",
  ["{n:0:horde:Samuel Van Brunt}, right next to the trainer"] = "{n:0:horde:Samuel Van Brunt}, прямо рядом с учителем",
  ["Thunder Bluff"] = "Громовой Утес",
  ["{n:0:horde:Taur Stonehoof}, right next to the trainer"] = "{n:0:horde:Taur Stonehoof}, прямо рядом с учителем",
  ["{n:0:horde:Flakk} in Razor Hill"] = "{n:0:horde:Flakk} в Колючем Холме",
  ["{n:0:horde:Walter Mason} in Deathknell {n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Walter Mason} в Похоронном Звоне {n:0:horde:Abigail Shiel} в Брилле",
  ["{n:0::Halavuul Cragwind}, the Mining trainer in Valanaar {n:0::Aedi Thriceforged} in Shen'dar Village"] = "{n:0::Halavuul Cragwind}, учитель горного дела в Валанааре {n:0::Aedi Thriceforged} в деревне Шен'дар",
  ["Alliance vendors"] = "Торговцы Альянса",
  ["Stormwind City"] = "Штормград",
  ["{n:0:alliance:Kaita Deepforge}, right next to the trainer"] = "{n:0:alliance:Kaita Deepforge}, прямо рядом с учителем",
  ["Ironforge"] = "Стальгорн",
  ["{n:0:alliance:Thurgrum Deepforge}, right next to the trainer"] = "{n:0:alliance:Thurgrum Deepforge}, прямо рядом с учителем",
  ["{n:0:alliance:Tharynn Bouden} in Goldshire"] = "{n:0:alliance:Tharynn Bouden} в Златоземье",
  ["{n:0:alliance:Thrawn Boltar}, right next to the trainer"] = "{n:0:alliance:Thrawn Boltar}, прямо рядом с учителем",
  ["Darkshore"] = "Темные берега",
  ["{n:0:alliance:Elisa Steelhand} in Auberdine, right next to the trainer"] = "{n:0:alliance:Elisa Steelhand} в Аубердине, прямо рядом с учителем",
  ["30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Rough Stone"] = "30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Грубый камень",
  ["30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Rough Stone"] = "30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Грубый камень",
  ["Keep 10 of them, you need them for the Silver Rods at 75."] = "Сохрани 10 штук, они понадобятся для Серебряных жезлов на 75.",
  ["36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Coarse Stone"] = "36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Шершавый камень",
  ["Make all 36, you will need them for the bracers at 95 and 112."] = "Сделай все 36, они понадобятся для наручей на 95 и 112.",
  ["If you are not at 75 after these, make a few more."] = "Если после этого у тебя еще нет 75, сделай еще несколько.",
  ["Journeyman Blacksmithing (75-150)"] = "Кузнечное дело: Подмастерье (75-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Blacksmithing. You need {b}Blacksmithing 50{/b} and {b}level 10{/b}:"] = "Чтобы учиться дальше 75, посети одного из этих учителей и выучи кузнечное дело уровня Подмастерье. Нужно {b}Кузнечное дело 50{/b} и {b}10-й уровень{/b}:",
  ["Orgrimmar: {n:0:horde:Snarl}"] = "Оргриммар: {n:0:horde:Snarl}",
  ["Undercity: {n:0:horde:James Van Brunt}"] = "Подгород: {n:0:horde:James Van Brunt}",
  ["Thunder Bluff: {n:0:horde:Karn Stonehoof}"] = "Громовой Утес: {n:0:horde:Karn Stonehoof}",
  ["Tirisfal Glades: {n:0:horde:Angus Hammerhand} at Bandarion Keep"] = "Тирисфальские леса: {n:0:horde:Angus Hammerhand} в Цитадели Бандариона",
  ["Zephras Isle: {n:0::Daeann Steelwind} in Valanaar"] = "Остров Зефрас: {n:0::Daeann Steelwind} в Валанааре",
  ["Stormwind City: {n:0:alliance:Therum Deepforge}"] = "Штормград: {n:0:alliance:Therum Deepforge}",
  ["Ironforge: {n:0:alliance:Rotgath Stonebeard}"] = "Стальгорн: {n:0:alliance:Rotgath Stonebeard}",
  ["5x {s:7818:inv_staff_01:Silver Rod} - 5 Silver Bar, 10 Rough Grinding Stone"] = "5x {s:7818:inv_staff_01:Silver Rod} - 5 Серебряный слиток, 10 Грубый шлифовальный камень",
  ["You need the {i:5956:inv_hammer_20:Blacksmith Hammer} from here on."] = "С этого момента тебе нужен {i:5956:inv_hammer_20:Blacksmith Hammer}.",
  ["Make 5x {s:2666:inv_belt_03:Runed Copper Belt} instead (10 Copper Bar each) if one Silver Bar costs more than 10 Copper Bars."] = "Если один серебряный слиток стоит дороже 10 медных, сделай вместо этого 5x {s:2666:inv_belt_03:Runed Copper Belt} (по 10 медных слитков).",
  ["18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Copper Bar"] = "18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Медный слиток",
  ["5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Bronze Bar, 10 Coarse Grinding Stone"] = "5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Бронзовый слиток, 10 Шершавый шлифовальный камень",
  ["Use 10 of the Coarse Grinding Stones you made at 50 and keep the other 26 for 112."] = "Используй 10 шершавых шлифовальных камней, сделанных на 50, а остальные 26 оставь на 112.",
  ["20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Heavy Stone"] = "20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Тяжелый камень",
  ["Keep them, you need all 20 for the Golden Scale Bracers at 180."] = "Сохрани их, все 20 понадобятся для Наручей с золотой чешуей на 180.",
  ["13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Bronze Bar, 26 Coarse Grinding Stone"] = "13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Бронзовый слиток, 26 Шершавый шлифовальный камень",
  ["24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Bronze Bar, 96 Weak Flux, 48 Medium Leather"] = "24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Бронзовый слиток, 96 Слабый флюс, 48 Средняя кожа",
  ["I recommend these over the Patterned Bronze Bracers because they sell for more than twice as much to a vendor, so they end up cheaper."] = "Советую их вместо Узорчатых бронзовых наручей: торговцу они продаются более чем вдвое дороже, так что в итоге выходят дешевле.",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} and the {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} for the Bronze Warhammers (140-150) are sold by the Blacksmithing Supply vendor right next to the Blacksmithing trainer in every capital city."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} и {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} для Бронзовых боевых молотов (140-150) продает торговец кузнечными товарами прямо рядом с учителем кузнечного дела в каждой столице.",
  ["If you disenchant your greens:"] = "Если ты распыляешь зеленые вещи:",
  ["24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Bronze Bar, 48 Coarse Grinding Stone."] = "24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Бронзовый слиток, 48 Шершавый шлифовальный камень.",
  ["10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Bronze Bar, 10 Strong Flux, 10 Medium Leather"] = "10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Бронзовый слиток, 10 Сильный флюс, 10 Средняя кожа",
  ["Expert Blacksmithing (150-215)"] = "Кузнечное дело: Умелец (150-215)",
  ["To train past 150, visit {n:0:horde:Saru Steelfury} in Orgrimmar (Horde) or {n:0:alliance:Bengus Deepforge} in Ironforge (Alliance) and learn Expert Blacksmithing. You need {b}Blacksmithing 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Чтобы учиться дальше 150, посети {n:0:horde:Saru Steelfury} в Оргриммаре (Орда) или {n:0:alliance:Bengus Deepforge} в Стальгорне (Альянс) и выучи кузнечное дело уровня Умелец. Нужно {b}Кузнечное дело 125{/b} и {b}20-й уровень{/b}, стоит 50 серебра.",
  ["30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Iron Bar, 30 Green Dye"] = "30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Железный слиток, 30 Зеленый краситель",
  ["Green Dye is sold by {n:0:horde:Tamar} in Orgrimmar and {n:0:alliance:Bombus Finespindle} in Ironforge."] = "Зеленый краситель продают {n:0:horde:Tamar} в Оргриммаре и {n:0:alliance:Bombus Finespindle} в Стальгорне.",
  ["8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Solid Stone"] = "8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Твердый камень",
  ["Keep them, you need 6 for the Heavy Mithril Axes at 210."] = "Сохрани их, 6 штук понадобятся для Тяжелых мифриловых топоров на 210.",
  ["20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Steel Bar, 40 Heavy Grinding Stone"] = "20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Стальной слиток, 40 Тяжелый шлифовальный камень",
  ["Use the 20 Heavy Grinding Stones you made at 100 and make 20 more (60 {i:2838:inv_stone_12:Heavy Stone})."] = "Используй 20 тяжелых шлифовальных камней, сделанных на 100, и сделай еще 20 (60 {i:2838:inv_stone_12:Heavy Stone}).",
  ["If you have Mining 165, you can smelt the {i:3859:inv_ingot_steel:Steel Bars} yourself from {i:3575:inv_ingot_iron:Iron Bar} and {i:3857:inv_ore_tin_01:Coal}. Coal is sold by the Blacksmithing Supply vendor next to the Blacksmithing trainer in every capital city."] = "Если у тебя горное дело 165, можешь сам выплавить {i:3859:inv_ingot_steel:Steel Bars} из {i:3575:inv_ingot_iron:Iron Bar} и {i:3857:inv_ore_tin_01:Coal}. Уголь продает торговец кузнечными товарами рядом с учителем кузнечного дела в каждой столице.",
  ["Alliance players should keep 6 of these. You might need them if you choose Armorsmithing."] = "Игрокам Альянса стоит сохранить 6 штук. Они могут понадобиться, если выберешь бронника.",
  ["17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Mithril Bar"] = "17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Мифриловый слиток",
  ["I recommend these over the Heavy Mithril Gauntlets because they sell for more than three times as much to a vendor, so they end up cheaper."] = "Советую их вместо Тяжелых мифриловых рукавиц: торговцу они продаются более чем втрое дороже, так что в итоге выходят дешевле.",
  ["6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Mithril Bar, 12 Citrine, 6 Solid Grinding Stone, 24 Heavy Leather"] = "6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Мифриловый слиток, 12 Цитрин, 6 Твердый шлифовальный камень, 24 Толстая кожа",
  ["Keep 2 of these. You might need them if you choose Weaponsmithing."] = "Сохрани 2 штуки. Они могут понадобиться, если выберешь оружейника.",
  ["Blacksmithing Specializations"] = "Специализации кузнечного дела",
  ["At {b}Blacksmithing 200{/b} and {b}level 40{/b}, you can specialize in Armorsmithing or Weaponsmithing to craft powerful armor or weapons. Choosing one is optional, you don't need it to level Blacksmithing, and you can choose later too."] = "На {b}Кузнечном деле 200{/b} и {b}40-м уровне{/b} можно выбрать специализацию: бронник или оружейник, чтобы делать мощную броню или оружие. Выбирать не обязательно, для прокачки кузнечного дела она не нужна, и выбрать можно и позже.",
  ["For information on how to become an Armorsmith or a Weaponsmith, please see my separate guides:"] = "О том, как стать бронником или оружейником, читай в моих отдельных руководствах:",
  ["Artisan Blacksmithing (215-300)"] = "Кузнечное дело: Мастер (215-300)",
  ["To train past 225, visit {n:0::Brikk Keencraft} in Booty Bay, Stranglethorn Vale and learn Artisan Blacksmithing. You need {b}Blacksmithing 200{/b} and {b}level 35{/b}, and both factions learn it there."] = "Чтобы учиться дальше 225, посети {n:0::Brikk Keencraft} в Пиратской Бухте в Тернистой долине и выучи кузнечное дело уровня Мастер. Нужно {b}Кузнечное дело 200{/b} и {b}35-й уровень{/b}, учатся у него обе фракции.",
  ["{i:7989:inv_scroll_06:Plans: Mithril Spurs} is a world drop. If you already have it, you can use the {b}Mithril Spurs{/b} tab instead."] = "{i:7989:inv_scroll_06:Plans: Mithril Spurs} выпадает в мире. Если он у тебя уже есть, можешь вместо этого использовать вкладку {b}Мифриловые шпоры{/b}.",
  ["Heavy Mithril"] = "Тяжелый мифрил",
  ["Mithril Spurs"] = "Мифриловые шпоры",
  ["10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Mithril Bar"] = "10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Мифриловый слиток",
  ["Keep 2 of these. You might need them if you choose Armorsmithing."] = "Сохрани 2 штуки. Они могут понадобиться, если выберешь бронника.",
  ["5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Dense Stone"] = "5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Плотный камень",
  ["16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Mithril Bar, 64 Thick Leather"] = "16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Мифриловый слиток, 64 Плотная кожа",
  ["5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Thorium Bar, 30 Rugged Leather, 5 Aquamarine"] = "5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Ториевый слиток, 30 Грубая кожа, 5 Аквамарин",
  ["You can get the recipe from the {q:7653::Imperial Plate Belt} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it. Do his {q:7652::A Blue Light Bargain} quest first, it unlocks the Imperial Plate quests."] = "Рецепт можно получить за задание {q:7653::Imperial Plate Belt} (требуется {b}50-й уровень{/b}) в Танарисе у {n:14567::Derotain Mudsipper}. Для выполнения понадобится 20 ториевых слитков. Сначала выполни его задание {q:7652::A Blue Light Bargain}, оно открывает задания на имперские латы.",
  ["{b}The next three recipes are also from the same NPC{/b}, so make sure to bring at least 140 Thorium Bar with you to get all 4 recipes."] = "{b}Следующие три рецепта дает тот же NPC{/b}, так что возьми с собой не меньше 140 ториевых слитков, чтобы получить все 4 рецепта.",
  ["If you have the plans for one of these world drops, you can make it from 240 instead:"] = "Если у тебя есть чертежи одной из этих вещей, выпадающих в мире, можешь делать ее начиная с 240:",
  ["240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Mithril Bar, 27 Aquamarine, 54 Lesser Moonstone, 54 Moss Agate, 27 Solid Grinding Stone, 54 Mageweave Cloth"] = "240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Мифриловый слиток, 27 Аквамарин, 54 Малый лунный камень, 54 Моховой агат, 27 Твердый шлифовальный камень, 54 Магическая ткань",
  ["240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Mithril Bar, 40 Core of Earth, 20 Solid Grinding Stone, 80 Thick Leather"] = "240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Мифриловый слиток, 40 Сердце земли, 20 Твердый шлифовальный камень, 80 Плотная кожа",
  ["240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Thorium Bar, 68 Blue Power Crystal"] = "240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Ториевый слиток, 68 Синий кристалл энергии",
  ["10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Mithril Bar, 30 Solid Grinding Stone (120 Solid Stone)"] = "10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Мифриловый слиток, 30 Твердый шлифовальный камень (120 Твердый камень)",
  ["33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Mithril Bar, 99 Solid Grinding Stone (396 Solid Stone)"] = "33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Мифриловый слиток, 99 Твердый шлифовальный камень (396 Твердый камень)",
  ["{b}The next three recipes all come from one NPC in Tanaris{/b}, so make sure to bring at least 120 Thorium Bar with you to get all 3 recipes."] = "{b}Следующие три рецепта дает один NPC в Танарисе{/b}, так что возьми с собой не меньше 120 ториевых слитков, чтобы получить все 3 рецепта.",
  ["27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Thorium Bar, 27 Star Ruby"] = "27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Ториевый слиток, 27 Звездный рубин",
  ["You get the recipe from the {q:7655::Imperial Plate Bracer} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it."] = "Рецепт дают за задание {q:7655::Imperial Plate Bracer} (требуется {b}50-й уровень{/b}) в Танарисе у {n:14567::Derotain Mudsipper}. Для выполнения понадобится 20 ториевых слитков.",
  ["20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Thorium Bar, 20 Star Ruby, 20 Aquamarine"] = "20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Ториевый слиток, 20 Звездный рубин, 20 Аквамарин",
  ["You get the recipe from the {q:7654::Imperial Plate Boots} quest, it needs 40 Thorium Bar."] = "Рецепт дают за задание {q:7654::Imperial Plate Boots}, для него нужно 40 ториевых слитков.",
  ["{b}Note:{/b} It wasn't possible to level this far on the beta, so this part only relies on the data I found in the game files. There might be more recipes we haven't discovered yet, but if there is nothing else, these are the only recipes you can use to level until 300."] = "{b}Примечание:{/b} на бете не получилось прокачаться так далеко, поэтому эта часть опирается только на данные, найденные в файлах игры. Возможно, есть еще рецепты, которые мы пока не нашли, но если других нет, то только этими рецептами можно прокачаться до 300.",
  ["10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Thorium Bar, 20 Star Ruby"] = "10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Ториевый слиток, 20 Звездный рубин",
  ["You get the recipe from the {q:7658::Imperial Plate Leggings} quest, it needs 60 Thorium Bar."] = "Рецепт дают за задание {q:7658::Imperial Plate Leggings}, для него нужно 60 ториевых слитков.",
  ["This WoW Forever Enchanting leveling guide will show you the fastest and cheapest way to level your Enchanting skill from 1 to 300. You will also find every trainer location and where to train Enchanting past 75, 150 and 225."] = "Это руководство по прокачке наложения чар для WoW Forever покажет тебе самый быстрый и дешевый способ поднять навык наложения чар с 1 до 300. Здесь же ты найдешь всех учителей и узнаешь, где учиться наложению чар после 75, 150 и 225.",
  ["Enchanting goes well with Tailoring because you don't need a gathering profession for either of them, and you can disenchant the items you made with Tailoring. Below you will find the shopping list, the Enchanting trainers by starting zone and capital city, and the cheapest enchants for every skill range. Forever added a few new low level recipes, so the first 70 points are cheaper than in Classic."] = "Наложение чар хорошо сочетается с портняжным делом: ни для одной из этих профессий не нужна собирательская профессия, а вещи, сшитые портным, можно распылять. Ниже ты найдешь список покупок, учителей наложения чар по стартовым зонам и столицам, а также самые дешевые чары для каждого диапазона навыка. В Forever добавили несколько новых низкоуровневых рецептов, поэтому первые 70 очков обходятся дешевле, чем в Classic.",
  ["An alternative replaces the whole row, so buy the one that is cheaper."] = "Альтернатива заменяет всю строку целиком, так что покупай то, что дешевле.",
  ["Enchanting Trainer Locations"] = "Где найти учителей наложения чар",
  ["Apprentice Enchanting has no level requirement in Forever, so you can learn it on a fresh character."] = "В Forever у наложения чар уровня Ученик нет требований к уровню, так что его можно выучить новым персонажем.",
  ["Orgrimmar: {n:0:horde:Jhag}"] = "Оргриммар: {n:0:horde:Jhag}",
  ["Undercity: {n:0:horde:Malcomb Wynn}"] = "Подгород: {n:0:horde:Malcomb Wynn}",
  ["Thunder Bluff: {n:0:horde:Mot Dawnstrider}"] = "Громовой Утес: {n:0:horde:Mot Dawnstrider}",
  ["{n:0:horde:Pa'zula} in Sen'jin Village"] = "{n:0:horde:Pa'zula} в деревне Сен'джин",
  ["There is no Enchanting trainer in Mulgore, go to {n:0:horde:Mot Dawnstrider} on the middle rise in Thunder Bluff"] = "В Мулгоре нет учителя наложения чар, иди к {n:0:horde:Mot Dawnstrider} на средний уступ Громового Утеса",
  ["{n:0:horde:Vance Undergloom} upstairs in the inn in Brill"] = "{n:0:horde:Vance Undergloom} на втором этаже таверны в Брилле",
  ["{n:0::Eaysaa Brightgust} in Valanaar, {n:0::Nasalanna Windsinger} in Shen'dar Village"] = "{n:0::Eaysaa Brightgust} в Валанааре, {n:0::Nasalanna Windsinger} в деревне Шен'дар",
  ["Stormwind City: {n:0:alliance:Betty Quin}"] = "Штормград: {n:0:alliance:Betty Quin}",
  ["Ironforge: {n:0:alliance:Thonys Pillarstone}"] = "Стальгорн: {n:0:alliance:Thonys Pillarstone}",
  ["Darnassus: {n:0:alliance:Lalina Summermoon}"] = "Дарнас: {n:0:alliance:Lalina Summermoon}",
  ["There is no Enchanting trainer in Elwynn Forest, go to {n:0:alliance:Betty Quin} in the Mage Quarter in Stormwind City"] = "В Элвиннском лесу нет учителя наложения чар, иди к {n:0:alliance:Betty Quin} в Квартал магов Штормграда",
  ["There is no Enchanting trainer in Dun Morogh, go to {n:0:alliance:Thonys Pillarstone} at the Great Forge in Ironforge"] = "В Дун Мороге нет учителя наложения чар, иди к {n:0:alliance:Thonys Pillarstone} у Великой Кузни в Стальгорне",
  ["{n:0:alliance:Alanna Raveneye} at the Oracle Glade, in the north-west of Teldrassil"] = "{n:0:alliance:Alanna Raveneye} на Поляне Оракула, на северо-западе Тельдрассила",
  ["You can find every Enchanting trainer for Horde and Alliance on my WoW Forever Enchanting Trainers page."] = "Всех учителей наложения чар Орды и Альянса ты найдешь на моей странице «WoW Forever Enchanting Trainers».",
  ["Enchanting Macro for Faster Leveling"] = "Макрос для быстрой прокачки наложения чар",
  ["I highly recommend using this macro to speed up the leveling process."] = "Очень советую использовать этот макрос, он сильно ускоряет прокачку.",
  ["This macro presses the Create button for you and confirms the prompt that asks if you want to replace the enchant already on the item, without any extra clicks."] = "Макрос нажимает за тебя кнопку «Создать» и подтверждает окно с вопросом, заменить ли чары, уже наложенные на предмет, без лишних кликов.",
  ["Macro"] = "Макрос",
  ["If you have never made a macro, type /m in the chat and press Enter, click New, give it a name and paste these two lines into it."] = "Если ты никогда не создавал макрос, введи /m в чат и нажми Enter, нажми «Создать», задай имя и вставь в него эти две строки.",
  ["How to Use"] = "Как пользоваться",
  ["Place the macro on your action bar"] = "Вынеси макрос на панель команд",
  ["Open your Enchanting profession window"] = "Открой окно профессии «Наложение чар»",
  ["Select the enchant you want to craft (make sure it's the right one)"] = "Выбери чары, которые хочешь накладывать (убедись, что выбраны нужные)",
  ["Put the item you want to enchant into the optional target slot"] = "Положи предмет, который хочешь зачаровать, в дополнительную ячейку цели",
  ["Press the macro repeatedly"] = "Нажимай макрос раз за разом",
  ["Disenchanting"] = "Распыление",
  ["You get {s:13262:inv_enchant_disenchant:Disenchant} together with Apprentice Enchanting. In WoW Forever {b}Disenchant is not in your spellbook{/b}, it's in the Enchanting box of the Professions window."] = "{s:13262:inv_enchant_disenchant:Disenchant} ты получаешь вместе с наложением чар уровня Ученик. В WoW Forever {b}Распыления нет в книге заклинаний{/b}, оно находится в блоке наложения чар в окне профессий.",
  ["If you are looking for the disenchanting table, it's in my disenchanting guide, and if you can't find the Disenchant button, the guide shows it with pictures:"] = "Если ищешь таблицу распыления, она в моем руководстве по распылению, а если не можешь найти кнопку распыления, там же она показана на картинках:",
  ["Apprentice Enchanting (1-70)"] = "Наложение чар: Ученик (1-70)",
  ["1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Copper Rod, 1 Mote of Magic"] = "1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Медный жезл, 1 Частица магии",
  ["The {i:6217:inv_misc_flute_01:Copper Rod} and the {i:247786:inv_elemental_mote_mana:Mote of Magic} are sold by the Enchanting Supply vendor near your trainer, don't buy them from the Auction House."] = "{i:6217:inv_misc_flute_01:Copper Rod} и {i:247786:inv_elemental_mote_mana:Mote of Magic} продает торговец товарами для наложения чар рядом с учителем, не покупай их на аукционе.",
  ["{b}If you are leveling in a starting zone with a low level character{/b}, you can buy the Copper Rod from a trade vendor there, but the Mote of Magic is only sold by Enchanting vendors. In the starting zones only the trainers on {b}Zephras Isle{/b} and in {b}Tirisfal Glades{/b} (Brill) sell it, everyone else has to visit the trainer in the capital city, the vendor stands right next to them."] = "{b}Если ты качаешься в стартовой зоне на персонаже низкого уровня{/b}, медный жезл можно купить у местного торговца ремесленными товарами, но Частицу магии продают только торговцы товарами для наложения чар. В стартовых зонах она есть только у учителей на {b}Острове Зефрас{/b} и в {b}Тирисфальских лесах{/b} (Брилл), всем остальным придется идти к учителю в столицу, торговец стоит прямо рядом с ним.",
  ["18x {s:7418:spell_holy_greaterheal:Enchant Bracer - Inferior Stamina} - 18 Mote of Magic"] = "18x {s:7418:spell_holy_greaterheal:Enchant Bracer - Inferior Stamina} - 18 Частица магии",
  ["Make one of these:"] = "Сделай что-то одно из этого:",
  ["50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Strange Dust"] = "50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Странная пыль",
  ["50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Lesser Magic Essence"] = "50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Малая магическая сущность",
  ["A {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} turns into 3 Lesser Magic Essence when you right-click it in your bags, so you can buy those too."] = "{i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} превращается в 3 малые магические сущности, если щелкнуть по ней правой кнопкой в сумке, так что можно покупать и их.",
  ["Journeyman Enchanting (70-150)"] = "Наложение чар: Подмастерье (70-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Enchanting. You need {b}Enchanting 50{/b} and {b}level 10{/b}:"] = "Чтобы учиться дальше 75, посети одного из этих учителей и выучи наложение чар уровня Подмастерье. Нужно {b}Наложение чар 50{/b} и {b}10-й уровень{/b}:",
  ["Orgrimmar: {n:0:horde:Godan}"] = "Оргриммар: {n:0:horde:Godan}",
  ["Undercity: {n:0:horde:Lavinia Crowe}"] = "Подгород: {n:0:horde:Lavinia Crowe}",
  ["Thunder Bluff: {n:0:horde:Teg Dawnstrider}"] = "Громовой Утес: {n:0:horde:Teg Dawnstrider}",
  ["Stormwind City: {n:0:alliance:Lucan Cordell}"] = "Штормград: {n:0:alliance:Lucan Cordell}",
  ["Ironforge: {n:0:alliance:Gimble Thistlefuzz}"] = "Стальгорн: {n:0:alliance:Gimble Thistlefuzz}",
  ["Darnassus: {n:0:alliance:Taladan}"] = "Дарнас: {n:0:alliance:Taladan}",
  ["If you bought Strange Dust pick the {b}Strange Dust{/b} tab, if you bought Lesser Magic Essence pick the {b}Lesser Magic Essence{/b} tab."] = "Если ты купил странную пыль, выбери вкладку {b}Странная пыль{/b}, если купил малые магические сущности, выбери вкладку {b}Малая магическая сущность{/b}.",
  ["Strange Dust"] = "Странная пыль",
  ["Lesser Magic Essence"] = "Малая магическая сущность",
  ["49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Lesser Magic Essence"] = "49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Малая магическая сущность",
  ["1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Silver Rod, 3 Strange Dust, 4 Lesser Magic Essence, 1 Shadowgem"] = "1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Серебряный жезл, 3 Странная пыль, 4 Малая магическая сущность, 1 Камень тени",
  ["{i:6338:inv_staff_01:Silver Rod} and every other rod in this guide (Golden, Truesilver, Arcanite) is made by Blacksmiths, you can buy them from the Auction House."] = "{i:6338:inv_staff_01:Silver Rod} и все остальные жезлы из этого руководства (золотой, из истинного серебра, арканитовый) делают кузнецы, их можно купить на аукционе.",
  ["23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Simple Wood, 46 Lesser Magic Essence"] = "23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Простая древесина, 46 Малая магическая сущность",
  ["37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Lesser Magic Essence"] = "37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Малая магическая сущность",
  ["{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} is sold by these vendors:"] = "{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} продают эти торговцы:",
  ["{n:0:horde:Kithas} in Orgrimmar"] = "{n:0:horde:Kithas} в Оргриммаре",
  ["{n:0:horde:Nata Dawnstrider} in Thunder Bluff"] = "{n:0:horde:Nata Dawnstrider} в Громовом Утесе",
  ["{n:0:horde:Leo Sarn} in Silverpine Forest"] = "{n:0:horde:Leo Sarn} в Серебряном бору",
  ["{n:0:alliance:Tilli Thistlefuzz} in Ironforge"] = "{n:0:alliance:Tilli Thistlefuzz} в Стальгорне",
  ["Buy {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} and {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need them at 150 and 200."] = "Купи у них также {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} и {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}, они понадобятся на 150 и 200.",
  ["If you don't want to get the formula, make this:"] = "Если не хочешь доставать формулу, делай вот это:",
  ["25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Strange Dust"] = "25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Странная пыль",
  ["23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Strange Dust"] = "23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Странная пыль",
  ["15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Strange Dust"] = "15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Странная пыль",
  ["9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Strange Dust"] = "9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Странная пыль",
  ["32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Strange Dust"] = "32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Странная пыль",
  ["20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Strange Dust"] = "20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Странная пыль",
  ["If 20 Soul Dust cost less than 80 Strange Dust, make this:"] = "Если 20 пылей души стоят меньше, чем 80 странной пыли, делай вот это:",
  ["20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Soul Dust."] = "20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Пыль души.",
  ["Expert Enchanting (150-225)"] = "Наложение чар: Умелец (150-225)",
  ["To train past 150, visit one of these trainers and learn Expert Enchanting. You need {b}Enchanting 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Чтобы учиться дальше 150, посети одного из этих учителей и выучи наложение чар уровня Умелец. Нужно {b}Наложение чар 125{/b} и {b}20-й уровень{/b}, стоит 50 серебра.",
  ["There is only one Expert Enchanting trainer for each faction. {n:0:horde:Hgarth} in Stonetalon Mountains at Sun Rock Retreat is the Horde trainer, he is up on the hill above the village. {n:0:alliance:Kitta Firewind} in Elwynn Forest is the Alliance trainer, she is at the top of the Tower of Azora."] = "У каждой фракции только один учитель наложения чар уровня Умелец. Учитель Орды {n:0:horde:Hgarth} находится в Когтистых горах у Приюта Солнечного Камня, на холме над деревней. Учитель Альянса {n:0:alliance:Kitta Firewind} находится в Элвиннском лесу, на вершине Башни Азоры.",
  ["1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Golden Rod, 1 Iridescent Pearl, 1 Greater Astral Essence, 1 Soul Dust"] = "1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Золотой жезл, 1 Радужная жемчужина, 1 Большая астральная сущность, 1 Пыль души",
  ["16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Soul Dust, 32 Maple Seed, 16 Leaded Vial"] = "16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Пыль души, 32 Семя клена, 16 Освинцованный флакон",
  ["{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} is sold by these vendors:"] = "{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} продают эти торговцы:",
  ["{n:0:horde:Thaddeus Webb} in Undercity"] = "{n:0:horde:Thaddeus Webb} в Подгороде",
  ["{n:0:alliance:Vaean} in Darnassus"] = "{n:0:alliance:Vaean} в Дарнасе",
  ["{n:0:alliance:Jessara Cordell} in Stormwind City"] = "{n:0:alliance:Jessara Cordell} в Штормграде",
  ["Buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need it at 200."] = "Купи у них также {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}, она понадобится на 200.",
  ["{i:17034:inv_misc_food_02:Maple Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17034:inv_misc_food_02:Maple Seed} продают торговцы реагентами, а {i:3372:inv_potion_85:Leaded Vial} торговцы алхимическими товарами.",
  ["47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Soul Dust"] = "47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Пыль души",
  ["If 2 Vision Dust cost less than 3 Soul Dust, stop the boots at 185 and make this until 200:"] = "Если 2 пыли видений стоят меньше, чем 3 пыли души, остановись с сапогами на 185 и до 200 делай вот это:",
  ["15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Vision Dust."] = "15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Пыль видений.",
  ["1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Truesilver Rod, 1 Black Pearl, 1 Greater Mystic Essence, 1 Vision Dust"] = "1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Жезл из истинного серебра, 1 Черная жемчужина, 1 Большая мистическая сущность, 1 Пыль видений",
  ["25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Vision Dust, 50 Stranglethorn Seed, 25 Leaded Vial"] = "25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Пыль видений, 50 Семя из Тернистой долины, 25 Освинцованный флакон",
  ["If you didn't buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} yet, the vendors are listed at the 151-165 step above."] = "Если ты еще не купил {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}, торговцы перечислены выше, на шаге 151-165.",
  ["{i:17035:inv_misc_food_02:Stranglethorn Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17035:inv_misc_food_02:Stranglethorn Seed} продают торговцы реагентами, а {i:3372:inv_potion_85:Leaded Vial} торговцы алхимическими товарами.",
  ["5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Vision Dust"] = "5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Пыль видений",
  ["Artisan Enchanting (225-300)"] = "Наложение чар: Мастер (225-300)",
  ["The Expert Enchanting trainers only teach you up to 225. To train Enchanting past 225 you need {b}level 35{/b} and {b}Enchanting 200{/b}, then learn Artisan Enchanting from Annora in Uldaman (I explain below how to find her). {b}She is the only trainer who teaches Artisan Enchanting.{/b}"] = "Учителя наложения чар уровня Умелец обучают только до 225. Чтобы учиться дальше 225, нужны {b}35-й уровень{/b} и {b}Наложение чар 200{/b}, после чего выучи наложение чар уровня Мастер у Анноры в Ульдамане (ниже я объясню, как ее найти). {b}Она единственный учитель, который обучает наложению чар уровня Мастер.{/b}",
  ["There are a few recipes only Annora teaches, {b}so bring enough gold to learn every recipe and enough materials to reach Enchanting 250{/b}, otherwise you have to go back to Uldaman for the higher recipes. Around 50 {i:11137:inv_enchant_dustvision:Vision Dust} gets you to 250."] = "Некоторым рецептам обучает только Аннора, {b}так что возьми достаточно золота, чтобы выучить все рецепты, и достаточно материалов, чтобы дойти до Наложения чар 250{/b}, иначе за высокими рецептами придется возвращаться в Ульдаман. Примерно 50 {i:11137:inv_enchant_dustvision:Vision Dust} хватит, чтобы дойти до 250.",
  ["How to enter Uldaman"] = "Как попасть в Ульдаман",
  ["Uldaman is in the Badlands and it has two entrances, use the back entrance. You can't solo it at level 35, so go with a party or ask a level 60 to help."] = "Ульдаман находится в Бесплодных землях, у него два входа, используй задний. На 35-м уровне соло его не пройти, так что иди с группой или попроси помочь персонажа 60-го уровня.",
  ["How to find Annora"] = "Как найти Аннору",
  ["Annora only spawns once you {b}kill every mob in the area she is in!{/b}"] = "Аннора появляется, только когда ты {b}убьешь всех монстров в ее области!{/b}",
  ["{b}Don't forget to learn everything from Annora before you leave Uldaman!{/b} The recipes from 230 up are taught nowhere else."] = "{b}Не забудь выучить у Анноры все, прежде чем покинуть Ульдаман!{/b} Рецептам от 230 и выше больше нигде не обучают.",
  ["Recipe"] = "Рецепт",
  ["Skill"] = "Навык",
  ["Cost"] = "Цена",
  ["{b}Artisan Enchanting{/b}"] = "{b}Наложение чар: Мастер{/b}",
  ["37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Vision Dust"] = "37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Пыль видений",
  ["20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Dream Dust, 20 Purple Lotus, 20 Crystal Vial"] = "20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Пыль грез, 20 Лиловый лотос, 20 Хрустальный флакон",
  ["{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} is sold by {n:0::Kania} in Silithus, she is upstairs in the inn. {i:8925:inv_potion_86:Crystal Vial} is sold by {n:0::Mishta} in Silithus or any Alchemy Supply vendor."] = "{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} продает {n:0::Kania} в Силитусе, она на втором этаже таверны. {i:8925:inv_potion_86:Crystal Vial} продает {n:0::Mishta} в Силитусе или любой торговец алхимическими товарами.",
  ["If you don't have Purple Lotus, make {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} instead (1 Dream Dust, 2 Lesser Nether Essence each), Annora teaches it."] = "Если у тебя нет лилового лотоса, делай вместо этого {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} (по 1 пыли грез и 2 малые сущности пустоты), ему обучает Аннора.",
  ["40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Dream Dust"] = "40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Пыль грез",
  ["{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} is sold by {n:0:horde:Daniel Bartlett} in Undercity and {n:0:alliance:Mythrin'dir} in Darnassus. It's bind on pickup, so don't buy it on an alt."] = "{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} продают {n:0:horde:Daniel Bartlett} в Подгороде и {n:0:alliance:Mythrin'dir} в Дарнасе. Она становится персональной при получении, так что не покупай ее на твинке.",
  ["From 290 you can make the Runed Arcanite Rod, see the next step."] = "С 290 можно сделать Рунический арканитовый жезл, смотри следующий шаг.",
  ["1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Arcanite Rod, 1 Golden Pearl, 10 Illusion Dust, 4 Greater Eternal Essence, 4 Small Brilliant Shard, 2 Large Brilliant Shard"] = "1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Арканитовый жезл, 1 Золотая жемчужина, 10 Пыль иллюзий, 4 Великая сущность вечности, 4 Маленький сверкающий осколок, 2 Большой сверкающий осколок",
  ["{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} is sold by {n:0::Lorelae Wintersong} in Moonglade at Nighthaven."] = "{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} продает {n:0::Lorelae Wintersong} на Лунной поляне в Ночной Гавани.",
  ["{b}You need this rod for some recipes from 290 and for most recipes at 300{/b}, Crusader for example. You can make it from 290, but if you don't need it yet, you can make it later and make one more Shield for the last point instead."] = "{b}Этот жезл нужен для некоторых рецептов с 290 и для большинства рецептов на 300{/b}, например для Рыцаря. Сделать его можно с 290, но если он пока не нужен, сделай его позже, а последнее очко возьми еще одним щитом.",
  ["This WoW Forever Engineering leveling guide will show you the fastest and cheapest way to level your Engineering skill from 1 to 300. You will also find every trainer location and where to train Engineering past 75, 150 and 225."] = "Это руководство по прокачке инженерного дела для WoW Forever покажет тебе самый быстрый и дешевый способ поднять навык инженерного дела с 1 до 300. Здесь же ты найдешь всех учителей и узнаешь, где учиться инженерному делу после 75, 150 и 225.",
  ["Engineering is best combined with Mining, because almost everything you make needs stone and bars, and you can mine both. If you don't have Mining, you have to buy everything from the Auction House. Below you will find the shopping list, the Engineering trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "Инженерное дело лучше всего сочетать с горным делом: почти для всего нужны камни и слитки, а их можно добывать самому. Без горного дела все придется покупать на аукционе. Ниже ты найдешь список покупок, учителей инженерного дела по стартовым зонам и столицам, а также самые дешевые рецепты для каждого диапазона навыка.",
  ["Engineering Trainer Locations"] = "Где найти учителей инженерного дела",
  ["Apprentice Engineering has no level requirement in Forever, so you can learn it on a fresh character."] = "В Forever у инженерного дела уровня Ученик нет требований к уровню, так что его можно выучить новым персонажем.",
  ["There is no Engineering trainer in Thunder Bluff and Darnassus, the other four capitals have one. You can also ask a guard, then it will be marked with a red flag on your map."] = "В Громовом Утесе и Дарнасе нет учителя инженерного дела, в остальных четырех столицах он есть. Можно также спросить стражника, и тогда учитель будет отмечен красным флажком на карте.",
  ["Orgrimmar: {n:0:horde:Thund}"] = "Оргриммар: {n:0:horde:Thund}",
  ["Undercity: {n:0:horde:Graham Van Talen}"] = "Подгород: {n:0:horde:Graham Van Talen}",
  ["{n:0:horde:Mukdrak} in Razor Hill, near the forge next to the road to Orgrimmar"] = "{n:0:horde:Mukdrak} в Колючем Холме, у кузни рядом с дорогой на Оргриммар",
  ["{n:0::Twizwick Sprocketgrind} on the plateau above the Venture Co. Mine, hard to reach at low level. There is no anvil near him and nobody there sells the Blacksmith Hammer, so it's probably best to go to {n:0:horde:Thund} in Orgrimmar instead."] = "{n:0::Twizwick Sprocketgrind} на плато над рудником Торговой Компании, на низком уровне туда трудно добраться. Рядом с ним нет наковальни, и никто поблизости не продает кузнечный молот, так что, наверное, лучше пойти к {n:0:horde:Thund} в Оргриммар.",
  ["There is no Engineering trainer in Tirisfal Glades, go to {n:0:horde:Graham Van Talen} in the Rogues' Quarter in Undercity"] = "В Тирисфальских лесах нет учителя инженерного дела, иди к {n:0:horde:Graham Van Talen} в Квартал разбойников Подгорода",
  ["{n:0::Strange Hermit} in Shadowgale Forest"] = "{n:0::Strange Hermit} в Лесу Шедоугейл",
  ["Stormwind City: {n:0:alliance:Sprite Jumpsprocket}"] = "Штормград: {n:0:alliance:Sprite Jumpsprocket}",
  ["Ironforge: {n:0:alliance:Jemma Quikswitch}"] = "Стальгорн: {n:0:alliance:Jemma Quikswitch}",
  ["There is no Engineering trainer in Elwynn Forest, go to {n:0:alliance:Sprite Jumpsprocket} in the Dwarven District in Stormwind City"] = "В Элвиннском лесу нет учителя инженерного дела, иди к {n:0:alliance:Sprite Jumpsprocket} в Квартал дворфов Штормграда",
  ["{n:0:alliance:Bronk Guzzlegear} at Steelgrill's Depot"] = "{n:0:alliance:Bronk Guzzlegear} в Депо Сталежара",
  ["There is no Engineering trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Jenna Lemkenilli} in Auberdine in Darkshore"] = "В Тельдрассиле и Дарнасе нет учителя инженерного дела, ближайший из них {n:0:alliance:Jenna Lemkenilli} в Аубердине на Темных берегах",
  ["You can find every Engineering trainer for Horde and Alliance on my WoW Forever Engineering Trainers page."] = "Всех учителей инженерного дела Орды и Альянса ты найдешь на моей странице «WoW Forever Engineering Trainers».",
  ["Apprentice Engineering (1-50)"] = "Инженерное дело: Ученик (1-50)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer}, most recipes need it. {b}Most trainers{/b} have a Blacksmithing or Engineering Supply vendor nearby that sells it, {b}except{/b} the trainers in Dun Morogh and on Zephras Isle. In Dun Morogh buy it in Kharanos from {n:0:alliance:Thrawn Boltar}, on Zephras Isle in Shen'dar Village from {n:0::Aedi Thriceforged}."] = "Купи {i:5956:inv_hammer_20:Blacksmith Hammer}, он нужен для большинства рецептов. {b}У большинства учителей{/b} рядом есть торговец кузнечными или инженерными товарами, который его продает, {b}кроме{/b} учителей в Дун Мороге и на Острове Зефрас. В Дун Мороге купи его в Караносе у {n:0:alliance:Thrawn Boltar}, на Острове Зефрас в деревне Шен'дар у {n:0::Aedi Thriceforged}.",
  ["The {b}Gnome{/b} racial changed in Forever. Instead of +15 Engineering skill, Engineering Specialization now makes your devices fail or backfire 20% less often, so Gnomes level Engineering exactly like everyone else."] = "В Forever изменили расовую способность {b}гномов{/b}. Вместо +15 к навыку инженерного дела «Инженерная специализация» теперь на 20% снижает шанс отказа или осечки твоих устройств, так что гномы качают инженерное дело точно так же, как все остальные.",
  ["66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Rough Stone"] = "66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Грубый камень",
  ["Keep all of them, you need 66 for the bombs at 51."] = "Сохрани все, 66 штук понадобятся для бомб на 51.",
  ["33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Copper Bar"] = "33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Медный слиток",
  ["Keep these too, you will need all 33 for the bombs."] = "Их тоже сохрани, все 33 понадобятся для бомб.",
  ["1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Copper Bar"] = "1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Медный слиток",
  ["You will use this to craft Engineering recipes, so keep it."] = "Он нужен для изготовления инженерных рецептов, так что сохрани его.",
  ["Journeyman Engineering (50-150)"] = "Инженерное дело: Подмастерье (50-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Engineering. You need {b}Engineering 50{/b} and {b}level 10{/b}:"] = "Чтобы учиться дальше 75, посети одного из этих учителей и выучи инженерное дело уровня Подмастерье. Нужно {b}Инженерное дело 50{/b} и {b}10-й уровень{/b}:",
  ["Orgrimmar: {n:0:horde:Nogg}"] = "Оргриммар: {n:0:horde:Nogg}",
  ["Undercity: {n:0:horde:Franklin Lloyd}"] = "Подгород: {n:0:horde:Franklin Lloyd}",
  ["Stormwind City: {n:0:alliance:Lilliam Sparkspindle}"] = "Штормград: {n:0:alliance:Lilliam Sparkspindle}",
  ["Ironforge: {n:0:alliance:Trixie Quikswitch}"] = "Стальгорн: {n:0:alliance:Trixie Quikswitch}",
  ["Duskwood: {n:0:alliance:Finbus Geargrind}"] = "Сумеречный лес: {n:0:alliance:Finbus Geargrind}",
  ["33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Copper Bar, 33 Handful of Copper Bolts, 66 Rough Blasting Powder, 33 Linen Cloth"] = "33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Медный слиток, 33 Горсть медных болтов, 66 Грубое взрывчатое вещество, 33 Льняной материал",
  ["{b}It's possible that you reach further than 75 with these{/b}, so it's best not to afk craft them unless you already learned Journeyman Engineering. Either make sure you learn it first, or just don't afk craft them. (Depends on luck, sometimes you don't even reach 75.)"] = "{b}С ними можно подняться выше 75{/b}, так что лучше не делать их в АФК, если ты еще не выучил уровень Подмастерье. Либо сначала выучи его, либо просто не делай их в АФК. (Зависит от удачи, иногда не доходишь даже до 75.)",
  ["60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Coarse Stone"] = "60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Шершавый камень",
  ["Keep them, you will need all 60 for the dynamite at 90."] = "Сохрани их, все 60 понадобятся для динамита на 90.",
  ["20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Coarse Blasting Powder, 20 Linen Cloth"] = "20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Простое взрывчатое вещество, 20 Льняной материал",
  ["5x {s:3973:inv_ingot_04:Silver Contact} - 5 Silver Bar"] = "5x {s:3973:inv_ingot_04:Silver Contact} - 5 Серебряный слиток",
  ["If Silver Bar is expensive, make this instead:"] = "Если серебряные слитки дорогие, делай вместо этого:",
  ["5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Light Leather, 10 Tigerseye."] = "5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Легкая кожа, 10 Тигровый глаз.",
  ["25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Bronze Bar, 25 Weak Flux"] = "25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Бронзовый слиток, 25 Слабый флюс",
  ["Keep 10 of them, you will need them at 125."] = "Сохрани 10 штук, они понадобятся на 125.",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} is sold by Engineering Supply vendors near your trainer."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} продают торговцы инженерными товарами рядом с учителем.",
  ["If you end up a few points short of 125, don't make more tubes, just start the scopes."] = "Если до 125 не хватит нескольких очков, не делай больше трубок, просто начинай делать прицелы.",
  ["10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Bronze Tube, 10 Moss Agate"] = "10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Бронзовая трубка, 10 Моховой агат",
  ["Start making {s:3945:inv_misc_dust_06:Heavy Blasting Powder} instead if you don't have any Moss Agate, or it's really expensive."] = "Если мохового агата у тебя нет или он очень дорогой, начинай вместо этого делать {s:3945:inv_misc_dust_06:Heavy Blasting Powder}.",
  ["Make both of these:"] = "Сделай и то, и другое:",
  ["30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Heavy Stone"] = "30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Тяжелый камень",
  ["15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Bronze Bar, 15 Wool Cloth"] = "15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Бронзовый слиток, 15 Шерсть",
  ["{b}Make sure to make them in the same order.{/b} You need both for the sheep at 160, so make them now and you should reach 150 with them."] = "{b}Делай их обязательно в этом порядке.{/b} Оба понадобятся для овец на 160, так что сделай их сейчас, и ты должен дойти с ними до 150.",
  ["Expert Engineering (150-200)"] = "Инженерное дело: Умелец (150-200)",
  ["To train past 150, visit {n:0:horde:Roxxik} in Orgrimmar (Horde) or {n:0:alliance:Springspindle Fizzlegear} in Ironforge (Alliance) and learn Expert Engineering. You need {b}Engineering 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Чтобы учиться дальше 150, посети {n:0:horde:Roxxik} в Оргриммаре (Орда) или {n:0:alliance:Springspindle Fizzlegear} в Стальгорне (Альянс) и выучи инженерное дело уровня Умелец. Нужно {b}Инженерное дело 125{/b} и {b}20-й уровень{/b}, стоит 50 серебра.",
  ["15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Bronze Bar, 15 Medium Leather, 15 Wool Cloth"] = "15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Бронзовый слиток, 15 Средняя кожа, 15 Шерсть",
  ["Keep these too, you will need all 15 for the sheep."] = "Их тоже сохрани, все 15 понадобятся для овец.",
  ["The 15 will probably take you past 160, that's fine."] = "Скорее всего, эти 15 поднимут тебя выше 160, это нормально.",
  ["15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Heavy Blasting Powder, 15 Whirring Bronze Gizmo, 15 Bronze Framework, 30 Wool Cloth"] = "15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Тяжелое взрывчатое вещество, 15 Жужжащая бронзовая штуковина, 15 Бронзовый каркас, 30 Шерсть",
  ["Keep 5 of them, you might need them if you choose Goblin Engineering at 200."] = "Сохрани 5 штук, они могут понадобиться, если на 200 выберешь гоблинскую инженерию.",
  ["60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Solid Stone"] = "60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Твердый камень",
  ["Save these, you will need them later."] = "Сохрани их, они понадобятся позже.",
  ["1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Steel Bar"] = "1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Стальной слиток",
  ["Keep this, you will need it to craft some of the Engineering recipes."] = "Сохрани его, он нужен для изготовления некоторых инженерных рецептов.",
  ["If you were unlucky with the skill points and didn't reach 195, craft a few {s:3962:inv_misc_bomb_08:Iron Grenade} or any other recipe that gives skill points."] = "Если с очками навыка не повезло и ты не дошел до 195, сделай несколько {s:3962:inv_misc_bomb_08:Iron Grenade} или любой другой рецепт, который дает очки навыка.",
  ["6x {s:12589:inv_musket_01:Mithril Tube} - 18 Mithril Bar"] = "6x {s:12589:inv_musket_01:Mithril Tube} - 18 Мифриловый слиток",
  ["Keep all 6, you might need them if you choose Gnomish Engineering at 200."] = "Сохрани все 6, они могут понадобиться, если на 200 выберешь гномскую инженерию.",
  ["Engineering Specializations"] = "Специализации инженерного дела",
  ["At {b}Engineering 200{/b} and {b}level 30{/b}, you can specialize in Gnomish or Goblin Engineering. Some items require a specific specialization to use, while other items are crafted by one specialization but are usable by any engineer. Fortunately, most recipes that are crafted by one specialization can be used by both."] = "На {b}Инженерном деле 200{/b} и {b}30-м уровне{/b} можно выбрать специализацию: гномская или гоблинская инженерия. Некоторыми предметами может пользоваться только инженер с определенной специализацией, а другие делает одна специализация, но пользоваться ими может любой инженер. К счастью, большинством рецептов одной специализации могут пользоваться обе.",
  ["For information on how to choose a specialization, please see my separate guide:"] = "О том, как выбрать специализацию, читай в моем отдельном руководстве:",
  ["Artisan Engineering (200-300)"] = "Инженерное дело: Мастер (200-300)",
  ["To train Engineering past 225 you need {b}Engineering 200{/b} and {b}level 35{/b}, then learn Artisan Engineering from {n:0::Buzzek Bracketswing} in Tanaris at Gadgetzan, he is right outside the inn near the mailbox. He also teaches the recipes above 200, so go there as soon as you reach 200."] = "Чтобы учиться инженерному делу дальше 225, нужны {b}Инженерное дело 200{/b} и {b}35-й уровень{/b}, после чего выучи инженерное дело уровня Мастер у {n:0::Buzzek Bracketswing} в Прибамбасске в Танарисе, он стоит прямо у таверны рядом с почтовым ящиком. Он же обучает рецептам выше 200, так что иди к нему, как только дойдешь до 200.",
  ["20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Mithril Bar, 20 Mageweave Cloth, 20 Solid Blasting Powder"] = "20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Мифриловый слиток, 20 Магическая ткань, 20 Твердое взрывчатое вещество",
  ["Keep them, you will need all 20 for the bombs at 238."] = "Сохрани их, все 20 понадобятся для бомб на 238.",
  ["40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Mithril Bar"] = "40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Мифриловый слиток",
  ["Keep these too, you will need 40 for the bombs."] = "Их тоже сохрани, 40 штук понадобятся для бомб.",
  ["20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 Mithril Casing, 20 Unstable Trigger, 40 Solid Blasting Powder"] = "20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 Мифриловый кожух, 20 Нестабильный спусковой механизм, 40 Твердое взрывчатое вещество",
  ["44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Dense Stone"] = "44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Плотный камень",
  ["35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Thorium Bar, 35 Runecloth"] = "35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Ториевый слиток, 35 Руническая ткань",
  ["{i:16042:inv_scroll_03:Schematic: Thorium Widget} is sold by {n:0:horde:Sovik} in Orgrimmar and {n:0:alliance:Gearcutter Cogspinner} in Ironforge."] = "{i:16042:inv_scroll_03:Schematic: Thorium Widget} продают {n:0:horde:Sovik} в Оргриммаре и {n:0:alliance:Gearcutter Cogspinner} в Стальгорне.",
  ["20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Thorium Bar"] = "20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Ториевый слиток",
  ["{i:16047:inv_scroll_03:Schematic: Thorium Tube} is sold by {n:0::Xizzer Fizzbolt} in Winterspring at Everlook, in the first building on the right after the gate. It's bind on pickup in Forever, so buy it with the character that levels Engineering."] = "{i:16047:inv_scroll_03:Schematic: Thorium Tube} продает {n:0::Xizzer Fizzbolt} в Круговзоре в Зимних Ключах, в первом здании справа за воротами. В Forever она становится персональной при получении, так что покупай ее тем персонажем, который качает инженерное дело.",
  ["This WoW Forever Leatherworking leveling guide will show you the fastest and cheapest way to level your Leatherworking skill from 1 to 300. You will also find every trainer location and where to train Leatherworking past 75, 150 and 225."] = "Это руководство по прокачке кожевничества для WoW Forever покажет тебе самый быстрый и дешевый способ поднять навык кожевничества с 1 до 300. Здесь же ты найдешь всех учителей и узнаешь, где учиться кожевничеству после 75, 150 и 225.",
  ["Below you will find the full shopping list, the Leatherworking trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Leatherworking is best combined with Skinning because leather is most of the cost, but you can also buy everything in the guide from the Auction House."] = "Ниже ты найдешь полный список покупок, учителей кожевничества по стартовым зонам и столицам, а также самые дешевые рецепты для каждого диапазона навыка от Ученика до Мастера. Кожевничество лучше всего сочетать со снятием шкур, ведь кожа составляет большую часть затрат, но все из этого руководства можно купить и на аукционе.",
  ["When a recipe is yellow or green, a craft doesn't always give you a skill point, so nobody can tell exactly how many materials you will need. That's why the counts that depend a lot on luck are a range. {b}With the bigger number 9 out of 10 players have enough, with the smaller one it's 50/50.{/b} If you buy the smaller number, be ready to buy more later."] = "Когда рецепт желтый или зеленый, изготовление не всегда дает очко навыка, поэтому никто не может точно сказать, сколько материалов понадобится. Вот почему количество, которое сильно зависит от удачи, указано диапазоном. {b}С большим числом хватит 9 игрокам из 10, с меньшим шансы 50/50.{/b} Если покупаешь меньшее количество, будь готов докупить позже.",
  ["Material"] = "Материал",
  ["Leatherworking Trainer Locations"] = "Где найти учителей кожевничества",
  ["Apprentice Leatherworking has no level requirement in Forever, so you can learn it on a fresh character."] = "В Forever у кожевничества уровня Ученик нет требований к уровню, так что его можно выучить новым персонажем.",
  ["Orgrimmar: {n:0:horde:Kamari}"] = "Оргриммар: {n:0:horde:Kamari}",
  ["Undercity: {n:0:horde:Dan Golthas}"] = "Подгород: {n:0:horde:Dan Golthas}",
  ["Thunder Bluff: {n:0:horde:Mak}"] = "Громовой Утес: {n:0:horde:Mak}",
  ["There is no Leatherworking trainer in Durotar, go to {n:0:horde:Kamari} in the Drag in Orgrimmar"] = "В Дуротаре нет учителя кожевничества, иди к {n:0:horde:Kamari} на Волок в Оргриммаре",
  ["{n:0:horde:Chaw Stronghide} in Bloodhoof Village"] = "{n:0:horde:Chaw Stronghide} в деревне Кровавого Копыта",
  ["{n:0:horde:Shelene Rhobart} at the road junction southeast of Brill"] = "{n:0:horde:Shelene Rhobart} на развилке дорог к юго-востоку от Брилла",
  ["{n:0::Emerii Tallgust} in Valanaar, {n:0::Indari Sunseam} in Shen'dar Village"] = "{n:0::Emerii Tallgust} в Валанааре, {n:0::Indari Sunseam} в деревне Шен'дар",
  ["Stormwind City: {n:0:alliance:Randal Worth}"] = "Штормград: {n:0:alliance:Randal Worth}",
  ["Ironforge: {n:0:alliance:Gretta Finespindle}"] = "Стальгорн: {n:0:alliance:Gretta Finespindle}",
  ["Darnassus: {n:0:alliance:Darianna}"] = "Дарнас: {n:0:alliance:Darianna}",
  ["{n:0:alliance:Adele Fielder} in the small house by Crystal Lake, northeast of Goldshire"] = "{n:0:alliance:Adele Fielder} в маленьком доме у Хрустального озера, к северо-востоку от Златоземья",
  ["There is no Leatherworking trainer in Dun Morogh, go to {n:0:alliance:Gretta Finespindle} at the Great Forge in Ironforge"] = "В Дун Мороге нет учителя кожевничества, иди к {n:0:alliance:Gretta Finespindle} у Великой Кузни в Стальгорне",
  ["{n:0:alliance:Nadyia Maneweaver} in the small house near the road to Darnassus"] = "{n:0:alliance:Nadyia Maneweaver} в маленьком доме у дороги в Дарнас",
  ["You can find every Leatherworking trainer for Horde and Alliance on my WoW Forever Leatherworking Trainers page."] = "Всех учителей кожевничества Орды и Альянса ты найдешь на моей странице «WoW Forever Leatherworking Trainers».",
  ["Apprentice Leatherworking (1-55)"] = "Кожевничество: Ученик (1-55)",
  ["35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Ruined Leather Scraps"] = "35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Обрывки испорченной кожи",
  ["27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Light Hide, 27 Salt"] = "27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Легкая шкура, 27 Соль",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Leatherworking Supply vendor nearby that sells the threads, dyes, and salt, {b}except{/b} the trainers in Elwynn Forest and Tirisfal Glades. For those, buy the Salt and Coarse Thread in Goldshire from {n:0:alliance:Tharynn Bouden} or in Brill from {n:0:horde:Abigail Shiel}."] = "{b}ПРИМЕЧАНИЕ:{/b} {b}У большинства учителей{/b} рядом есть торговец кожевенными товарами, который продает нитки, красители и соль, {b}кроме{/b} учителей в Элвиннском лесу и Тирисфальских лесах. В этом случае купи соль и грубую нить в Златоземье у {n:0:alliance:Tharynn Bouden} или в Брилле у {n:0:horde:Abigail Shiel}.",
  ["Keep 24 of the hides, you will need them for the Light Leather Pants at 100."] = "Сохрани 24 шкуры, они понадобятся для Штанов из легкой кожи на 100.",
  ["Alternative recipes"] = "Альтернативные рецепты",
  ["If you farm your own leather and don't have 27 Light Hides, make Light Armor Kits until 45, then Embossed Leather Gloves until 55:"] = "Если ты сам добываешь кожу и у тебя нет 27 легких шкур, делай Легкие накладки для доспехов до 45, а затем Тисненые кожаные перчатки до 55:",
  ["24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Light Leather"] = "24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Легкая кожа",
  ["10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Light Leather, 20 Coarse Thread"] = "10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Легкая кожа, 20 Грубая нить",
  ["You still need 24 Cured Light Hide for the Light Leather Pants at 100, so keep the Light Hides you skin until then."] = "Для Штанов из легкой кожи на 100 все равно понадобятся 24 выделанные легкие шкуры, так что до того момента сохраняй легкие шкуры, которые снимаешь.",
  ["Journeyman Leatherworking (55-130)"] = "Кожевничество: Подмастерье (55-130)",
  ["To train past 75, visit one of these trainers and learn Journeyman Leatherworking. You need {b}Leatherworking 50{/b} and {b}level 10{/b}:"] = "Чтобы учиться дальше 75, посети одного из этих учителей и выучи кожевничество уровня Подмастерье. Нужно {b}Кожевничество 50{/b} и {b}10-й уровень{/b}:",
  ["Orgrimmar: {n:0:horde:Karolek}"] = "Оргриммар: {n:0:horde:Karolek}",
  ["Undercity: {n:0:horde:Arthur Moore}"] = "Подгород: {n:0:horde:Arthur Moore}",
  ["Thunder Bluff: {n:0:horde:Tarn}"] = "Громовой Утес: {n:0:horde:Tarn}",
  ["Stormwind City: {n:0:alliance:Simon Tanner}"] = "Штормград: {n:0:alliance:Simon Tanner}",
  ["Ironforge: {n:0:alliance:Fimble Finespindle}"] = "Стальгорн: {n:0:alliance:Fimble Finespindle}",
  ["Darnassus: {n:0:alliance:Faldron}"] = "Дарнас: {n:0:alliance:Faldron}",
  ["21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Light Leather, 42 Coarse Thread"] = "21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Легкая кожа, 42 Грубая нить",
  ["8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Light Leather"] = "8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Легкая кожа",
  ["10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Medium Hide, 10 Salt"] = "10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Средняя шкура, 10 Соль",
  ["Keep the Cured Medium Hides, you will need them for the Dark Leather Belts at 115."] = "Сохрани выделанные средние шкуры, они понадобятся для Поясов из темной кожи на 115.",
  ["19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Light Leather, 38 Coarse Thread"] = "19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Легкая кожа, 38 Грубая нить",
  ["Keep 10 of the belts for the Dark Leather Belts at 115."] = "Сохрани 10 поясов для Поясов из темной кожи на 115.",
  ["24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Light Leather, 24 Cured Light Hide, 24 Fine Thread"] = "24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Легкая кожа, 24 Выделанная легкая шкура, 24 Тонкая нить",
  ["10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Fine Leather Belt, 10 Cured Medium Hide, 20 Fine Thread, 10 Gray Dye"] = "10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Пояс из тонкой кожи, 10 Выделанная средняя шкура, 20 Тонкая нить, 10 Серый краситель",
  ["7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Medium Leather"] = "7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Средняя кожа",
  ["Expert Leatherworking (130-205)"] = "Кожевничество: Умелец (130-205)",
  ["To train past 150, visit {n:0:horde:Una} in Thunder Bluff (Horde) or {n:0:alliance:Telonis} in Darnassus (Alliance) and learn Expert Leatherworking. You need {b}Leatherworking 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Чтобы учиться дальше 150, посети {n:0:horde:Una} в Громовом Утесе (Орда) или {n:0:alliance:Telonis} в Дарнасе (Альянс) и выучи кожевничество уровня Умелец. Нужно {b}Кожевничество 125{/b} и {b}20-й уровень{/b}, стоит 50 серебра.",
  ["30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Heavy Hide, 90 Salt"] = "30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Тяжелая шкура, 90 Соль",
  ["Keep the Cured Heavy Hides, you will need 10 for the Barbaric Shoulders at 155 and 20 for the Guardian Gloves at 165."] = "Сохрани выделанные тяжелые шкуры: 10 понадобятся для Варварских наплечников на 155 и 20 для Перчаток стража на 165.",
  ["17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Medium Leather, 68 Fine Thread"] = "17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Средняя кожа, 68 Тонкая нить",
  ["10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Heavy Leather, 10 Cured Heavy Hide, 20 Fine Thread"] = "10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Толстая кожа, 10 Выделанная тяжелая шкура, 20 Тонкая нить",
  ["20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Heavy Leather, 20 Cured Heavy Hide, 20 Silken Thread"] = "20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Толстая кожа, 20 Выделанная тяжелая шкура, 20 Шелковая нить",
  ["22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Thick Leather, 44 Silken Thread"] = "22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Плотная кожа, 44 Шелковая нить",
  ["Leatherworking Specializations"] = "Специализации кожевничества",
  ["Once you reach {b}Leatherworking 225{/b} and {b}level 40{/b}, you can choose one of the three Leatherworking specializations: Dragonscale, Elemental, or Tribal. Each specialization gives access to a specific set of patterns."] = "Когда достигнешь {b}Кожевничества 225{/b} и {b}40-го уровня{/b}, можно выбрать одну из трех специализаций кожевничества: драконья чешуя, сила стихий или традиции предков. Каждая специализация открывает свой набор выкроек.",
  ["Dragonscale - Mail-type gear"] = "Драконья чешуя - кольчужное снаряжение",
  ["Elemental - elemental resistance and Leather-type agility gear"] = "Сила стихий - снаряжение с сопротивлением стихиям и кожаное снаряжение на ловкость",
  ["Tribal - Leather-type intellect & agility gear and the Devilsaur Armor set"] = "Традиции предков - кожаное снаряжение на интеллект и ловкость и комплект доспехов девизавра",
  ["For information on how to become a Dragonscale, Elemental, or Tribal Leatherworker, please see my separate guides:"] = "О том, как стать кожевником драконьей чешуи, силы стихий или традиций предков, читай в моих отдельных руководствах:",
  ["Artisan Leatherworking (205-300)"] = "Кожевничество: Мастер (205-300)",
  ["To train past 225, visit {n:0:horde:Hahrana Ironhide} in Camp Mojache, Feralas (Horde) or {n:0:alliance:Drakk Stonehand} in Aerie Peak, The Hinterlands (Alliance) and learn Artisan Leatherworking. You need {b}Leatherworking 200{/b} and {b}level 35{/b}."] = "Чтобы учиться дальше 225, посети {n:0:horde:Hahrana Ironhide} в Лагере Мохаче в Фераласе (Орда) или {n:0:alliance:Drakk Stonehand} в Орлином Гнезде во Внутренних землях (Альянс) и выучи кожевничество уровня Мастер. Нужно {b}Кожевничество 200{/b} и {b}35-й уровень{/b}.",
  ["36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Thick Leather, 144 Silken Thread"] = "36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Плотная кожа, 144 Шелковая нить",
  ["{b}The Expert trainers in Thunder Bluff and Darnassus don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}Учителя уровня Умелец в Громовом Утесе и Дарнасе не обучают этому рецепту{/b}, его можно выучить только у двух учителей выше.",
  ["I recommend these over the Nightscape Boots because they sell for more to a vendor, so they end up cheaper."] = "Советую их вместо Сапог ночного неба: торговцу они продаются дороже, так что в итоге выходят дешевле.",
  ["36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Rugged Leather, 36 Black Dye, 36 Rune Thread"] = "36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Грубая кожа, 36 Черный краситель, 36 Руническая нить",
  ["The pattern is sold by {n:0:horde:Werg Thickblade} in Tirisfal Glades (Horde) and {n:0:alliance:Leonard Porter} in Western Plaguelands (Alliance)."] = "Выкройку продают {n:0:horde:Werg Thickblade} в Тирисфальских лесах (Орда) и {n:0:alliance:Leonard Porter} в Западных Чумных землях (Альянс).",
  ["Blue Suede Shoes use the same leather but sell for more to a vendor, so they save you about 13 gold on this step. If the pattern costs less than that on the Auction House, make these instead:"] = "Синие замшевые туфли делаются из той же кожи, но торговцу продаются дороже, так что на этом шаге сэкономят тебе около 13 золота. Если выкройка на аукционе стоит меньше, делай вместо этого:",
  ["36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Rugged Leather, 36 Blue Dye, 36 Rune Thread."] = "36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Грубая кожа, 36 Синий краситель, 36 Руническая нить.",
  ["53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Rugged Leather, 530 Runecloth, 53 Rune Thread"] = "53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Грубая кожа, 530 Руническая ткань, 53 Руническая нить",
  ["The pattern is sold by {n:0::Jase Farlane} at Light's Hope Chapel in Eastern Plaguelands."] = "Выкройку продает {n:0::Jase Farlane} у Часовни Последней Надежды в Восточных Чумных землях.",
  ["If you have the pattern, make these from 275 instead:"] = "Если у тебя есть выкройка, делай вместо этого начиная с 275:",
  ["27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Rugged Leather, 27 Blue Dye, 27 Rune Thread."] = "27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Грубая кожа, 27 Синий краситель, 27 Руническая нить.",
  ["Blue Suede Hat"] = "Синяя замшевая шляпа",
  ["{b}Someone with Leatherworking 300 has to place the Sewing Machine for you.{/b} You can't place a Sewing Machine yourself before 300, even if you buy one. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}Швейную машину для тебя должен поставить кто-то с Кожевничеством 300.{/b} До 300 поставить швейную машину самому нельзя, даже если ты ее купишь. Не уверен, что это не недосмотр Blizzard, так что это могут изменить.",
  ["If you can use one and have the pattern, you can make these from 280:"] = "Если у тебя есть доступ к машине и выкройка, можешь делать это начиная с 280:",
  ["20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Rugged Leather, 80 Blue Dye, 20 Rune Thread."] = "20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Грубая кожа, 80 Синий краситель, 20 Руническая нить.",
  ["This WoW Forever Tailoring leveling guide will show you the fastest and cheapest way to level your Tailoring skill from 1 to 300. You will also find every trainer location and where to train Tailoring past 75, 150 and 225."] = "Это руководство по прокачке портняжного дела для WoW Forever покажет тебе самый быстрый и дешевый способ поднять навык портняжного дела с 1 до 300. Здесь же ты найдешь всех учителей и узнаешь, где учиться портняжному делу после 75, 150 и 225.",
  ["Below you will find the full shopping list, the Tailoring trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Tailoring uses cloth as its main material, but cloth drops from humanoids, so you don't need a gathering profession and you can combine Tailoring with anything. Enchanting is a popular choice because you can disenchant the things you make while leveling and use the dust to level Enchanting."] = "Ниже ты найдешь полный список покупок, учителей портняжного дела по стартовым зонам и столицам, а также самые дешевые рецепты для каждого диапазона навыка от Ученика до Мастера. Основной материал портного - ткань, а она падает с гуманоидов, так что собирательская профессия не нужна и портняжное дело можно сочетать с чем угодно. Популярный выбор - наложение чар: вещи, сделанные при прокачке, можно распылять и качать наложение чар полученной пылью.",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Tailoring Supply vendor nearby that sells the threads and dyes, {b}except{/b} the trainer in Tirisfal Glades. For that one, buy the Coarse Thread in Brill from {n:0:horde:Abigail Shiel}."] = "{b}ПРИМЕЧАНИЕ:{/b} {b}У большинства учителей{/b} рядом есть торговец портняжными товарами, который продает нитки и красители, {b}кроме{/b} учителя в Тирисфальских лесах. В этом случае купи грубую нить в Брилле у {n:0:horde:Abigail Shiel}.",
  ["Alternative (if cheaper)"] = "Альтернатива (если дешевле)",
  ["This list is not final yet, but the skill ranges come from the game data, so it should be pretty close. The 280-300 part is not included here yet."] = "Этот список еще не окончательный, но диапазоны навыка взяты из данных игры, так что он должен быть довольно точным. Часть 280-300 сюда пока не включена.",
  ["Tailoring Trainer Locations"] = "Где найти учителей портняжного дела",
  ["Apprentice Tailoring has no level requirement in Forever, so you can learn it on a fresh character."] = "В Forever у портняжного дела уровня Ученик нет требований к уровню, так что его можно выучить новым персонажем.",
  ["Orgrimmar: {n:0:horde:Snang}"] = "Оргриммар: {n:0:horde:Snang}",
  ["Undercity: {n:0:horde:Victor Ward}"] = "Подгород: {n:0:horde:Victor Ward}",
  ["Thunder Bluff: {n:0:horde:Vhan}"] = "Громовой Утес: {n:0:horde:Vhan}",
  ["There is no Tailoring trainer in Durotar, go to {n:0:horde:Snang} in the Drag in Orgrimmar"] = "В Дуротаре нет учителя портняжного дела, иди к {n:0:horde:Snang} на Волок в Оргриммаре",
  ["There is no Tailoring trainer in Mulgore, go to {n:0:horde:Vhan} on the middle rise in Thunder Bluff"] = "В Мулгоре нет учителя портняжного дела, иди к {n:0:horde:Vhan} на средний уступ Громового Утеса",
  ["{n:0:horde:Bowen Brisboise} in the small house at Cold Hearth Manor, southwest of Brill"] = "{n:0:horde:Bowen Brisboise} в маленьком доме у поместья Холодного Очага, к юго-западу от Брилла",
  ["{n:0::Othesia Evengale} in Valanaar, {n:0::Taleen Shimmerthread} in Shen'dar Village"] = "{n:0::Othesia Evengale} в Валанааре, {n:0::Taleen Shimmerthread} в деревне Шен'дар",
  ["Stormwind City: {n:0:alliance:Lawrence Schneider}"] = "Штормград: {n:0:alliance:Lawrence Schneider}",
  ["Ironforge: {n:0:alliance:Uthrar Threx}"] = "Стальгорн: {n:0:alliance:Uthrar Threx}",
  ["Darnassus: {n:0:alliance:Trianna}"] = "Дарнас: {n:0:alliance:Trianna}",
  ["{n:0:alliance:Eldrin} in a house at the Eastvale Logging Camp"] = "{n:0:alliance:Eldrin} в доме в лагере лесорубов Восточной долины",
  ["There is no Tailoring trainer in Dun Morogh, go to {n:0:alliance:Uthrar Threx} at the Great Forge in Ironforge"] = "В Дун Мороге нет учителя портняжного дела, иди к {n:0:alliance:Uthrar Threx} у Великой Кузни в Стальгорне",
  ["There is no Tailoring trainer in Teldrassil, go to {n:0:alliance:Trianna} at the Craftsmen's Terrace in Darnassus"] = "В Тельдрассиле нет учителя портняжного дела, иди к {n:0:alliance:Trianna} на Террасу Ремесленников в Дарнасе",
  ["You can find every Tailoring trainer for Horde and Alliance on my WoW Forever Tailoring Trainers page."] = "Всех учителей портняжного дела Орды и Альянса ты найдешь на моей странице «WoW Forever Tailoring Trainers».",
  ["Apprentice Tailoring (1-55)"] = "Портняжное дело: Ученик (1-55)",
  ["30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Linen Cloth"] = "30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Льняной материал",
  ["Keep the bolts, you need all of them for the belts."] = "Сохрани рулоны, все они понадобятся для поясов.",
  ["28x {s:8776:inv_belt_05:Linen Belt} - 28 Bolt of Linen Cloth, 28 Coarse Thread"] = "28x {s:8776:inv_belt_05:Linen Belt} - 28 Рулон льняного полотна, 28 Грубая нить",
  ["Journeyman Tailoring (55-140)"] = "Портняжное дело: Подмастерье (55-140)",
  ["To train past 75, visit one of these trainers and learn Journeyman Tailoring. You need {b}Tailoring 50{/b} and {b}level 10{/b}:"] = "Чтобы учиться дальше 75, посети одного из этих учителей и выучи портняжное дело уровня Подмастерье. Нужно {b}Портняжное дело 50{/b} и {b}10-й уровень{/b}:",
  ["Orgrimmar: {n:0:horde:Magar}"] = "Оргриммар: {n:0:horde:Magar}",
  ["Undercity: {n:0:horde:Rhiannon Davis}"] = "Подгород: {n:0:horde:Rhiannon Davis}",
  ["Thunder Bluff: {n:0:horde:Tepa}"] = "Громовой Утес: {n:0:horde:Tepa}",
  ["Stormwind City: {n:0:alliance:Sellandus}"] = "Штормград: {n:0:alliance:Sellandus}",
  ["Ironforge: {n:0:alliance:Jormund Stonebrow}"] = "Стальгорн: {n:0:alliance:Jormund Stonebrow}",
  ["Darnassus: {n:0:alliance:Me'lynn}"] = "Дарнас: {n:0:alliance:Me'lynn}",
  ["{b}Learn Journeyman Tailoring before you make these.{/b} You can reach past 75 with them, but you won't get any skill points above 75 until you learn it, so don't go AFK while crafting before you have it."] = "{b}Выучи уровень Подмастерье, прежде чем делать это.{/b} С ними можно подняться выше 75, но пока не выучишь его, очков навыка выше 75 не будет, так что не уходи в АФК во время изготовления, пока не выучишь.",
  ["45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Wool Cloth"] = "45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Шерсть",
  ["Keep the bolts, you will need them later. In total you will need 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}) until 140, so you can also make all of them now."] = "Сохрани рулоны, они понадобятся позже. Всего до 140 понадобится 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}), так что можешь сделать их все сразу.",
  ["22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Bolt of Woolen Cloth, 22 Fine Thread"] = "22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Рулон шерстяной ткани, 22 Тонкая нить",
  ["If the bolts already took you past 80, just make capes until 95."] = "Если рулоны уже подняли тебя выше 80, просто делай плащи до 95.",
  ["5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Bolt of Woolen Cloth, 10 Fine Thread"] = "5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Рулон шерстяной ткани, 10 Тонкая нить",
  ["54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Silk Cloth"] = "54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Шелк",
  ["Keep the bolts, you will need them later. In total you will need 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}) until 190, so you can also make all of them now."] = "Сохрани рулоны, они понадобятся позже. Всего до 190 понадобится 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}), так что можешь сделать их все сразу.",
  ["29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Bolt of Woolen Cloth, 87 Fine Thread, 29 Elixir of Wisdom"] = "29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Рулон шерстяной ткани, 87 Тонкая нить, 29 Эликсир мудрости",
  ["You can buy {i:3383:inv_potion_06:Elixir of Wisdom} from the Auction House or ask an Alchemist."] = "{i:3383:inv_potion_06:Elixir of Wisdom} можно купить на аукционе или попросить у алхимика.",
  ["Expert Tailoring (140-200)"] = "Портняжное дело: Умелец (140-200)",
  ["To train past 150, visit {n:0:horde:Josef Gregorian} in Undercity (Horde) or {n:0:alliance:Georgio Bolero} in Stormwind City (Alliance) and learn Expert Tailoring. You need {b}Tailoring 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Чтобы учиться дальше 150, посети {n:0:horde:Josef Gregorian} в Подгороде (Орда) или {n:0:alliance:Georgio Bolero} в Штормграде (Альянс) и выучи портняжное дело уровня Умелец. Нужно {b}Портняжное дело 125{/b} и {b}20-й уровень{/b}, стоит 50 серебра.",
  ["23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Mageweave Cloth"] = "23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Магическая ткань",
  ["Keep the bolts, you will need them later. In total you will need 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}) until 225, so you can also make all of them now."] = "Сохрани рулоны, они понадобятся позже. Всего до 225 понадобится 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}), так что можешь сделать их все сразу.",
  ["20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Bolt of Silk Cloth, 40 Red Dye, 40 Fine Thread"] = "20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Рулон шелка, 40 Красный краситель, 40 Тонкая нить",
  ["26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Bolt of Silk Cloth, 52 Red Dye, 52 Silken Thread"] = "26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Рулон шелка, 52 Красный краситель, 52 Шелковая нить",
  ["19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Bolt of Mageweave, 57 Silken Thread"] = "19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Рулон магической ткани, 57 Шелковая нить",
  ["Artisan Tailoring (200-300)"] = "Портняжное дело: Мастер (200-300)",
  ["To train past 225, visit {n:0:horde:Daryl Stack} in Tarren Mill, Hillsbrad Foothills (Horde) or {n:0:alliance:Timothy Worthington} in Theramore Isle, Dustwallow Marsh (Alliance) and learn Artisan Tailoring. You need {b}Tailoring 200{/b} and {b}level 35{/b}."] = "Чтобы учиться дальше 225, посети {n:0:horde:Daryl Stack} в Мельнице Таррен в Предгорьях Хилсбрада (Орда) или {n:0:alliance:Timothy Worthington} на острове Терамор в Пылевых топях (Альянс) и выучи портняжное дело уровня Мастер. Нужно {b}Портняжное дело 200{/b} и {b}35-й уровень{/b}.",
  ["5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Bolt of Mageweave, 10 Heavy Silken Thread"] = "5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Рулон магической ткани, 10 Толстая шелковая нить",
  ["{b}The Expert trainers in Undercity and Stormwind don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}Учителя уровня Умелец в Подгороде и Штормграде не обучают этому рецепту{/b}, его можно выучить только у двух учителей выше.",
  ["23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Runecloth"] = "23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Руническая ткань",
  ["Keep the bolts, you will need them later. In total you will need 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}) until 280, so you can also make all of them now."] = "Сохрани рулоны, они понадобятся позже. Всего до 280 понадобится 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}), так что можешь сделать их все сразу.",
  ["26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Bolt of Mageweave, 52 Silken Thread"] = "26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Рулон магической ткани, 52 Шелковая нить",
  ["I recommend the bags right now simply because they are more useful. You can use them yourself, sell some, give them to friends or use them in your bank."] = "Сейчас советую сумки просто потому, что они полезнее. Можно пользоваться ими самому, продать часть, раздать друзьям или поставить в банк.",
  ["If you don't need the bags and don't want to sell them, make these instead."] = "Если сумки не нужны и продавать их не хочешь, делай вместо этого вот это.",
  ["10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Bolt of Runecloth, 10 Rune Thread."] = "10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Рулон рунической ткани, 10 Руническая нить.",
  ["24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Bolt of Runecloth, 24 Rune Thread"] = "24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Рулон рунической ткани, 24 Руническая нить",
  ["11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Bolt of Runecloth, 44 Rugged Leather, 11 Rune Thread"] = "11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Рулон рунической ткани, 44 Грубая кожа, 11 Руническая нить",
  ["The pattern is sold by {n:0::Qia} in Winterspring."] = "Выкройку продает {n:0::Qia} в Зимних Ключах.",
  ["39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Bolt of Runecloth, 39 Ironweb Spider Silk, 39 Rune Thread"] = "39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Рулон рунической ткани, 39 Паутина железного паука, 39 Руническая нить",
  ["The pattern is sold by {n:0::Pexmit} in Mount Hyjal. It's bind on pickup, so buy it with the character that levels Tailoring."] = "Выкройку продает {n:0::Pexmit} на горе Хиджал. Она становится персональной при получении, так что покупай ее тем персонажем, который качает портняжное дело.",
  ["Horde players can also get it as the reward for {q:95769::Threading a Solution}, a quest from {n:265788::Kal'tinzan} in Elderwild, Mount Hyjal. It needs level 54 and 6 Bolt of Runecloth. It's probably a Tailoring quest, but I don't know yet what skill it needs."] = "Игроки Орды могут также получить ее в награду за {q:95769::Threading a Solution}, задание от {n:265788::Kal'tinzan} в Элдервайлде на горе Хиджал. Нужен 54-й уровень и 6 рулонов рунической ткани. Скорее всего, это задание для портных, но какой навык для него нужен, я пока не знаю.",
  ["Make the {s:18449:inv_shoulder_21:Runecloth Shoulders} if you can get the pattern. These are all the recipes I found so far that still give points after 280. I left out the ones that aren't worth it for leveling, and there might be new ones that nobody has found yet."] = "Делай {s:18449:inv_shoulder_21:Runecloth Shoulders}, если сможешь достать выкройку. Это все рецепты, которые я пока нашел и которые еще дают очки после 280. Я не включил те, что невыгодны для прокачки, и, возможно, есть новые, которые еще никто не нашел.",
  ["Range"] = "Диапазон",
  ["Materials"] = "Материалы",
  ["Pattern"] = "Выкройка",
  ["World drop, on the Auction House"] = "Добыча в мире, есть на аукционе",
  ["Rare, grab it if you see it on the Auction House"] = "Редкая, хватай, если увидишь на аукционе",
  ["You can get a few more points with these, but they stop giving skill points before 300, so you can't reach 300 with them:"] = "С ними можно получить еще несколько очков, но они перестают давать навык до 300, так что до 300 с ними не дойти:",
  ["{n:0::Pexmit} in Mount Hyjal"] = "{n:0::Pexmit} на горе Хиджал",
  ["Recipes that need a Loom"] = "Рецепты, для которых нужен ткацкий станок",
  ["{b}These recipes need a Loom, and you can only make a Loom at Tailoring 300.{/b} They could be used for leveling, but for now you would need a camp where another tailor already placed a Loom. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}Для этих рецептов нужен ткацкий станок, а сделать его можно только на Портняжном деле 300.{/b} Их можно было бы использовать для прокачки, но пока для этого нужен лагерь, где другой портной уже поставил станок. Не уверен, что это не недосмотр Blizzard, так что это могут изменить.",
  ["These are the Cenarion Circle patterns from {n:0::Mishta} in Silithus:"] = "Это выкройки Круга Кенария от {n:0::Mishta} в Силитусе:",
  ["Requires"] = "Требуется",
  ["5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} or {s:1297120:inv_gauntlets_18:Venomspew Gloves}"] = "5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} или {s:1297120:inv_gauntlets_18:Venomspew Gloves}",
  ["20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} или {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Friendly"] = "Круг Кенария: дружелюбие",
  ["5x {s:1297124:inv_belt_03:Swarmtender's Cord} or {s:1297121:inv_belt_25:Venomspew Cord}"] = "5x {s:1297124:inv_belt_03:Swarmtender's Cord} или {s:1297121:inv_belt_25:Venomspew Cord}",
  ["30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} или {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Honored"] = "Круг Кенария: уважение",
  ["18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} or {s:1297122:inv_boots_cloth_04:Venomspew Footpads}"] = "18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} или {s:1297122:inv_boots_cloth_04:Venomspew Footpads}",
  ["90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} или {i:7082:spell_nature_earthbind:Essence of Air}",
  ["This WoW Forever Mining leveling guide will show you the fastest way to level Mining from 1 to 300. You will also find every trainer location and where to train Mining past 75, 150 and 225."] = "Это руководство по прокачке горного дела для WoW Forever покажет тебе самый быстрый способ поднять горное дело с 1 до 300. Здесь же ты найдешь всех учителей и узнаешь, где учиться горному делу после 75, 150 и 225.",
  ["Below you will find the Mining trainers by starting zone and capital city, and the best zones to mine in for every skill range. Mining serves two professions, Blacksmithing and Engineering, so it's really good combined with these two. Check out my Forever Blacksmithing leveling guide or my Forever Engineering leveling guide if you want to level one of them."] = "Ниже ты найдешь учителей горного дела по стартовым зонам и столицам, а также лучшие зоны для добычи руды на каждом диапазоне навыка. Горное дело обслуживает две профессии, кузнечное и инженерное дело, так что с ними оно сочетается отлично. Загляни в мое руководство по кузнечному делу для Forever или по инженерному делу для Forever, если хочешь прокачать одну из них.",
  ["WoW Forever added a couple of new ores, bars and recipes. You can check them out here:"] = "В WoW Forever добавили несколько новых руд, слитков и рецептов. Посмотреть их можно здесь:",
  ["Mining Trainer Locations"] = "Где найти учителей горного дела",
  ["Every capital city except Darnassus has a Mining trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Учитель горного дела есть в каждой столице, кроме Дарнаса. Можно также спросить стражника, и тогда учитель будет отмечен красным флажком на карте.",
  ["{b}Capital cities:{/b}"] = "{b}Столицы:{/b}",
  ["Orgrimmar: {n:0:horde:Makaru}"] = "Оргриммар: {n:0:horde:Makaru}",
  ["Undercity: {n:0:horde:Brom Killian}"] = "Подгород: {n:0:horde:Brom Killian}",
  ["Thunder Bluff: {n:0:horde:Brek Stonehoof}"] = "Громовой Утес: {n:0:horde:Brek Stonehoof}",
  ["{b}Starting zones:{/b}"] = "{b}Стартовые зоны:{/b}",
  ["{n:0:horde:Norzsh} in the Valley of Trials (only up to 75) {n:0:horde:Krunn} in Razor Hill"] = "{n:0:horde:Norzsh} в Долине Испытаний (только до 75) {n:0:horde:Krunn} в Колючем Холме",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache (only up to 75) {n:0:horde:Brek Stonehoof} in Thunder Bluff"] = "{n:0:horde:Vartha Rockmane} в Лагере Нараче (только до 75) {n:0:horde:Brek Stonehoof} в Громовом Утесе",
  ["{n:0:horde:Walter Mason} in Deathknell (only up to 75) {n:0:horde:Brom Killian} in Undercity"] = "{n:0:horde:Walter Mason} в Похоронном Звоне (только до 75) {n:0:horde:Brom Killian} в Подгороде",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining. The trainers on the island are {n:0::Halavuul Cragwind} in Valanaar and {n:0::Messana Crestwind} in Shen'dar Village."] = "В деревне Тендал, где ты начинаешь, учителя нет, но он и не нужен. {q:93552::Harvesting Windstones} - одно из первых заданий в деревне Тендал. Выбери в награду {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies}, она обучает горному делу. Учителя на острове: {n:0::Halavuul Cragwind} в Валанааре и {n:0::Messana Crestwind} в деревне Шен'дар.",
  ["Stormwind City: {n:0:alliance:Gelman Stonehand}"] = "Штормград: {n:0:alliance:Gelman Stonehand}",
  ["Ironforge: {n:0:alliance:Geofram Bouldertoe}"] = "Стальгорн: {n:0:alliance:Geofram Bouldertoe}",
  ["Darnassus: no trainer, the closest one is {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "Дарнас: учителя нет, ближайший из них {n:0:alliance:Kurdram Stonehammer} в Аубердине на Темных берегах",
  ["{n:0:alliance:Kelsey Fargo} (only up to 75) {n:0:alliance:Gelman Stonehand} in Stormwind City"] = "{n:0:alliance:Kelsey Fargo} (только до 75) {n:0:alliance:Gelman Stonehand} в Штормграде",
  ["{n:0:alliance:Sally Swiftwrench} (only up to 75) {n:0:alliance:Yarr Hammerstone} at Steelgrill's Depot {n:0:alliance:Dank Drizzlecut} at Gol'Bolar Quarry"] = "{n:0:alliance:Sally Swiftwrench} (только до 75) {n:0:alliance:Yarr Hammerstone} в Депо Сталежара {n:0:alliance:Dank Drizzlecut} в Карьере Гол'Болар",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "{n:0:alliance:Fanorran Stilloak} у Альдрассила в Тенистой долине (только до 75) {n:0:alliance:Kurdram Stonehammer} в Аубердине на Темных берегах",
  ["You can find every Mining trainer for Horde and Alliance on my WoW Forever Mining Trainers page."] = "Всех учителей горного дела Орды и Альянса ты найдешь на моей странице «WoW Forever Mining Trainers».",
  ["Track Ore on Your Minimap"] = "Отслеживание руды на миникарте",
  ["You can only track one thing at a time, so {b}you can't track minerals and herbs together{/b}."] = "Отслеживать можно только что-то одно, так что {b}руду и травы одновременно отслеживать нельзя{/b}.",
  ["You learn {s:2580:spell_nature_earthquake:Find Minerals} together with Mining, but it's not turned on by default:"] = "{s:2580:spell_nature_earthquake:Find Minerals} ты получаешь вместе с горным делом, но по умолчанию поиск не включен:",
  ["Open the Professions window with the hammer and pick button, the 2nd button in the menu at the bottom of your screen."] = "Открой окно профессий кнопкой с молотом и киркой, второй кнопкой в меню внизу экрана.",
  ["Click Find Minerals in the Mining box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "Нажми «Поиск минералов» в блоке горного дела. {b}Советую перетащить его на панель команд, поближе к баффам, которые ты используешь после смерти.{/b} Так это войдет в привычку и ты реже будешь о нем забывать.",
  ["The Find Minerals buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "Бафф «Поиск минералов» появится рядом с миникартой. {b}Отслеживание выключается при каждой смерти, так что не забывай включать его снова!{/b}",
  ["The Find Minerals button in the WoW Forever Professions window"] = "Кнопка «Поиск минералов» в окне профессий WoW Forever",
  ["Mining Skill Bonuses"] = "Бонусы к навыку горного дела",
  ["You don't need these, but they help when you are stuck between two ores. With +5 you can mine Iron Deposits from 120 instead of 125, so you can skip the last few slow points of Tin."] = "Они не обязательны, но помогают, когда застрял между двумя рудами. С +5 можно добывать железные залежи со 120 вместо 125, так что последние медленные очки на олове можно пропустить.",
  ["Item"] = "Предмет",
  ["Mining"] = "Горное дело",
  ["How to get it"] = "Как получить",
  ["An enchanter"] = "Зачарователь",
  ["Made by Engineers, you need Engineering 205 to wear it"] = "Делают инженеры, чтобы носить, нужно Инженерное дело 205",
  ["Reward of A Miner Problem, an Alliance quest in the Riverglades"] = "Награда за A Miner Problem, задание Альянса в Ривергладах",
  ["Drops from Miner Johnson in The Deadmines"] = "Падает с Шахтера Джонсона в Мертвых копях",
  ["Smelting to 105"] = "Выплавка до 105",
  ["You can skip the first 105 skill points by buying ores on the Auction House and smelting them. If you prefer leveling Mining the normal way, scroll down to the mining routes. But I would recommend smelting if you have the gold, as it saves a lot of time. Sometimes the bars even sell for more than the ores or they are very close in price, so it's not like you are losing much by doing this."] = "Первые 105 очков навыка можно пропустить, если купить руду на аукционе и переплавить ее. Если хочешь качать горное дело обычным способом, листай вниз к маршрутам добычи. Но если есть золото, я бы советовал плавку, она экономит кучу времени. Иногда слитки даже продаются дороже руды или почти по той же цене, так что ты почти ничего не теряешь.",
  ["Buy around 140 {i:2770:inv_ore_copper_01:Copper Ore} and 70 {i:2771:inv_ore_tin_01:Tin Ore}. Smelting is mostly yellow and green, so you might need a few more if you are unlucky."] = "Купи около 140 {i:2770:inv_ore_copper_01:Copper Ore} и 70 {i:2771:inv_ore_tin_01:Tin Ore}. Плавка в основном желтая и зеленая, так что если не повезет, может понадобиться чуть больше.",
  ["Notes"] = "Примечания",
  ["120-140x {s:2657:inv_ingot_02:Smelt Copper} until you reach 65. Keep 70 Copper Bars, you will need them for Bronze."] = "120-140x {s:2657:inv_ingot_02:Smelt Copper}, пока не дойдешь до 65. Сохрани 70 медных слитков, они понадобятся для бронзы.",
  ["Learn Journeyman Mining, Smelt Tin and Smelt Bronze from your trainer. Make 70x {s:3304:inv_ingot_05:Smelt Tin}. It turns grey at 75, but you need all 70 Tin Bars for Bronze anyway."] = "Выучи у учителя горное дело уровня Подмастерье, выплавку олова и выплавку бронзы. Сделай 70x {s:3304:inv_ingot_05:Smelt Tin}. На 75 рецепт становится серым, но все 70 оловянных слитков все равно нужны для бронзы.",
  ["Make 70x {s:2659:inv_ingot_bronze:Smelt Bronze} from the Copper Bars and Tin Bars you made. You will end up somewhere between 100 and 110, so you might need a few more."] = "Сделай 70x {s:2659:inv_ingot_bronze:Smelt Bronze} из полученных медных и оловянных слитков. В итоге будет где-то между 100 и 110, так что может понадобиться еще немного.",
  ["Learn Smelt Silver from your trainer. Check the price of Silver Ore and Silver Bar first, because this part can get expensive. If you don't mind the cost, make 35-45x {s:2658:inv_ingot_01:Smelt Silver} until you reach 120. The last 5 points to 125 could take around 50 more Silver Ore, so I recommend mining from 120. (or keep smelting if you have the gold) Iron Deposits need Mining 125, but with +5 from the Mining Skill Bonuses above you can mine them from 120, so you can skip Tin and go straight to Iron."] = "Выучи у учителя выплавку серебра. Сначала проверь цены на серебряную руду и серебряные слитки, эта часть может выйти дорогой. Если цена тебя не смущает, сделай 35-45x {s:2658:inv_ingot_01:Smelt Silver}, пока не дойдешь до 120. Последние 5 очков до 125 могут потребовать еще около 50 серебряной руды, так что со 120 советую добывать. (или продолжай плавить, если есть золото) Для железных залежей нужно Горное дело 125, но с +5 от бонусов к навыку выше их можно добывать со 120, так что олово можно пропустить и сразу перейти к железу.",
  ["{b}Don't forget to buy{/b} a {i:2901:inv_pick_02:Mining Pick} from the Mining Supplier near your trainer or from the trainer!"] = "{b}Не забудь купить{/b} {i:2901:inv_pick_02:Mining Pick} у торговца горняцкими товарами рядом с учителем или у самого учителя!",
  ["You can buy one from these vendors:"] = "Купить ее можно у этих торговцев:",
  ["{n:0:horde:Norzsh} in the Valley of Trials, {n:0:horde:Flakk} in Razor Hill"] = "{n:0:horde:Norzsh} в Долине Испытаний, {n:0:horde:Flakk} в Колючем Холме",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache, {n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "{n:0:horde:Vartha Rockmane} в Лагере Нараче, {n:0:horde:Wunna Darkmane} в деревне Кровавого Копыта",
  ["{n:0:horde:Walter Mason} in Deathknell, {n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Walter Mason} в Похоронном Звоне, {n:0:horde:Abigail Shiel} в Брилле",
  ["{n:0::Uualia Suncrest} in Thendal Village, {n:0::Belandiel Farflight} in Shen'dar Village"] = "{n:0::Uualia Suncrest} в деревне Тендал, {n:0::Belandiel Farflight} в деревне Шен'дар",
  ["{n:0:horde:Gorina} in the Valley of Honor"] = "{n:0:horde:Gorina} в Аллее Чести",
  ["{n:0:horde:Elizabeth Van Talen} in the Rogues' Quarter"] = "{n:0:horde:Elizabeth Van Talen} в Квартале разбойников",
  ["{n:0:alliance:Brother Danil} in Northshire Valley, {n:0:alliance:Tharynn Bouden} in Goldshire"] = "{n:0:alliance:Brother Danil} в Долине Североземья, {n:0:alliance:Tharynn Bouden} в Златоземье",
  ["{n:0:alliance:Thrawn Boltar} in Kharanos"] = "{n:0:alliance:Thrawn Boltar} в Караносе",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen, {n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "{n:0:alliance:Fanorran Stilloak} у Альдрассила в Тенистой долине, {n:0:alliance:Narret Shadowgrove} в Доланааре",
  ["{n:0:alliance:Brooke Stonebraid} in the Dwarven District"] = "{n:0:alliance:Brooke Stonebraid} в Квартале дворфов",
  ["{n:0:alliance:Thurgrum Deepforge} in The Great Forge"] = "{n:0:alliance:Thurgrum Deepforge} у Великой Кузни",
  ["Darnassus"] = "Дарнас",
  ["Like I said above, for most high level players I think it's best to skip this part and smelt your way up to at least 105. But if you prefer mining and you can choose your zone, I think {b}Durotar{/b} is the best for Horde and {b}Elwynn Forest{/b} for Alliance."] = "Как я сказал выше, большинству игроков высокого уровня, по-моему, лучше пропустить эту часть и доплавить хотя бы до 105. Но если тебе больше нравится добывать и можешь выбрать зону, то, по-моему, лучше всего {b}Дуротар{/b} для Орды и {b}Элвиннский лес{/b} для Альянса.",
  ["One or two laps around the zone will get you enough Copper Ore to reach 65 with smelting."] = "Одного-двух кругов по зоне хватит, чтобы набрать медной руды и выплавкой дойти до 65.",
  ["After you do one lap, {b}stop at Razor Hill and smelt your Copper Ore{/b} into Copper Bars."] = "После одного круга {b}зайди в Колючий Холм и переплавь медную руду{/b} в медные слитки.",
  ["Mining route in Durotar"] = "Маршрут добычи руды в Дуротаре",
  ["The cave marked with the red circle has 5 Copper Veins inside, {b}the respawn rate is so fast that you can basically stay inside the cave and level there{/b}. The cave layout is also very good because there is a drop down at the end, so you can quickly return to the start and continue mining. If the respawn rate is not enough for you or there is competition, just run outside, mine a couple of Copper Veins and go back to the cave."] = "В пещере, отмеченной красным кругом, 5 медных жил, и {b}они возрождаются так быстро, что можно, по сути, качаться, не выходя из пещеры{/b}. Устройство пещеры тоже очень удобное: в конце есть спуск, так что можно быстро вернуться к началу и продолжать. Если возрождения не хватает или есть конкуренты, просто выйди наружу, добудь пару медных жил и вернись в пещеру.",
  ["You can also just do a full lap in Mulgore, the route is very easy to follow, it's basically a loop around the edge of the zone. But I found the cave to be better without a mount."] = "Можно также просто пройти полный круг по Мулгору, маршрут очень простой, по сути петля по краю зоны. Но без маунта пещера, по-моему, лучше.",
  ["{b}You can smelt your ore at the Bael'dun Digsite{/b}, the dwarf camp just north of the cave has a forge and an anvil. (marked on the map) The dwarves there are hostile."] = "{b}Переплавить руду можно на раскопках Баэл'дун{/b}: в лагере дворфов к северу от пещеры есть кузня и наковальня. (отмечены на карте) Дворфы там враждебны.",
  ["Mining route in Mulgore with the forge and anvil at the Bael'dun Digsite"] = "Маршрут добычи руды в Мулгоре с кузней и наковальней на раскопках Баэл'дун",
  ["Both routes are good. The route on the east side of the zone will probably have fewer people, because there are fewer quest hubs there."] = "Оба маршрута хороши. На маршруте в восточной части зоны, скорее всего, будет меньше людей, потому что там меньше мест с заданиями.",
  ["{b}Stop at Brill after one lap{/b} to smelt your Copper Ore."] = "{b}После одного круга зайди в Брилл{/b}, чтобы переплавить медную руду.",
  ["Mining route in Tirisfal Glades"] = "Маршрут добычи руды в Тирисфальских лесах",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining."] = "{q:93552::Harvesting Windstones} - одно из первых заданий в деревне Тендал. Выбери в награду {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies}, она обучает горному делу.",
  ["The respawn rate is very fast around this area, sometimes the veins spawned right on top of me. You can do a larger route, but without a mount and with the fast respawn rate I found it wasn't needed."] = "В этой области жилы возрождаются очень быстро, иногда прямо у меня под ногами. Можно пройти и маршрут побольше, но без маунта и при таком быстром возрождении мне это не понадобилось.",
  ["{b}Stop at Shen'dar Village after one lap{/b} to smelt your Copper Ore."] = "{b}После одного круга зайди в деревню Шен'дар{/b}, чтобы переплавить медную руду.",
  ["Mining route on Zephras Isle"] = "Маршрут добычи руды на Острове Зефрас",
  ["Just move back and forth along the marked route, and clear the cave if you are high enough level. The respawn rate is quite fast inside the cave, so you might not even have to leave it, it depends on your level. You can also just skip the cave, the respawn rate seems to be fast enough on the route, but then do the small detour to the north too."] = "Просто ходи туда-обратно по отмеченному маршруту и зачищай пещеру, если позволяет уровень. В пещере жилы возрождаются довольно быстро, так что, возможно, выходить из нее даже не придется, зависит от твоего уровня. Пещеру можно и пропустить, на маршруте возрождение, похоже, тоже достаточно быстрое, но тогда загляни еще и в небольшой крюк на север.",
  ["{b}Stop at Goldshire after one lap{/b} to smelt your Copper Ore."] = "{b}После одного круга зайди в Златоземье{/b}, чтобы переплавить медную руду.",
  ["Mining route in Elwynn Forest"] = "Маршрут добычи руды в Элвиннском лесу",
  ["Not much to say about this one, just do loops around this area. You don't have to go inside the cave, it's optional and the respawn rate outside is quite fast."] = "Тут особо нечего сказать, просто ходи кругами по этой области. В пещеру заходить не обязательно, снаружи возрождение довольно быстрое.",
  ["{b}Stop at Kharanos after one lap{/b} to smelt your Copper Ore."] = "{b}После одного круга зайди в Каранос{/b}, чтобы переплавить медную руду.",
  ["Mining route in Dun Morogh"] = "Маршрут добычи руды в Дун Мороге",
  ["These two caves have an insanely fast respawn rate. I don't know if it stays like this, but right now you can just stay inside the caves and level there."] = "В этих двух пещерах безумно быстрое возрождение. Не знаю, останется ли так, но сейчас можно просто сидеть в пещерах и качаться там.",
  ["There is no forge in Teldrassil, {b}the closest one is at the Warrior's Terrace in Darnassus{/b}."] = "В Тельдрассиле нет кузни, {b}ближайшая находится на Террасе Воинов в Дарнасе{/b}.",
  ["Mining route in Teldrassil"] = "Маршрут добычи руды в Тельдрассиле",
  ["Visit your trainer and learn Journeyman Mining, it requires Mining 50. The new Junior Mining Trainers in the starting areas won't teach you Journeyman Mining."] = "Зайди к учителю и выучи горное дело уровня Подмастерье, для этого нужно Горное дело 50. Новые младшие учителя горного дела в стартовых зонах уровню Подмастерье не обучают.",
  ["If you have any Copper Ore or Tin Ore at this point, smelt them and make Bronze Bars before you head out, because Bronze stops giving skill points around 105."] = "Если у тебя сейчас есть медная или оловянная руда, переплавь ее и сделай бронзовые слитки до выхода, потому что бронза перестает давать очки навыка примерно на 105.",
  ["For Alliance, the {b}Wetlands{/b} is the best one by far if you can manage the cave. For Horde it's the {b}Silverpine Forest{/b} cave or {b}Hillsbrad Foothills{/b}. The rest are pretty even, hard to judge."] = "Для Альянса лучше всего, с большим отрывом, {b}Болотина{/b}, если справишься с пещерой. Для Орды - пещера в {b}Серебряном бору{/b} или {b}Предгорья Хилсбрада{/b}. Остальные примерно равны, сложно сказать.",
  ["Ores in these zones: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}"] = "Руда в этих зонах: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}",
  ["Tin Veins need Mining 65 and Silver Veins 75."] = "Для оловянных жил нужно Горное дело 65, для серебряных 75.",
  ["Wetlands"] = "Болотина",
  ["Silverpine Forest"] = "Серебряный бор",
  ["Westfall"] = "Западный Край",
  ["Hillsbrad Foothills"] = "Предгорья Хилсбрада",
  ["The Barrens"] = "Степи",
  ["Ashenvale"] = "Ясеневый лес",
  ["Stonetalon Mountains"] = "Когтистые горы",
  ["This cave in the Wetlands is the best place for Alliance players to level Mining. The cave is full of Tin Veins and Incendicite Mineral Veins with a very fast respawn time."] = "Эта пещера в Болотине - лучшее место для прокачки горного дела для игроков Альянса. Пещера полна оловянных жил и ароматитовых жил, которые очень быстро возрождаются.",
  ["The mobs are around level 20 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Монстры там около 20-го уровня, и {b}в Forever они возрождаются намного быстрее, так что тебе нужно обогнать их на приличное количество уровней{/b}, иначе они будут постоянно возрождаться прямо на тебе.",
  ["Mining route in the Wetlands"] = "Маршрут добычи руды в Болотине",
  ["This cave has 3 vein spawn points with a very fast respawn time, just mine the veins and wait for the respawn. (around 2 minutes)"] = "В этой пещере 3 точки появления жил с очень быстрым возрождением, просто добывай жилы и жди, пока они появятся снова. (примерно 2 минуты)",
  ["The mobs are around level 21-22 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Монстры там около 21-22-го уровня, и {b}в Forever они возрождаются намного быстрее, так что тебе нужно обогнать их на приличное количество уровней{/b}, иначе они будут постоянно возрождаться прямо на тебе.",
  ["Mining route in Silverpine Forest"] = "Маршрут добычи руды в Серебряном бору",
  ["This cave has several Tin Veins that respawn very fast. There are also veins outside, so if you clear it too fast you can just run outside and mine a few there too."] = "В этой пещере несколько оловянных жил, которые очень быстро возрождаются. Снаружи тоже есть жилы, так что если зачистишь ее слишком быстро, просто выйди и добудь несколько снаружи.",
  ["The mobs are around level 13-15 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "Монстры там около 13-15-го уровня, и {b}в Forever они возрождаются намного быстрее, так что тебе нужно обогнать их на приличное количество уровней{/b}, иначе они будут постоянно возрождаться прямо на тебе.",
  ["Mining route in Westfall"] = "Маршрут добычи руды в Западном Крае",
  ["This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area. The route goes around a Horde town, so I'm not sure how it works for Alliance. I think you can probably avoid the guards, but I only tested this one with a Horde character."] = "Это лучший вариант, если предпочитаешь добывать обычным способом, но конкурентов может быть больше, ведь место популярное. Маршрут проходит вокруг поселения Орды, так что не уверен, как это работает для Альянса. Думаю, стражников, скорее всего, можно обойти, но я проверял его только персонажем Орды.",
  ["Mining route in Hillsbrad Foothills"] = "Маршрут добычи руды в Предгорьях Хилсбрада",
  ["The mobs are around level 22-26 here, so it's best to farm here if you are above those levels. But the respawn rate is fast."] = "Монстры здесь около 22-26-го уровня, так что фармить здесь лучше, если ты выше их. Но возрождение быстрое.",
  ["Mining route in The Barrens"] = "Маршрут добычи руды в Степях",
  ["A very straightforward route that is easy to follow. This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area."] = "Очень простой маршрут, по которому легко идти. Это лучший вариант, если предпочитаешь добывать обычным способом, но конкурентов может быть больше, ведь место популярное.",
  ["Mining route in Ashenvale"] = "Маршрут добычи руды в Ясеневом лесу",
  ["This route might not work if more than one player is leveling Mining there, because when I tested it there were very few people around. But this place usually has fewer people, so I think it's a good alternative if you don't want to level in caves. The only downside is that sometimes an Iron Deposit spawns instead of a Tin Vein, and you can't mine it yet."] = "Этот маршрут может не сработать, если там качает горное дело больше одного игрока: когда я его проверял, людей вокруг было очень мало. Но обычно здесь народу меньше, так что, думаю, это хорошая альтернатива, если не хочешь качаться в пещерах. Единственный минус: иногда вместо оловянной жилы появляются железные залежи, которые ты пока не можешь добыть.",
  ["Mining route in Stonetalon Mountains"] = "Маршрут добычи руды в Когтистых горах",
  ["From this point the guide follows the standard Classic Mining routes. The beta cap was 30, so I couldn't properly test Arathi and Desolace. I'll revise this section once I level my character higher on live, but the main change is the ore respawn rate, so most routes should work and you can probably take shorter routes in most zones."] = "Начиная отсюда руководство следует стандартным маршрутам горного дела из Classic. На бете был предел 30-го уровня, так что Нагорье Арати и Пустоши я как следует проверить не смог. Я переработаю этот раздел, когда прокачаю персонажа выше на живом сервере, но главное изменение - скорость возрождения руды, так что большинство маршрутов должны работать и в большинстве зон, скорее всего, можно ходить по более коротким маршрутам.",
  ["{b}Visit your trainer and learn Expert Mining{/b}, it requires Mining 125."] = "{b}Зайди к учителю и выучи горное дело уровня Умелец{/b}, для этого нужно Горное дело 125.",
  ["Smelting Iron and Gold (optional)"] = "Выплавка железа и золота (по желанию)",
  ["If you want to save some time and have the gold, buy around 20 {i:2772:inv_ore_iron_01:Iron Ore} and make {s:3307:inv_ingot_iron:Smelt Iron} until 135 before you head out mining. After 135 it rarely gives a point, so don't count on reaching 140."] = "Если хочешь сэкономить время и есть золото, купи около 20 {i:2772:inv_ore_iron_01:Iron Ore} и делай {s:3307:inv_ingot_iron:Smelt Iron} до 135, прежде чем идти добывать. После 135 она редко дает очко, так что на 140 не рассчитывай.",
  ["At 155 you can learn {s:3308:inv_ingot_03:Smelt Gold} from your trainer. It gives a point every time until 170, so around 22 Gold Ore takes you from 155 to 175 and you can start on Mithril right away. I recommend checking the price of Gold Ore and Gold Bar first."] = "На 155 можно выучить у учителя {s:3308:inv_ingot_03:Smelt Gold}. До 170 она дает очко каждый раз, так что примерно 22 золотой руды поднимут тебя со 155 до 175 и можно сразу переходить к мифрилу. Советую сначала проверить цены на золотую руду и золотые слитки.",
  ["If you have a {b}lower level character{/b} around level 30, stick to the {b}Thousand Needles{/b} route, that's the safest. If you have a {b}higher level character or a mount{/b} already, I recommend {b}Arathi Highlands{/b}."] = "Если у тебя {b}персонаж невысокого уровня{/b}, около 30-го, держись маршрута по {b}Тысяче Игл{/b}, он самый безопасный. Если у тебя уже {b}персонаж высокого уровня или есть маунт{/b}, советую {b}Нагорье Арати{/b}.",
  ["Ores in these zones: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}"] = "Руда в этих зонах: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}",
  ["Iron Deposits need Mining 125 and Gold Veins 155."] = "Для железных залежей нужно Горное дело 125, для золотых жил 155.",
  ["Arathi Highlands"] = "Нагорье Арати",
  ["Thousand Needles"] = "Тысяча Игл",
  ["Desolace"] = "Пустоши",
  ["There are 4 caves marked with red circles on the map. Make sure to go all the way to the end of each cave because you won't see all the mining veins from the entrance."] = "На карте красными кругами отмечены 4 пещеры. Обязательно доходи до самого конца каждой пещеры, потому что от входа видны не все жилы.",
  ["Low level players should skip all 4 caves, and low level Alliance players should take a detour and go south of Hammerfall!"] = "Игрокам низкого уровня стоит пропустить все 4 пещеры, а игрокам Альянса низкого уровня - сделать крюк и обойти Молотопад с юга!",
  ["Mining route in Arathi Highlands"] = "Маршрут добычи руды в Нагорье Арати",
  ["Mining route in Thousand Needles"] = "Маршрут добычи руды в Тысяче Игл",
  ["Mining route in Desolace"] = "Маршрут добычи руды в Пустошах",
  ["To train past 225, visit your trainer and learn Artisan Mining, it requires Mining 200."] = "Чтобы учиться дальше 225, зайди к учителю и выучи горное дело уровня Мастер, для этого нужно Горное дело 200.",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}"] = "Руда в этих зонах: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}",
  ["Mithril Deposits need Mining 175 and Truesilver Deposits 230."] = "Для мифриловых залежей нужно Горное дело 175, для залежей истинного серебра 230.",
  ["The Hinterlands"] = "Внутренние земли",
  ["Tanaris"] = "Танарис",
  ["The red route should be skipped by lower level players because the area is filled with level 62 elites. Lower level players might also want to consider skipping the cave marked with a red circle on the map. (depends on your gear/class)"] = "Игрокам пониже уровнем стоит пропустить красный маршрут, там полно элитных монстров 62-го уровня. Возможно, им стоит пропустить и пещеру, отмеченную на карте красным кругом. (зависит от снаряжения и класса)",
  ["Mining route in The Hinterlands"] = "Маршрут добычи руды во Внутренних землях",
  ["Players below level 60 should skip the 4 caves marked with red circles."] = "Игрокам ниже 60-го уровня стоит пропустить 4 пещеры, отмеченные красными кругами.",
  ["Mining route in Tanaris"] = "Маршрут добычи руды в Танарисе",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}"] = "Руда в этих зонах: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}",
  ["Small Thorium Veins need Mining 245."] = "Для малых ториевых жил нужно Горное дело 245.",
  ["Un'Goro Crater"] = "Кратер Ун'Горо",
  ["Blasted Lands"] = "Выжженные земли",
  ["Felwood"] = "Оскверненный лес",
  ["You will find 2-3 veins in the two caves marked with red circles on the map."] = "В двух пещерах, отмеченных на карте красными кругами, найдешь по 2-3 жилы.",
  ["Lower level players should probably skip the cave to the south. It really depends on your level, gear and class."] = "Игрокам пониже уровнем, наверное, стоит пропустить южную пещеру. Все очень зависит от уровня, снаряжения и класса.",
  ["Mining route in Un'Goro Crater"] = "Маршрут добычи руды в Кратере Ун'Горо",
  ["Both caves marked with red circles have a lot of mobs inside, so I only recommend this zone to level 60 players with good gear, or to Druids and Rogues with stealth."] = "В обеих пещерах, отмеченных красными кругами, много монстров, так что эту зону советую только игрокам 60-го уровня в хорошем снаряжении или друидам и разбойникам с незаметностью.",
  ["It's really hard to navigate inside the Garrison Armory mine, so I included a small map. {b}Alliance{/b} players can't mine inside the Garrison Armory!"] = "В шахте Оружейной гарнизона очень трудно ориентироваться, поэтому я добавил небольшую карту. Игроки {b}Альянса{/b} не могут добывать руду в Оружейной гарнизона!",
  ["Mining route in the Blasted Lands"] = "Маршрут добычи руды в Выжженных землях",
  ["There are usually 2 veins inside the cave marked with a red circle. It's worth going in because the cave is small and there aren't many mobs inside, and if you are high level, you can pass some of them without aggro."] = "В пещере, отмеченной красным кругом, обычно 2 жилы. Туда стоит зайти: пещера маленькая, монстров внутри немного, а на высоком уровне часть из них можно пройти, не привлекая внимания.",
  ["I recommend skipping the other two caves at Jaedenar, especially Shadow Hold. (if you have stealth, they might be worth going into)"] = "Две другие пещеры в Джеденаре советую пропустить, особенно Цитадель Тени. (если у тебя есть незаметность, возможно, туда стоит зайти)",
  ["Mining route in Felwood"] = "Маршрут добычи руды в Оскверненном лесу",
  ["Ores in these zones: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}"] = "Руда в этих зонах: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}",
  ["At 275 you can mine Rich Thorium Veins too."] = "На 275 можно добывать и богатые ториевые жилы.",
  ["Eastern Plaguelands"] = "Восточные Чумные земли",
  ["Winterspring"] = "Зимние Ключи",
  ["Burning Steppes"] = "Пылающие степи",
  ["Almost the same as the previous Un'Goro route, but now it includes Rich Thorium Veins."] = "Почти то же самое, что и прошлый маршрут по Ун'Горо, но теперь с богатыми ториевыми жилами.",
  ["Mining route with Rich Thorium Veins in Un'Goro Crater"] = "Маршрут добычи руды с богатыми ториевыми жилами в Кратере Ун'Горо",
  ["The red line is full of level 57-58 elites, so if your gear is bad, you should probably skip that part unless you have stealth. With some practice you can usually get through and only pull a few of them."] = "На красной линии полно элитных монстров 57-58-го уровня, так что если снаряжение слабое, эту часть, наверное, стоит пропустить, если только у тебя нет незаметности. С некоторой практикой обычно можно пройти, сагрив лишь нескольких.",
  ["Mining route in the Eastern Plaguelands"] = "Маршрут добычи руды в Восточных Чумных землях",
  ["The mobs in this cave are not that hard, so most classes can clear it. (depends on your gear)"] = "Монстры в этой пещере не такие уж сильные, так что большинство классов смогут ее зачистить. (зависит от снаряжения)",
  ["Most classes can get into at least the first part of the cave without pulling aggro. You can try going deeper depending on your gear."] = "Большинство классов могут пройти хотя бы в первую часть пещеры, не привлекая внимания. В зависимости от снаряжения можно попробовать пройти глубже.",
  ["A lot of elites patrol this gorge, but you can usually pass most of them without pulling aggro. Sometimes you have to kill 1 or 2."] = "По этому ущелью патрулирует много элитных монстров, но обычно большинство из них можно пройти, не привлекая внимания. Иногда придется убить 1-2.",
  ["I don't recommend this area for most players because it's hard to farm here without dying. It really depends on your class and how good you are at avoiding mobs."] = "Большинству игроков эту область не советую: фармить здесь, не умирая, трудно. Все очень зависит от класса и от того, насколько хорошо ты умеешь обходить монстров.",
  ["Mining route in Winterspring"] = "Маршрут добычи руды в Зимних Ключах",
  ["The two caves marked with red circles are full of level 50 mobs, so lower level players might want to skip them. (depends on your gear and level)"] = "Две пещеры, отмеченные красными кругами, полны монстров 50-го уровня, так что игрокам пониже уровнем, возможно, стоит их пропустить. (зависит от снаряжения и уровня)",
  ["Mining route in the Burning Steppes"] = "Маршрут добычи руды в Пылающих степях",
  ["This WoW Forever Herbalism leveling guide will show you the fastest way to level Herbalism from 1 to 300. You will also find a route map for every zone, every trainer location and where to train Herbalism past 75, 150 and 225."] = "Это руководство по прокачке травничества для WoW Forever покажет тебе самый быстрый способ поднять травничество с 1 до 300. Здесь же ты найдешь карту маршрута для каждой зоны, всех учителей и узнаешь, где учиться травничеству после 75, 150 и 225.",
  ["Below you will find the Herbalism trainers by starting zone and capital city, and the best zones to pick herbs in for every skill range. Herbalism goes well with Alchemy because you can use the herbs you pick to make potions and elixirs, so check out my Forever Alchemy leveling guide if you want to level Alchemy. But keep in mind, this guide is made to level Herbalism as fast as possible, so sometimes the herbs you pick are not the best ones for Alchemy."] = "Ниже ты найдешь учителей травничества по стартовым зонам и столицам, а также лучшие зоны для сбора трав на каждом диапазоне навыка. Травничество хорошо сочетается с алхимией, ведь из собранных трав можно делать зелья и эликсиры, так что загляни в мое руководство по алхимии для Forever, если хочешь прокачать алхимию. Но учти: это руководство нацелено на максимально быструю прокачку травничества, так что иногда собираемые травы не самые лучшие для алхимии.",
  ["WoW Forever added a couple of new herbs, seeds and recipes. You can check them out here:"] = "В WoW Forever добавили несколько новых трав, семян и рецептов. Посмотреть их можно здесь:",
  ["Herbalism Trainer Locations"] = "Где найти учителей травничества",
  ["Every capital city has a Herbalism trainer. You can also ask a guard where the herbalist is, then it will be marked with a red flag on your map."] = "Учитель травничества есть в каждой столице. Можно также спросить стражника, где травник, и тогда он будет отмечен красным флажком на карте.",
  ["Orgrimmar: {n:0:horde:Jandi}"] = "Оргриммар: {n:0:horde:Jandi}",
  ["Undercity: {n:0:horde:Martha Alliestar}"] = "Подгород: {n:0:horde:Martha Alliestar}",
  ["Thunder Bluff: {n:0:horde:Komin Winterhoof}"] = "Громовой Утес: {n:0:horde:Komin Winterhoof}",
  ["{n:0:horde:Zor'la} in the Valley of Trials (only up to 75) {n:0:horde:Mishiki} in Sen'jin Village"] = "{n:0:horde:Zor'la} в Долине Испытаний (только до 75) {n:0:horde:Mishiki} в деревне Сен'джин",
  ["{n:0:horde:Garan Sunstrider} in Camp Narache (only up to 75) {n:0:horde:Komin Winterhoof} in Thunder Bluff"] = "{n:0:horde:Garan Sunstrider} в Лагере Нараче (только до 75) {n:0:horde:Komin Winterhoof} в Громовом Утесе",
  ["{n:0:horde:Florence Nightshade} in Deathknell (only up to 75) {n:0:horde:Faruza} in Brill"] = "{n:0:horde:Florence Nightshade} в Похоронном Звоне (только до 75) {n:0:horde:Faruza} в Брилле",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism. The trainers on the island are {n:0::Syriel Nightrain} in Valanaar and {n:0::Halassa Fernbreeze} in Shen'dar Village."] = "В деревне Тендал, где ты начинаешь, учителя нет, но он и не нужен. {q:93552::Harvesting Windstones} - одно из первых заданий в деревне Тендал. Выбери в награду {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest}, она обучает травничеству. Учителя на острове: {n:0::Syriel Nightrain} в Валанааре и {n:0::Halassa Fernbreeze} в деревне Шен'дар.",
  ["Stormwind City: {n:0:alliance:Tannysa}"] = "Штормград: {n:0:alliance:Tannysa}",
  ["Ironforge: {n:0:alliance:Reyna Stonebranch}"] = "Стальгорн: {n:0:alliance:Reyna Stonebranch}",
  ["Darnassus: {n:0:alliance:Firodren Mooncaller}"] = "Дарнас: {n:0:alliance:Firodren Mooncaller}",
  ["{n:0:alliance:Nancy Songflower} (only up to 75) {n:0:alliance:Herbalist Pomeroy}"] = "{n:0:alliance:Nancy Songflower} (только до 75) {n:0:alliance:Herbalist Pomeroy}",
  ["{n:0:alliance:Emrys Flintbeard} (only up to 75) {n:0:alliance:Reyna Stonebranch} in Ironforge"] = "{n:0:alliance:Emrys Flintbeard} (только до 75) {n:0:alliance:Reyna Stonebranch} в Стальгорне",
  ["{n:0:alliance:Eleyna Duskbreeze} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Malorne Bladeleaf} in Dolanaar"] = "{n:0:alliance:Eleyna Duskbreeze} у Альдрассила в Тенистой долине (только до 75) {n:0:alliance:Malorne Bladeleaf} в Доланааре",
  ["You can find every Herbalism trainer for Horde and Alliance on my WoW Forever Herbalism Trainers page."] = "Всех учителей травничества Орды и Альянса ты найдешь на моей странице «WoW Forever Herbalism Trainers».",
  ["Track Herbs on Your Minimap"] = "Отслеживание трав на миникарте",
  ["You can only track one thing at a time, so {b}you can't track herbs and minerals together{/b}."] = "Отслеживать можно только что-то одно, так что {b}травы и руду одновременно отслеживать нельзя{/b}.",
  ["You learn {s:2383:inv_misc_flower_02:Find Herbs} together with Herbalism, but it's not turned on by default:"] = "{s:2383:inv_misc_flower_02:Find Herbs} ты получаешь вместе с травничеством, но по умолчанию поиск не включен:",
  ["Click Find Herbs in the Herbalism box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "Нажми «Поиск трав» в блоке травничества. {b}Советую перетащить его на панель команд, поближе к баффам, которые ты используешь после смерти.{/b} Так это войдет в привычку и ты реже будешь о нем забывать.",
  ["The Find Herbs buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "Бафф «Поиск трав» появится рядом с миникартой. {b}Отслеживание выключается при каждой смерти, так что не забывай включать его снова!{/b}",
  ["Herbalism Skill Bonuses"] = "Бонусы к навыку травничества",
  ["You don't need these, but they help when you are stuck between two herbs. With +5 you can pick Kingsblood from 120 instead of 125, so you can move on earlier."] = "Они не обязательны, но помогают, когда застрял между двумя травами. С +5 можно собирать королевскую кровь со 120 вместо 125, так что двигаться дальше можно раньше.",
  ["Herbalism"] = "Травничество",
  ["A world drop, check the Auction House"] = "Добыча в мире, смотри на аукционе",
  ["Henry Stern in Razorfen Downs teaches the recipe, it {b}requires Cooking 175{/b}. Take the left path at the start of the instance and go all the way to the end, to the stables, knock down the walls and talk to him."] = "Рецепту обучает Генри Стерн в Курганах Иглошкурых, {b}нужна Кулинария 175{/b}. В начале подземелья иди по левой дороге до самого конца, к конюшням, сломай стены и поговори с ним.",
  ["can be very handy when you find a herb you can't pick yet and you are only a few points short. It will probably be pretty expensive early on because of the Goldthorn prices, but it's worth keeping a few with you while you level Herbalism."] = "очень выручает, когда находишь траву, которую еще не можешь собрать, а до нужного навыка не хватает всего пары очков. Поначалу он, скорее всего, будет довольно дорогим из-за цен на златошип, но пока качаешь травничество, стоит держать при себе несколько штук.",
  ["Every starting zone is full of herbs, so it doesn't really matter which one you choose. The respawn rate is so fast that without a mount you often can't even finish a full lap, you just run around in circles and pick the herbs as you see them."] = "Все стартовые зоны полны трав, так что неважно, какую выбрать. Травы возрождаются так быстро, что без маунта часто не успеваешь даже пройти полный круг: просто бегаешь кругами и собираешь все, что видишь.",
  ["Herbs in these zones: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}"] = "Травы в этих зонах: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}",
  ["Earthroot requires Herbalism 15."] = "Для земляного корня нужно Травничество 15.",
  ["Herbalism route in Durotar"] = "Маршрут сбора трав в Дуротаре",
  ["Herbalism route in Mulgore"] = "Маршрут сбора трав в Мулгоре",
  ["Herbalism route in Tirisfal Glades"] = "Маршрут сбора трав в Тирисфальских лесах",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism."] = "{q:93552::Harvesting Windstones} - одно из первых заданий в деревне Тендал. Выбери в награду {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest}, она обучает травничеству.",
  ["Herbalism route on Zephras Isle"] = "Маршрут сбора трав на Острове Зефрас",
  ["Herbalism route in Elwynn Forest"] = "Маршрут сбора трав в Элвиннском лесу",
  ["Herbalism route in Dun Morogh"] = "Маршрут сбора трав в Дун Мороге",
  ["Herbalism route in Teldrassil"] = "Маршрут сбора трав в Тельдрассиле",
  ["Visit your trainer and learn Journeyman Herbalism, it requires Herbalism 50. The new Junior Herbalism Trainers in the starting areas won't teach you Journeyman Herbalism."] = "Зайди к учителю и выучи травничество уровня Подмастерье, для этого нужно Травничество 50. Новые младшие учителя травничества в стартовых зонах уровню Подмастерье не обучают.",
  ["Herbs in these zones: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}"] = "Травы в этих зонах: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}",
  ["Stranglekelp requires Herbalism 85, so you can't pick it right away."] = "Для удавника нужно Травничество 85, так что сразу собирать его не получится.",
  ["Loch Modan"] = "Лок Модан",
  ["The respawn rate in the lower part of Silverpine Forest is fast enough that you can basically run in small circles in the marked area. I tested this without a mount, so with a mount it might be different, but then running up and down the main road to the loop should work fine as well."] = "В нижней части Серебряного бора травы возрождаются достаточно быстро, чтобы можно было бегать небольшими кругами по отмеченной области. Я проверял без маунта, с маунтом может быть иначе, но тогда тоже должно нормально работать, если бегать вверх-вниз по главной дороге до петли.",
  ["Herbalism route in Silverpine Forest"] = "Маршрут сбора трав в Серебряном бору",
  ["A very easy route to follow, but there might be a bit fewer herbs than in Darkshore."] = "Очень простой маршрут, но трав здесь может быть чуть меньше, чем на Темных берегах.",
  ["Herbalism route in Loch Modan"] = "Маршрут сбора трав в Лок Модане",
  ["Darkshore has herbs everywhere. I used this loop, but you can also expand it to the upper part of the map. The respawn rate is fast, so you can do smaller circles in different areas. I just found this route pretty easy and chill to follow."] = "На Темных берегах травы повсюду. Я ходил по этой петле, но можно расширить ее на верхнюю часть карты. Травы возрождаются быстро, так что можно ходить небольшими кругами в разных местах. Мне просто показалось, что по этому маршруту ходить легко и спокойно.",
  ["Herbalism route in Darkshore"] = "Маршрут сбора трав на Темных берегах",
  ["To train past 150, visit your trainer and learn Expert Herbalism, it requires Herbalism 125."] = "Чтобы учиться дальше 150, зайди к учителю и выучи травничество уровня Умелец, для этого нужно Травничество 125.",
  ["Herbs in these zones: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}"] = "Травы в этих зонах: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}",
  ["Kingsblood requires Herbalism 125 and Liferoot 150, so you can't pick them right away."] = "Для королевской крови нужно Травничество 125, для корня жизни 150, так что сразу собирать их не получится.",
  ["Running this loop in Hillsbrad Foothills gives the herbs enough time to respawn, but I tested it without a mount, so with a mount it might be different."] = "Если бегать по этой петле в Предгорьях Хилсбрада, травы успевают возродиться, но я проверял без маунта, с маунтом может быть иначе.",
  ["Herbalism route in Hillsbrad Foothills"] = "Маршрут сбора трав в Предгорьях Хилсбрада",
  ["All three areas are good here:"] = "Здесь хороши все три области:",
  ["The mobs here are only around level 14-15, so this is the lowest level area where you can safely farm these herbs."] = "Монстры здесь всего около 14-15-го уровня, так что это самая низкоуровневая область, где можно безопасно собирать эти травы.",
  ["A good alternative if someone is already farming the first area. The mobs are higher level here, around 25."] = "Хорошая альтернатива, если в первой области уже кто-то фармит. Монстры здесь выше уровнем, около 25-го.",
  ["This area is usually pretty crowded and full of mobs. {b}I only recommend it if you are over 125 already{/b}, because there is more Kingsblood here."] = "Здесь обычно довольно людно и полно монстров. {b}Советую ее, только если у тебя уже больше 125{/b}, потому что королевской крови здесь больше.",
  ["Herbalism route in Stonetalon Mountains"] = "Маршрут сбора трав в Когтистых горах",
  ["From this point the guide follows the standard Classic Herbalism routes. The beta cap was 30, so I couldn't test the higher level routes. I'll revise this section once I level my character higher on live, but the main change is the herb respawn rate, so most routes should work."] = "Начиная отсюда руководство следует стандартным маршрутам травничества из Classic. На бете был предел 30-го уровня, так что маршруты более высокого уровня я проверить не смог. Я переработаю этот раздел, когда прокачаю персонажа выше на живом сервере, но главное изменение - скорость возрождения трав, так что большинство маршрутов должны работать.",
  ["Herbs in these zones: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}"] = "Травы в этих зонах: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}",
  ["Khadgar's Whisker requires Herbalism 185, so you can't pick it right away."] = "Для кадгарова уса нужно Травничество 185, так что сразу собирать его не получится.",
  ["Stranglethorn Vale"] = "Тернистая долина",
  ["Herbalism route in Stranglethorn Vale"] = "Маршрут сбора трав в Тернистой долине",
  ["Herbalism route in Arathi Highlands"] = "Маршрут сбора трав в Нагорье Арати",
  ["{b}Learn Artisan Herbalism before you leave for these zones{/b}, it requires Herbalism 200. There is no trainer in Tanaris or Searing Gorge, so if you skip it, you have to fly back at 225."] = "{b}Выучи травничество уровня Мастер, прежде чем отправиться в эти зоны{/b}, для этого нужно Травничество 200. В Танарисе и Тлеющем ущелье учителя нет, так что если пропустишь, на 225 придется лететь обратно.",
  ["Herbs in these zones: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}"] = "Травы в этих зонах: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}",
  ["Searing Gorge"] = "Тлеющее ущелье",
  ["Herbalism route in Tanaris"] = "Маршрут сбора трав в Танарисе",
  ["Herbalism route in Searing Gorge"] = "Маршрут сбора трав в Тлеющем ущелье",
  ["Herbs in The Hinterlands: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}"] = "Травы во Внутренних землях: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}",
  ["I marked a cave with a red X, there are a lot of Ghost Mushrooms in the cave, but you can only pick them with Herbalism 245."] = "Я отметил пещеру красным крестиком: в ней много призрачных поганок, но собирать их можно только с Травничеством 245.",
  ["Herbalism route in The Hinterlands"] = "Маршрут сбора трав во Внутренних землях",
  ["Herbs in Felwood: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}"] = "Травы в Оскверненном лесу: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}",
  ["Herbalism route in Felwood"] = "Маршрут сбора трав в Оскверненном лесу",
  ["This WoW Forever Skinning leveling guide will show you the fastest way to level Skinning from 1 to 300. You will also find every trainer location and the best places to skin for each skill range."] = "Это руководство по прокачке снятия шкур для WoW Forever покажет тебе самый быстрый способ поднять снятие шкур с 1 до 300. Здесь же ты найдешь всех учителей и лучшие места для снятия шкур на каждом диапазоне навыка.",
  ["This guide is aimed at higher level players who want to switch their profession, but it's good for lower level players too. Leveling Skinning is easy but really boring, you will have to run around and skin hundreds of mobs. Skinning goes well with Leatherworking because you can use the leather you skin, so check out my Forever Leatherworking leveling guide if you want to level Leatherworking."] = "Это руководство рассчитано на игроков высокого уровня, которые хотят сменить профессию, но подойдет и игрокам пониже уровнем. Качать снятие шкур легко, но очень скучно: придется бегать и свежевать сотни монстров. Снятие шкур хорошо сочетается с кожевничеством, ведь снятую кожу можно пустить в дело, так что загляни в мое руководство по кожевничеству для Forever, если хочешь прокачать кожевничество.",
  ["Skinning Trainer Locations"] = "Где найти учителей снятия шкур",
  ["Every capital city has a Skinning trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Учитель снятия шкур есть в каждой столице. Можно также спросить стражника, и тогда учитель будет отмечен красным флажком на карте.",
  ["Orgrimmar: {n:0:horde:Thuwd}"] = "Оргриммар: {n:0:horde:Thuwd}",
  ["Undercity: {n:0:horde:Killian Hagey}"] = "Подгород: {n:0:horde:Killian Hagey}",
  ["Thunder Bluff: {n:0:horde:Mooranta}"] = "Громовой Утес: {n:0:horde:Mooranta}",
  ["{n:0:horde:Kagil} in the Valley of Trials (only up to 75) {n:0:horde:Thuwd} in Orgrimmar"] = "{n:0:horde:Kagil} в Долине Испытаний (только до 75) {n:0:horde:Thuwd} в Оргриммаре",
  ["{n:0:horde:Nawka Wildsong} in Camp Narache (only up to 75) {n:0:horde:Yonn Deepcut} in Bloodhoof Village"] = "{n:0:horde:Nawka Wildsong} в Лагере Нараче (только до 75) {n:0:horde:Yonn Deepcut} в деревне Кровавого Копыта",
  ["{n:0:horde:Margaret Weaver} in Deathknell (only up to 75) {n:0:horde:Rand Rhobart} in Tirisfal Glades"] = "{n:0:horde:Margaret Weaver} в Похоронном Звоне (только до 75) {n:0:horde:Rand Rhobart} в Тирисфальских лесах",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} as your reward, it teaches you Skinning. The trainers on the island are {n:0::Ishlee Breezewhisper} in Valanaar and {n:0::Mendalass Tattermend} in Shen'dar Village."] = "В деревне Тендал, где ты начинаешь, учителя нет, но он и не нужен. {q:93552::Harvesting Windstones} - одно из первых заданий в деревне Тендал. Выбери в награду {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners}, она обучает снятию шкур. Учителя на острове: {n:0::Ishlee Breezewhisper} в Валанааре и {n:0::Mendalass Tattermend} в деревне Шен'дар.",
  ["Stormwind City: {n:0:alliance:Maris Granger}"] = "Штормград: {n:0:alliance:Maris Granger}",
  ["Ironforge: {n:0:alliance:Balthus Stoneflayer}"] = "Стальгорн: {n:0:alliance:Balthus Stoneflayer}",
  ["Darnassus: {n:0:alliance:Eladriel}"] = "Дарнас: {n:0:alliance:Eladriel}",
  ["{n:0:alliance:Riley Peltskinner} in Northshire Valley (only up to 75) {n:0:alliance:Helene Peltskinner} in Goldshire"] = "{n:0:alliance:Riley Peltskinner} в Долине Североземья (только до 75) {n:0:alliance:Helene Peltskinner} в Златоземье",
  ["{n:0:alliance:Brighid Stormflayer} (only up to 75) {n:0:alliance:Balthus Stoneflayer} in Ironforge"] = "{n:0:alliance:Brighid Stormflayer} (только до 75) {n:0:alliance:Balthus Stoneflayer} в Стальгорне",
  ["{n:0:alliance:Terunne Bearshaper} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Radnaal Maneweaver} in Teldrassil"] = "{n:0:alliance:Terunne Bearshaper} у Альдрассила в Тенистой долине (только до 75) {n:0:alliance:Radnaal Maneweaver} в Тельдрассиле",
  ["You can find every Skinning trainer for Horde and Alliance on my WoW Forever Skinning Trainers page."] = "Всех учителей снятия шкур Орды и Альянса ты найдешь на моей странице «WoW Forever Skinning Trainers».",
  ["Skinning Skill Requirements"] = "Требования к навыку снятия шкур",
  ["You need 5 times the mob's level in Skinning to skin it, so a level 30 mob needs Skinning 150. Below level 20 it's less, if you follow the guide you don't have to worry about this."] = "Чтобы снять шкуру с монстра, нужен навык снятия шкур в 5 раз больше его уровня, так что для монстра 30-го уровня нужно Снятие шкур 150. Ниже 20-го уровня требуется меньше, и если следовать руководству, об этом можно не беспокоиться.",
  ["Mob level"] = "Уровень монстра",
  ["Skinning needed"] = "Нужный навык",
  ["10 for a level 11 mob, 10 more for every level (level 15 needs 50, level 19 needs 90)"] = "10 для монстра 11-го уровня, плюс 10 за каждый уровень (для 15-го нужно 50, для 19-го нужно 90)",
  ["20 and up"] = "20 и выше",
  ["5 times the level"] = "Уровень, умноженный на 5",
  ["If you enchant your gloves with {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}, you can skin mobs 1 level higher than normal."] = "Если зачаровать перчатки {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}, можно снимать шкуры с монстров на 1 уровень выше обычного.",
  ["Horde players can also pick the {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 Skinning) as a reward from Unwelcome Guests in The Barrens."] = "Игроки Орды могут также выбрать {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 к снятию шкур) в награду за Unwelcome Guests в Степях.",
  ["In WoW Forever you can skin the mobs in the starting areas, and they give skill points all the way up to 75."] = "В WoW Forever можно снимать шкуры с монстров в стартовых зонах, и они дают очки навыка вплоть до 75.",
  ["{b}Any starting zone is good{/b} for this. If you are leveling a new character, you can skin any mob in your starting zone, so you don't need a recommendation until around level 10, when you leave the zone. The two places below are for players who already have a higher level character and want to catch up on Skinning. A lot of players will be leveling new characters there, so there is always something to skin."] = "{b}Для этого подходит любая стартовая зона{/b}. Если качаешь нового персонажа, можно свежевать любых монстров в своей стартовой зоне, так что рекомендации не нужны примерно до 10-го уровня, когда ты покинешь зону. Два места ниже - для игроков, у которых уже есть персонаж высокого уровня и которые хотят догнать снятие шкур. Там многие будут качать новых персонажей, так что свежевать всегда будет кого.",
  ["{b}Don't forget to buy a {i:7005:inv_weapon_shortblade_01:Skinning Knife}!{/b} The Leatherworking Supply vendors near your trainer and most General Goods vendors sell it. You don't have to equip it, but you can't skin without one in your bags."] = "{b}Не забудь купить {i:7005:inv_weapon_shortblade_01:Skinning Knife}!{/b} Его продают торговцы кожевенными товарами рядом с учителем и большинство торговцев товарами повседневного спроса. Экипировать его не нужно, но без него в сумке снимать шкуры нельзя.",
  ["Skin the {n:3098::Mottled Boars} in the Valley of Trials in Durotar."] = "Снимай шкуры с {n:3098::Mottled Boars} в Долине Испытаний в Дуротаре.",
  ["{b}Mob level:{/b} 1-2"] = "{b}Уровень монстров:{/b} 1-2",
  ["The Mottled Boars in the Valley of Trials in Durotar"] = "Пятнистые вепри в Долине Испытаний в Дуротаре",
  ["Skin the {n:299::Young Wolves} and {n:69::Timber Wolves} in Northshire Valley in Elwynn Forest."] = "Снимай шкуры с {n:299::Young Wolves} и {n:69::Timber Wolves} в Долине Североземья в Элвиннском лесу.",
  ["The wolves in Northshire Valley in Elwynn Forest"] = "Волки в Долине Североземья в Элвиннском лесу",
  ["Visit your trainer and learn Journeyman Skinning if you haven't yet, it requires Skinning 50. The new Junior Skinning Trainers in the starting areas won't teach you Journeyman Skinning."] = "Зайди к учителю и выучи снятие шкур уровня Подмастерье, если еще не выучил, для этого нужно Снятие шкур 50. Новые младшие учителя снятия шкур в стартовых зонах уровню Подмастерье не обучают.",
  ["To train past 150, visit your trainer again and learn Expert Skinning when you reach 125."] = "Чтобы учиться дальше 150, на 125 снова зайди к учителю и выучи снятие шкур уровня Умелец.",
  ["Kill and skin {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}."] = "Убивай и свежуй {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}.",
  ["Go to the small raptor camp just west of Northwatch Hold. Skin the level 16-17 ones until 80, from 80 you can skin the level 18 ones too. Stay here until 150, the last 10 points are green but the respawn is fast."] = "Иди в небольшой лагерь ящеров к западу от Северной стражи. До 80 свежуй тех, что 16-17-го уровня, с 80 можно и 18-го. Оставайся здесь до 150: последние 10 очков зеленые, но возрождение быстрое.",
  ["{b}Mob level:{/b} 16-18"] = "{b}Уровень монстров:{/b} 16-18",
  ["The Sunscale Scytheclaws west of Northwatch Hold in the Barrens"] = "Солнечночешуйчатые серпокоготники к западу от Северной стражи в Степях",
  ["75-125 Loch Modan"] = "75-125 Лок Модан",
  ["Kill and skin {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}."] = "Убивай и свежуй {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}.",
  ["{n:1693::Loch Crocolisk} are also skinnable, make sure to pull them when you get to the shore."] = "С {n:1693::Loch Crocolisk} тоже можно снимать шкуры, обязательно агрь их, когда дойдешь до берега.",
  ["Stay here until around 125, then head north to the Wetlands, it is on the way to Hillsbrad."] = "Оставайся здесь примерно до 125, а затем иди на север в Болотину, она по пути в Хилсбрад.",
  ["{b}Mob level:{/b} 16-17"] = "{b}Уровень монстров:{/b} 16-17",
  ["Skinning spot in Loch Modan"] = "Место для снятия шкур в Лок Модане",
  ["125-150 Wetlands"] = "125-150 Болотина",
  ["Kill and skin {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}."] = "Убивай и свежуй {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}.",
  ["There are always a few of them at Whelgar's Excavation Site, so you never run out of mobs to kill."] = "На раскопках Вельгара их всегда несколько, так что монстры для убийства не кончатся.",
  ["{b}Mob level:{/b} 25-27"] = "{b}Уровень монстров:{/b} 25-27",
  ["Whelgar's Excavation Site in the Wetlands"] = "Раскопки Вельгара в Болотине",
  ["From 150, go to the Foothill Caverns in Hillsbrad Foothills, the yeti cave on the border of Alterac Mountains, or to the Rotting Orchard in Duskwood."] = "Со 150 иди в Пещеры Предгорий в Предгорьях Хилсбрада, пещеру йети на границе с Альтеракскими горами, или в Гнилой сад в Сумеречном лесу.",
  ["Duskwood"] = "Сумеречный лес",
  ["Both factions can get there, Horde from Tarren Mill and Alliance from Southshore."] = "Туда могут добраться обе фракции: Орда из Мельницы Таррен, Альянс из Южнобережья.",
  ["Kill and skin {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}."] = "Убивай и свежуй {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}.",
  ["The yetis respawn so fast that you can stay inside the cave the whole time."] = "Йети возрождаются так быстро, что можно все время оставаться в пещере.",
  ["{b}Mob level:{/b} 30-32"] = "{b}Уровень монстров:{/b} 30-32",
  ["The Foothill Caverns in Hillsbrad Foothills"] = "Пещеры Предгорий в Предгорьях Хилсбрада",
  ["Duskwood is an Alliance zone, but Grom'gol is close, so Horde players can get there too."] = "Сумеречный лес - зона Альянса, но Гром'гол рядом, так что игроки Орды тоже могут туда добраться.",
  ["Kill and skin {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}."] = "Убивай и свежуй {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}.",
  ["Start at the area marked with 1, clear the mobs outside and inside Roland's Doom cave, then go to the Rotting Orchard until the mobs respawn."] = "Начни с области, отмеченной цифрой 1, зачисти монстров снаружи и внутри пещеры Погибели Роланда, а затем иди в Гнилой сад, пока монстры не возродятся.",
  ["{b}Mob level:{/b} 26-29"] = "{b}Уровень монстров:{/b} 26-29",
  ["Roland's Doom and the Rotting Orchard in Duskwood"] = "Погибель Роланда и Гнилой сад в Сумеречном лесу",
  ["Visit your trainer and learn Artisan Skinning, it requires Skinning 200."] = "Зайди к учителю и выучи снятие шкур уровня Мастер, для этого нужно Снятие шкур 200.",
  ["Mount up and go to the yeti cave at Feral Scar Vale in the south of Feralas. Both factions can get there, Horde from Camp Mojache and Alliance from Feathermoon Stronghold."] = "Садись на маунта и иди в пещеру йети в Долине Диких Шрамов на юге Фераласа. Туда могут добраться обе фракции: Орда из Лагеря Мохаче, Альянс из Крепости Оперенной Луны.",
  ["Kill and skin {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}."] = "Убивай и свежуй {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}.",
  ["{b}Mob level:{/b} 43-46"] = "{b}Уровень монстров:{/b} 43-46",
  ["The yeti cave at Feral Scar Vale in Feralas"] = "Пещера йети в Долине Диких Шрамов в Фераласе",
  ["From 280, fly to Marshal's Refuge and skin the dinosaurs in the western part of Un'Goro Crater."] = "С 280 лети в Укрытие Маршала и свежуй динозавров в западной части Кратера Ун'Горо.",
  ["Kill and skin {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}."] = "Убивай и свежуй {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}.",
  ["{b}Mob level:{/b} 50-55"] = "{b}Уровень монстров:{/b} 50-55",
  ["The dinosaur area in the west of Un'Goro Crater"] = "Область с динозаврами на западе Кратера Ун'Горо",
  ["This WoW Forever Fishing and Cooking leveling guide will show you the fastest way to level Fishing and Cooking together from 1 to 300."] = "Это руководство по прокачке рыбной ловли и кулинарии для WoW Forever покажет тебе самый быстрый способ поднять рыбную ловлю и кулинарию вместе с 1 до 300.",
  ["Leveling Fishing takes a long time, so it's best to level these two together, because every fish you catch is also a Cooking recipe and your Cooking goes up for free while you fish. You will still need a lot of patience because you have to catch a lot of fish to get from start to finish. If you only want one of them, use my Fishing guide or my Cooking guide instead."] = "Рыбная ловля качается долго, поэтому лучше качать эти две профессии вместе: каждая пойманная рыба - это еще и рецепт кулинарии, так что кулинария растет бесплатно, пока ты рыбачишь. Терпения все равно понадобится много, ведь от начала до конца придется поймать кучу рыбы. Если нужна только одна из них, используй вместо этого мое руководство по рыбной ловле или по кулинарии.",
  ["Level Fishing to 75"] = "Прокачай рыбную ловлю до 75",
  ["If you can choose, {b}level Fishing in Mulgore{/b}, because everything is close together there. {n:0::Harn Longcast} in Bloodhoof Village sells both recipes and the pole, and the Fishing trainer stands at Stonebull Lake. Thunder Bluff, where you fish after 75, is right next to it."] = "Если есть выбор, {b}качай рыбную ловлю в Мулгоре{/b}, там все рядом. {n:0::Harn Longcast} в деревне Кровавого Копыта продает оба рецепта и удочку, а учитель рыбной ловли стоит у озера Каменного Быка. Громовой Утес, где ты будешь рыбачить после 75, совсем рядом.",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lau'Tiki} on the coast south of Sen'jin Village."] = "Если ты еще не выучил рыбную ловлю, выучи ее у {n:0::Lau'Tiki} на побережье к югу от деревни Сен'джин.",
  ["Buy {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} from {n:0::Zansoa} in Sen'jin Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Купи {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} у {n:0::Zansoa} в деревне Сен'джин. Там же купи {i:6256:inv_fishingpole_02:Fishing Pole} и {i:6529:inv_misc_orb_03:Shiny Bauble}. (Покупай любой {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, который увидишь, и сохрани на потом.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish on the coast next to {n:0::Lau'Tiki}, south of Sen'jin Village, until your Fishing skill reaches 75. Almost everything you catch there is {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, about 70 of them."] = "Возьми удочку, прицепи {i:6529:inv_misc_orb_03:Shiny Bauble} и рыбачь на побережье рядом с {n:0::Lau'Tiki}, к югу от деревни Сен'джин, пока навык рыбной ловли не дойдет до 75. Почти все, что ты там поймаешь, - это {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, около 70 штук.",
  ["Learn Journeyman Fishing from {n:0::Lau'Tiki}, it requires level 10."] = "Выучи рыбную ловлю уровня Подмастерье у {n:0::Lau'Tiki}, для этого нужен 10-й уровень.",
  ["The coast south of Sen'jin Village in Durotar, where to fish from 1 to 75"] = "Побережье к югу от деревни Сен'джин в Дуротаре, где рыбачить с 1 до 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Uthan Stillwater} at Stonebull Lake."] = "Если ты еще не выучил рыбную ловлю, выучи ее у {n:0::Uthan Stillwater} у озера Каменного Быка.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Harn Longcast} in Bloodhoof Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Купи {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} и {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} у {n:0::Harn Longcast} в деревне Кровавого Копыта. Там же купи {i:6256:inv_fishingpole_02:Fishing Pole} и {i:6529:inv_misc_orb_03:Shiny Bauble}. (Покупай любой {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, который увидишь, и сохрани на потом.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Stonebull Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Возьми удочку, прицепи {i:6529:inv_misc_orb_03:Shiny Bauble} и рыбачь в озере Каменного Быка, пока навык рыбной ловли не дойдет до 75. Поймаешь около 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} и 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Uthan Stillwater}, it requires level 10."] = "Выучи рыбную ловлю уровня Подмастерье у {n:0::Uthan Stillwater}, для этого нужен 10-й уровень.",
  ["Stonebull Lake around Bloodhoof Village in Mulgore, where to fish from 1 to 75"] = "Озеро Каменного Быка у деревни Кровавого Копыта в Мулгоре, где рыбачить с 1 до 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Clyde Kellen} at Brightwater Lake."] = "Если ты еще не выучил рыбную ловлю, выучи ее у {n:0::Clyde Kellen} у озера Светлой Воды.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Martine Tramblay} at the Death's Watch Waystation, south-east of Brill. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Купи {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} у {n:0::Martine Tramblay} на заставе Смертного Дозора, к юго-востоку от Брилла. Там же купи {i:6256:inv_fishingpole_02:Fishing Pole} и {i:6529:inv_misc_orb_03:Shiny Bauble}. (Покупай любой {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, который увидишь, и сохрани на потом.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Brightwater Lake until your Fishing skill reaches 75. You will catch about 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, plus some {i:6299:inv_misc_fish_28:Sickly Looking Fish} and junk."] = "Возьми удочку, прицепи {i:6529:inv_misc_orb_03:Shiny Bauble} и рыбачь в озере Светлой Воды, пока навык рыбной ловли не дойдет до 75. Поймаешь около 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} и 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, а также немного {i:6299:inv_misc_fish_28:Sickly Looking Fish} и хлама.",
  ["Learn Journeyman Fishing from {n:0::Clyde Kellen}, it requires level 10."] = "Выучи рыбную ловлю уровня Подмастерье у {n:0::Clyde Kellen}, для этого нужен 10-й уровень.",
  ["Brightwater Lake east of Brill in Tirisfal Glades, where to fish from 1 to 75"] = "Озеро Светлой Воды к востоку от Брилла в Тирисфальских лесах, где рыбачить с 1 до 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Fenn Fairweather} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar."] = "Если ты еще не выучил рыбную ловлю, выучи ее у {n:0::Fenn Fairweather} в деревне Шен'дар или у {n:0::Baelann Swiftcurrent} в Валанааре.",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Belandiel Farflight} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Купи {i:6256:inv_fishingpole_02:Fishing Pole} и {i:6529:inv_misc_orb_03:Shiny Bauble} у {n:0::Belandiel Farflight} в деревне Шен'дар или у {n:0::Baelann Swiftcurrent} в Валанааре. (Покупай любой {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, который увидишь, и сохрани на потом.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in any lake or river on Zephras Isle until your Fishing skill reaches 75, for example next to the Fishing trainers in Shen'dar Village and Valanaar. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Keep all the fish you catch."] = "Возьми удочку, прицепи {i:6529:inv_misc_orb_03:Shiny Bauble} и рыбачь в любом озере или реке на Острове Зефрас, пока навык рыбной ловли не дойдет до 75, например рядом с учителями рыбной ловли в деревне Шен'дар и Валанааре. Поймаешь около 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} и 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Сохрани всю пойманную рыбу.",
  ["Learn Journeyman Fishing from {n:0::Fenn Fairweather} or {n:0::Baelann Swiftcurrent}, it requires level 10."] = "Выучи рыбную ловлю уровня Подмастерье у {n:0::Fenn Fairweather} или {n:0::Baelann Swiftcurrent}, для этого нужен 10-й уровень.",
  ["When you get to Thunder Bluff, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Sewa Mistrunner} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Naal Mistrunner}. They stand next to each other."] = "Когда доберешься до Громового Утеса, купи {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} у {n:0::Sewa Mistrunner} и {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} у {n:0::Naal Mistrunner}. Они стоят рядом.",
  ["The water at Shen'dar Village and Valanaar on Zephras Isle, where to fish from 1 to 75"] = "Вода у деревни Шен'дар и Валанаара на Острове Зефрас, где рыбачить с 1 до 75",
  ["If you can choose, {b}level Fishing in Elwynn Forest{/b}, because everything is close together there. {n:0::Tharynn Bouden} in Goldshire sells both recipes and the pole, and the Fishing trainer stands at Crystal Lake. Stormwind City, where you fish after 75, is right next to it."] = "Если есть выбор, {b}качай рыбную ловлю в Элвиннском лесу{/b}, там все рядом. {n:0::Tharynn Bouden} в Златоземье продает оба рецепта и удочку, а учитель рыбной ловли стоит у Хрустального озера. Штормград, где ты будешь рыбачить после 75, совсем рядом.",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lee Brown} at Crystal Lake."] = "Если ты еще не выучил рыбную ловлю, выучи ее у {n:0::Lee Brown} у Хрустального озера.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Купи {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} и {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} у {n:0::Tharynn Bouden} в Златоземье. Там же купи {i:6256:inv_fishingpole_02:Fishing Pole} и {i:6529:inv_misc_orb_03:Shiny Bauble}. (Покупай любой {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, который увидишь, и сохрани на потом.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Crystal Lake, east of Goldshire, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Возьми удочку, прицепи {i:6529:inv_misc_orb_03:Shiny Bauble} и рыбачь в Хрустальном озере, к востоку от Златоземья, пока навык рыбной ловли не дойдет до 75. Поймаешь около 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} и 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Lee Brown}, it requires level 10."] = "Выучи рыбную ловлю уровня Подмастерье у {n:0::Lee Brown}, для этого нужен 10-й уровень.",
  ["Crystal Lake east of Goldshire in Elwynn Forest, where to fish from 1 to 75"] = "Хрустальное озеро к востоку от Златоземья в Элвиннском лесу, где рыбачить с 1 до 75",
  ["If you haven't learned Fishing yet, learn it from {n:0::Paxton Ganter} at Iceflow Lake."] = "Если ты еще не выучил рыбную ловлю, выучи ее у {n:0::Paxton Ganter} у озера Ледяного Потока.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Gretta Ganter} at Iceflow Lake. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Купи {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} у {n:0::Gretta Ganter} у озера Ледяного Потока. Там же купи {i:6256:inv_fishingpole_02:Fishing Pole} и {i:6529:inv_misc_orb_03:Shiny Bauble}. (Покупай любой {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, который увидишь, и сохрани на потом.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Iceflow Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Возьми удочку, прицепи {i:6529:inv_misc_orb_03:Shiny Bauble} и рыбачь в озере Ледяного Потока, пока навык рыбной ловли не дойдет до 75. Поймаешь около 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} и 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Paxton Ganter}, it requires level 10."] = "Выучи рыбную ловлю уровня Подмастерье у {n:0::Paxton Ganter}, для этого нужен 10-й уровень.",
  ["Iceflow Lake in Dun Morogh, where to fish from 1 to 75"] = "Озеро Ледяного Потока в Дун Мороге, где рыбачить с 1 до 75",
  ["Learn Fishing from {n:0::Astaia} in Darnassus. There is no Fishing trainer in Dolanaar."] = "Выучи рыбную ловлю у {n:0::Astaia} в Дарнасе. В Доланааре учителя рыбной ловли нет.",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Nyoma} in Dolanaar."] = "Купи {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} и {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} у {n:0::Nyoma} в Доланааре.",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Narret Shadowgrove} in Dolanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "Купи {i:6256:inv_fishingpole_02:Fishing Pole} и {i:6529:inv_misc_orb_03:Shiny Bauble} у {n:0::Narret Shadowgrove} в Доланааре. (Покупай любой {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}, который увидишь, и сохрани на потом.)",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Lake Al'Ameth, south of Dolanaar, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "Возьми удочку, прицепи {i:6529:inv_misc_orb_03:Shiny Bauble} и рыбачь в озере Аль'Амет, к югу от Доланаара, пока навык рыбной ловли не дойдет до 75. Поймаешь около 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} и 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}.",
  ["Learn Journeyman Fishing from {n:0::Astaia} in Darnassus, it requires level 10."] = "Выучи рыбную ловлю уровня Подмастерье у {n:0::Astaia} в Дарнасе, для этого нужен 10-й уровень.",
  ["Lake Al'Ameth south of Dolanaar in Teldrassil, where to fish from 1 to 75"] = "Озеро Аль'Амет к югу от Доланаара в Тельдрассиле, где рыбачить с 1 до 75",
  ["When you get to Stormwind City, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire, right outside the city."] = "Когда доберешься до Штормграда, купи {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} и {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} у {n:0::Tharynn Bouden} в Златоземье, прямо рядом с городом.",
  ["Fishing (75-130) and Cooking (1-100)"] = "Рыбная ловля (75-130) и кулинария (1-100)",
  ["Fishing"] = "Рыбная ловля",
  ["Fish in the capital city closest to you until your Fishing skill reaches 130. From 75 no fish gets away in any of them. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Рыбачь в ближайшей к тебе столице, пока навык рыбной ловли не дойдет до 130. С 75 ни в одной из них рыба не срывается. Поймаешь примерно 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} и 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["{b}Thunder Bluff:{/b} the pond near the Auction House."] = "{b}Громовой Утес:{/b} пруд у аукциона.",
  ["{b}Undercity:{/b} the canals. About a third of what you catch here is junk, so you get fewer fish."] = "{b}Подгород:{/b} каналы. Около трети улова здесь - хлам, так что рыбы будет меньше.",
  ["{b}Orgrimmar:{/b} the pond in the Valley of Honor, where the Fishing trainer stands."] = "{b}Оргриммар:{/b} пруд в Аллее Чести, где стоит учитель рыбной ловли.",
  ["Recipes to buy"] = "Какие рецепты купить",
  ["Buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Ronald Burch} in Undercity, you need it in the next part."] = "Купи {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} у {n:0::Naal Mistrunner} в Громовом Утесе или у {n:0::Ronald Burch} в Подгороде, он понадобится в следующей части.",
  ["If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Lizbeth Cromwell} in Undercity."] = "Если у тебя еще нет {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}, купи его у {n:0::Naal Mistrunner} в Громовом Утесе или у {n:0::Lizbeth Cromwell} в Подгороде.",
  ["Nobody sells them in Orgrimmar, so buy them on the Auction House or in Thunder Bluff."] = "В Оргриммаре их никто не продает, так что купи их на аукционе или в Громовом Утесе.",
  ["Cooking"] = "Кулинария",
  ["If you haven't learned Cooking yet, learn it from {n:0::Aska Mistrunner} in Thunder Bluff, {n:0::Eunice Burch} in Undercity or {n:0::Zamja} in Orgrimmar. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. If you caught {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel} in your starting zone, learn {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} and cook them into {s:7752:inv_misc_fish_24:Slitherskin Mackerel} instead. This should take your Cooking skill to 50."] = "Если ты еще не выучил кулинарию, выучи ее у {n:0::Aska Mistrunner} в Громовом Утесе, у {n:0::Eunice Burch} в Подгороде или у {n:0::Zamja} в Оргриммаре. Затем выучи {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} и приготовь всю {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, получив {s:7751:inv_misc_fish_07:Brilliant Smallfish}. Если в стартовой зоне ты наловил {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, выучи вместо этого {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} и приготовь из нее {s:7752:inv_misc_fish_24:Slitherskin Mackerel}. Это должно поднять кулинарию до 50.",
  ["If you are a few points short of 50, catch and cook a few more."] = "Если до 50 не хватает нескольких очков, налови и приготовь еще немного.",
  ["Learn Journeyman Cooking from the same trainer. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "Выучи кулинарию уровня Подмастерье у того же учителя. Затем выучи {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} и приготовь всех {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, получив {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Кулинария должна подняться выше 100.",
  ["Don't worry if you don't reach 100 Cooking with Longjaw Mud Snapper, you will catch more Raw Longjaw Mud Snapper later."] = "Не переживай, если с длинночелюстным илистым окунем не дойдешь до 100 в кулинарии, позже ты наловишь еще.",
  ["Fish in the canals of Stormwind City until your skill reaches 130. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Рыбачь в каналах Штормграда, пока навык не дойдет до 130. Поймаешь примерно 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} и 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Find {n:0::Catherine Leland} in Stormwind City and buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Tharynn Bouden} in Goldshire."] = "Найди {n:0::Catherine Leland} в Штормграде и купи {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. Если у тебя еще нет {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}, купи его у {n:0::Tharynn Bouden} в Златоземье.",
  ["You should also find {n:0::Ben Trias} and buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from him. You will need these later for the Artisan Cooking quest."] = "Найди также {n:0::Ben Trias} и купи у него 20 {i:8932:inv_misc_food_37:Alterac Swiss}. Он понадобится позже для задания на кулинарию уровня Мастер.",
  ["Learn Cooking from {n:0::Stephen Ryback} if you haven't yet. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. This should take your Cooking skill to 50."] = "Выучи кулинарию у {n:0::Stephen Ryback}, если еще не выучил. Затем выучи {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} и приготовь всю {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, получив {s:7751:inv_misc_fish_07:Brilliant Smallfish}. Это должно поднять кулинарию до 50.",
  ["Learn Journeyman Cooking from {n:0::Stephen Ryback} in Stormwind City. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "Выучи кулинарию уровня Подмастерье у {n:0::Stephen Ryback} в Штормграде. Затем выучи {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} и приготовь всех {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, получив {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Кулинария должна подняться выше 100.",
  ["Fishing (130-205) and Cooking (100-175)"] = "Рыбная ловля (130-205) и кулинария (100-175)",
  ["Expert Fishing needs {b}level 20{/b} and {b}Fishing 125{/b}, Expert Cooking needs {b}Cooking 125{/b}."] = "Для рыбной ловли уровня Умелец нужны {b}20-й уровень{/b} и {b}Рыбная ловля 125{/b}, для кулинарии уровня Умелец нужна {b}Кулинария 125{/b}.",
  ["Booty Bay"] = "Пиратская Бухта",
  ["Go to Ratchet in The Barrens and take the boat to Booty Bay in Stranglethorn Vale."] = "Иди в Кабестан в Степях и сядь на корабль до Пиратской Бухты в Тернистой долине.",
  ["Find {n:0::Old Man Heming} in Booty Bay, buy {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} from him and read it."] = "Найди {n:0::Old Man Heming} в Пиратской Бухте, купи у него {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} и прочитай.",
  ["Find {n:0::Kelsey Yance} and buy these two recipes: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}."] = "Найди {n:0::Kelsey Yance} и купи эти два рецепта: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}.",
  ["Go back to The Barrens, then fly from Ratchet to Sun Rock Retreat in Stonetalon Mountains and buy 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Kulwia}. You need 2 until 150, keep the other 5 for later."] = "Вернись в Степи, затем лети из Кабестана в Приют Солнечного Камня в Когтистых горах и купи 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} у {n:0::Kulwia}. До 150 понадобятся 2, остальные 5 сохрани на потом.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Прицепи {i:6530:inv_misc_monstertail_03:Nightcrawler} и рыбачь в открытой воде, пока навык рыбной ловли не дойдет до 205. Поймаешь около 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} и 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Fly to Shadowprey Village in Desolace."] = "Лети в Деревню Призрачной Охоты в Пустошах.",
  ["Find {n:0::Wulan} and buy the {i:16072:inv_misc_book_08:Expert Cookbook}. He is on the top floor of the eastern-most building in the village."] = "Найди {n:0::Wulan} и купи {i:16072:inv_misc_book_08:Expert Cookbook}. Он на верхнем этаже самого восточного здания в деревне.",
  ["Buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from {n:0::Innkeeper Sikewa}. You will need them for the Artisan Cooking quest."] = "Купи 20 {i:8932:inv_misc_food_37:Alterac Swiss} у {n:0::Innkeeper Sikewa}. Он понадобится для задания на кулинарию уровня Мастер.",
  ["Leveling Cooking to 175"] = "Прокачка кулинарии до 175",
  ["Cook your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper} if your Cooking skill is still below 100."] = "Если кулинария еще ниже 100, приготовь {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, получив {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}.",
  ["{b}Read the {i:16072:inv_misc_book_08:Expert Cookbook} as soon as you reach 125{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 150 and keep cooking for nothing."] = "{b}Прочитай {i:16072:inv_misc_book_08:Expert Cookbook}, как только дойдешь до 125{/b}, особенно если готовишь в АФК. Без нее на 150 очки навыка перестанут идти и ты будешь готовить впустую.",
  ["Learn {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} and cook all your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Your Cooking skill will hopefully get close to 175."] = "Выучи {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} и приготовь всех {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}, получив {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Кулинария, надеюсь, подойдет близко к 175.",
  ["Don't worry if you don't reach 175 Cooking with Bristle Whisker Catfish, you will catch more Raw Bristle Whisker Catfish later."] = "Не переживай, если с усатым сомом не дойдешь до 175 в кулинарии, позже ты наловишь еще.",
  ["Go to Booty Bay in Stranglethorn Vale."] = "Иди в Пиратскую Бухту в Тернистой долине.",
  ["Go to The Barrens, then fly from Ratchet to Astranaar in Ashenvale. Ride south-east to Mystral Lake and buy the {i:16072:inv_misc_book_08:Expert Cookbook} and 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Shandrina}. You need 2 until 150, keep the other 5 for later."] = "Иди в Степи, затем лети из Кабестана в Астранаар в Ясеневом лесу. Поезжай на юго-восток к озеру Мистраль и купи {i:16072:inv_misc_book_08:Expert Cookbook} и 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} у {n:0::Shandrina}. До 150 понадобятся 2, остальные 5 сохрани на потом.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water of Mystral Lake until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "Прицепи {i:6530:inv_misc_monstertail_03:Nightcrawler} и рыбачь в открытой воде озера Мистраль, пока навык рыбной ловли не дойдет до 205. Поймаешь около 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} и 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}.",
  ["Artisan Fishing Quest"] = "Задание на рыбную ловлю уровня Мастер",
  ["If you have no {i:6530:inv_misc_monstertail_03:Nightcrawlers} left, buy 5 from {n:0::Kilxx} in The Barrens or {n:0:alliance:Helenia Olden} in Dustwallow Marsh."] = "Если {i:6530:inv_misc_monstertail_03:Nightcrawlers} не осталось, купи 5 штук у {n:0::Kilxx} в Степях или у {n:0:alliance:Helenia Olden} в Пылевых топях.",
  ["Go to Dustwallow Marsh and {b}fish anywhere in the swamp until your skill reaches 225{/b}. {b}Don't fish in the ocean.{/b} Keep a {i:6530:inv_misc_monstertail_03:Nightcrawler} on your pole until 225, otherwise a few fish get away."] = "Иди в Пылевые топи и {b}рыбачь в любом месте болота, пока навык не дойдет до 225{/b}. {b}Не рыбачь в океане.{/b} До 225 держи на удочке {i:6530:inv_misc_monstertail_03:Nightcrawler}, иначе часть рыбы будет срываться.",
  ["Find {n:0::Nat Pagle} and accept the quest {q:6607::Nat Pagle, Angler Extreme}. It requires {b}level 35{/b} and {b}Fishing 225{/b}, and you need it to learn Artisan Fishing."] = "Найди {n:0::Nat Pagle} и возьми задание {q:6607::Nat Pagle, Angler Extreme}. Для него нужны {b}35-й уровень{/b} и {b}Рыбная ловля 225{/b}, и оно необходимо, чтобы выучить рыбную ловлю уровня Мастер.",
  ["Tidefury Cove, Dustwallow Marsh"] = "Бухта Яростного Прилива, Пылевые топи",
  ["To complete the quest you have to catch 4 quest fish in four different zones:"] = "Чтобы выполнить задание, нужно поймать 4 рыбы для задания в четырех разных зонах:",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas (attach the {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you kept, or {i:6532:inv_misc_gem_variety_02:Bright Baubles} from {n:0::Sheendra Tallgrass} / {n:0::Vivianna} in Feralas, otherwise most of them get away)"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Фералас (прицепи сохраненный {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} или {i:6532:inv_misc_gem_variety_02:Bright Baubles} от {n:0::Sheendra Tallgrass} / {n:0::Vivianna} в Фераласе, иначе большинство из них сорвется)",
  ["{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - Swamp of Sorrows"] = "{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - Болото Печали",
  ["{i:16968:inv_misc_fish_32:Sar'theris Striker} - Desolace"] = "{i:16968:inv_misc_fish_32:Sar'theris Striker} - Пустоши",
  ["{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - Stranglethorn Vale"] = "{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - Тернистая долина",
  ["Nat Pagle, Angler Extreme Quest Fishes"] = "Рыбы для задания Ната Пэйгла",
  ["Where to catch the four Nat Pagle quest fish"] = "Где поймать четырех рыб для задания Ната Пэйгла",
  ["Leveling Fishing to 255 and Cooking to 225"] = "Прокачка рыбной ловли до 255 и кулинарии до 225",
  ["After you completed the quest, {b}keep fishing in the swamp in Dustwallow Marsh until your Fishing skill reaches 255.{/b} {b}Don't fish in the ocean{/b}, because there you catch Raw Rockscale Cod instead of the Raw Mithril Head Trout you cook next."] = "Выполнив задание, {b}продолжай рыбачить в болоте Пылевых топей, пока навык рыбной ловли не дойдет до 255.{/b} {b}Не рыбачь в океане{/b}: там ловится сырая каменночешуйчатая треска, а не сырая мифрилоголовая форель, которую ты будешь готовить дальше.",
  ["Go back to Brackenwall Village (Horde) / Theramore Isle (Alliance) to cook your fish, or put down a campfire if you have one."] = "Вернись в Деревню Гиблотопь (Орда) / на остров Терамор (Альянс), чтобы приготовить рыбу, или разведи костер, если он у тебя есть.",
  ["Cook your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish} if your Cooking skill is still below 175."] = "Если кулинария еще ниже 175, приготовь {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}, получив {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}.",
  ["Learn {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} and cook your {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 225. Keep the rest, you cook them after the Artisan Cooking quest."] = "Выучи {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} и готовь {i:8365:inv_misc_fish_02:Raw Mithril Head Trout}, получая {s:20916:inv_misc_fish_02:Mithril Headed Trout}, до 225. Остальную сохрани, ее ты приготовишь после задания на кулинарию уровня Мастер.",
  ["Artisan Cooking Quest"] = "Задание на кулинарию уровня Мастер",
  ["Fly to Gadgetzan in Tanaris and pick up the quest {q:6610::Clamlette Surprise} from {n:0::Dirge Quikcleave}. The reward is Artisan Cooking. The quest requires {b}level 35{/b} and {b}Cooking 225{/b}. You will need these to complete the quest:"] = "Лети в Прибамбасск в Танарисе и возьми задание {q:6610::Clamlette Surprise} у {n:0::Dirge Quikcleave}. Награда - кулинария уровня Мастер. Для задания нужны {b}35-й уровень{/b} и {b}Кулинария 225{/b}. Для выполнения понадобится:",
  ["12x {i:12207:inv_egg_03:Giant Egg} - dropped by the {n:5428::Rocs}, {n:5429::Fire Rocs} and {n:5430::Searing Rocs} in Tanaris."] = "12x {i:12207:inv_egg_03:Giant Egg} - падают с {n:5428::Rocs}, {n:5429::Fire Rocs} и {n:5430::Searing Rocs} в Танарисе.",
  ["10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - from Big-mouth Clams, dropped by {n:14123::Steeljaw Snappers} and {n:5431::Surf Gliders} in Tanaris."] = "10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - из большеротых моллюсков, которые падают со {n:14123::Steeljaw Snappers} и {n:5431::Surf Gliders} в Танарисе.",
  ["20x {i:8932:inv_misc_food_37:Alterac Swiss} - you bought these earlier."] = "20x {i:8932:inv_misc_food_37:Alterac Swiss} - ты купил его раньше.",
  ["Find {n:0::Gikkix} at Steamwheedle Port in Tanaris and buy {i:13945:inv_scroll_03:Recipe: Nightfin Soup}."] = "Найди {n:0::Gikkix} в Порту Картеля Хитрых Делишек в Танарисе и купи {i:13945:inv_scroll_03:Recipe: Nightfin Soup}.",
  ["Fishing to 300 in Feralas"] = "Рыбная ловля до 300 в Фераласе",
  ["Fly to Camp Mojache (Horde) / Feathermoon Stronghold (Alliance) in Feralas."] = "Лети в Лагерь Мохаче (Орда) / Крепость Оперенной Луны (Альянс) в Фераласе.",
  ["Buy 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}."] = "Купи 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} у {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}.",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the marked lake until you reach Fishing 300, use a new one every 10 minutes. Any other lake or river in Feralas works too, {b}except Jademir Lake{/b}."] = "Прицепи {i:6530:inv_misc_monstertail_03:Nightcrawler} и рыбачь в отмеченном озере, пока не дойдешь до Рыбной ловли 300, каждые 10 минут используй новую наживку. Подойдет и любое другое озеро или река в Фераласе, {b}кроме озера Джедемир{/b}.",
  ["Where to fish in Feralas from 255 to 300"] = "Где рыбачить в Фераласе с 255 до 300",
  ["Leveling Cooking to 300"] = "Прокачка кулинарии до 300",
  ["Cook your remaining {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 250."] = "Готовь оставшуюся {i:8365:inv_misc_fish_02:Raw Mithril Head Trout}, получая {s:20916:inv_misc_fish_02:Mithril Headed Trout}, до 250.",
  ["Learn {i:13941:inv_scroll_03:Recipe: Filet of Redgill} and cook your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} until 285."] = "Выучи {i:13941:inv_scroll_03:Recipe: Filet of Redgill} и готовь {i:13758:inv_misc_fish_06:Raw Redgill}, получая {s:18241:inv_misc_fish_06:Filet of Redgill}, до 285.",
  ["Learn {i:13945:inv_scroll_03:Recipe: Nightfin Soup} and cook all your {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} into {s:18243:inv_drink_17:Nightfin Soup}. You also need a {i:159:inv_drink_07:Refreshing Spring Water} for each soup, buy 20 from the innkeeper."] = "Выучи {i:13945:inv_scroll_03:Recipe: Nightfin Soup} и приготовь всех {i:13759:inv_misc_fish_23:Raw Nightfin Snapper}, получив {s:18243:inv_drink_17:Nightfin Soup}. Для каждого супа нужна еще {i:159:inv_drink_07:Refreshing Spring Water}, купи 20 штук у хозяина таверны.",
  ["{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} don't bite in the afternoon (12:00-18:00 game time). If you fished in the afternoon, you will probably not have enough, so cook the rest of your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} too, you might reach 300 with them."] = "{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} не клюет днем (12:00-18:00 по игровому времени). Если ты рыбачил днем, ее, скорее всего, не хватит, так что приготовь также остаток {i:13758:inv_misc_fish_06:Raw Redgill}, получив {s:18241:inv_misc_fish_06:Filet of Redgill}, с ним можно дойти до 300.",
  ["If you still don't reach 300, fish a bit more outside the afternoon, or buy a few {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} on the Auction House."] = "Если до 300 все равно не дошел, порыбачь еще немного не в дневное время или купи несколько {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} на аукционе.",
  ["This WoW Forever Cooking leveling guide will show you the fastest way to level your Cooking skill from 1 to 300 as cheaply as possible. You will also find every trainer location, how the campfire works in Forever and where to train Cooking past 150 and 225."] = "Это руководство по прокачке кулинарии для WoW Forever покажет тебе самый быстрый и как можно более дешевый способ поднять навык кулинарии с 1 до 300. Здесь же ты найдешь всех учителей, узнаешь, как работает костер в Forever и где учиться кулинарии после 150 и 225.",
  ["Cooking doesn't take up one of your two profession slots, so every character can learn it. Most of the recipes below only need the meat or fish that drops while you level, so the guide lists a few recipes for every skill range and you can make the one you have the ingredients for. If you also want to level Fishing but haven't leveled it yet, use my Fishing and Cooking leveling guide instead:"] = "Кулинария не занимает один из двух слотов профессий, так что ее может выучить каждый персонаж. Для большинства рецептов ниже нужно только мясо или рыба, которые падают по ходу прокачки, поэтому в руководстве для каждого диапазона навыка указано несколько рецептов и можно делать тот, для которого есть ингредиенты. Если ты хочешь качать и рыбную ловлю, но еще не прокачал ее, используй вместо этого мое руководство по рыбной ловле и кулинарии:",
  ["You need level 35 to go past 225, so I split the list in two. Buy this part first."] = "Чтобы пройти дальше 225, нужен 35-й уровень, поэтому я разделил список на две части. Сначала купи эту часть.",
  ["The Giant Eggs and the Zesty Clam Meat are for the Artisan Cooking quest."] = "Гигантские яйца и острое мясо моллюска нужны для задания на кулинарию уровня Мастер.",
  ["Cooking Trainer Locations"] = "Где найти учителей кулинарии",
  ["Apprentice Cooking has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman Cooking, so you don't have to find a different trainer at 50."] = "У кулинарии уровня Ученик нет требований к уровню, так что ее можно выучить новым персонажем. Каждый учитель также обучает кулинарии уровня Подмастерье, так что на 50 не придется искать другого учителя.",
  ["Orgrimmar: {n:0:horde:Zamja}"] = "Оргриммар: {n:0:horde:Zamja}",
  ["Undercity: {n:0:horde:Eunice Burch}"] = "Подгород: {n:0:horde:Eunice Burch}",
  ["Thunder Bluff: {n:0:horde:Aska Mistrunner}"] = "Громовой Утес: {n:0:horde:Aska Mistrunner}",
  ["Every starting zone has a Cooking trainer, most of them are inside the inn."] = "В каждой стартовой зоне есть учитель кулинарии, обычно в таверне.",
  ["{n:0:horde:Cook Torka} in Razor Hill"] = "{n:0:horde:Cook Torka} в Колючем Холме",
  ["{n:0:horde:Pyall Silentstride} inside the big tent in Bloodhoof Village"] = "{n:0:horde:Pyall Silentstride} в большом шатре в деревне Кровавого Копыта",
  ["{n:0:horde:William Pickman} inside the inn in Brill"] = "{n:0:horde:William Pickman} в таверне в Брилле",
  ["{n:0::Nyalah Brightfire} in Valanaar, {n:0::Zerril Softbreeze} in Shen'dar Village"] = "{n:0::Nyalah Brightfire} в Валанааре, {n:0::Zerril Softbreeze} в деревне Шен'дар",
  ["Stormwind City: {n:0:alliance:Stephen Ryback}"] = "Штормград: {n:0:alliance:Stephen Ryback}",
  ["Ironforge: {n:0:alliance:Daryl Riknussun}"] = "Стальгорн: {n:0:alliance:Daryl Riknussun}",
  ["Darnassus: {n:0:alliance:Alegorn}"] = "Дарнас: {n:0:alliance:Alegorn}",
  ["{n:0:alliance:Tomas} in the kitchen of the inn in Goldshire"] = "{n:0:alliance:Tomas} на кухне таверны в Златоземье",
  ["{n:0:alliance:Gremlock Pilsnor} in the Thunderbrew Distillery in Kharanos"] = "{n:0:alliance:Gremlock Pilsnor} в пивоварне Громоваров в Караносе",
  ["{n:0:alliance:Zarrin} in Dolanaar"] = "{n:0:alliance:Zarrin} в Доланааре",
  ["You can find every Cooking trainer for Horde and Alliance on my WoW Forever Cooking Trainers page."] = "Всех учителей кулинарии Орды и Альянса ты найдешь на моей странице «WoW Forever Cooking Trainers».",
  ["Campfire"] = "Костер",
  ["You need a campfire to cook. There is often one burning next to the Cooking trainer, so look around before you make your own."] = "Чтобы готовить, нужен костер. Часто он уже горит рядом с учителем кулинарии, так что оглядись, прежде чем разводить свой.",
  ["In Forever the campfire is an item. You learn the {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} together with Cooking and place the fire from your bags, so you can make a stack of kits in advance. Other players can add their own camp items to your fire, you can read about the whole camping system in my WoW Forever Camping Guide."] = "В Forever костер - это предмет. {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} ты выучиваешь вместе с кулинарией и ставишь костер из сумки, так что можно заранее сделать стопку наборов. Другие игроки могут добавлять к твоему костру свои предметы для лагеря, обо всей системе лагерей можно прочитать в моем «WoW Forever Camping Guide».",
  ["To craft the kits you need {i:4470:inv_tradeskillitem_01:Simple Wood} and a {i:4471:inv_stone_11:Flint and Tinder}. The Flint and Tinder is only for crafting the kits, you don't need it to place the fire. Open your faction below to see who sells them near your trainer:"] = "Для изготовления наборов нужны {i:4470:inv_tradeskillitem_01:Simple Wood} и {i:4471:inv_stone_11:Flint and Tinder}. Огниво нужно только для изготовления наборов, чтобы поставить костер, оно не требуется. Открой свою фракцию ниже, чтобы узнать, кто продает их рядом с твоим учителем:",
  ["{n:0:horde:Xen'to}, next to the trainer"] = "{n:0:horde:Xen'to}, рядом с учителем",
  ["{n:0:horde:Ronald Burch}, next to the trainer"] = "{n:0:horde:Ronald Burch}, рядом с учителем",
  ["{n:0:horde:Naal Mistrunner}, next to the trainer"] = "{n:0:horde:Naal Mistrunner}, рядом с учителем",
  ["{n:0:horde:Jark} in the Razor Hill barracks"] = "{n:0:horde:Jark} в казарме Колючего Холма",
  ["{n:0:horde:Moorat Longstride} in Bloodhoof Village"] = "{n:0:horde:Moorat Longstride} в деревне Кровавого Копыта",
  ["{n:0:horde:Mrs. Winters} in Brill"] = "{n:0:horde:Mrs. Winters} в Брилле",
  ["{n:0::Antelariaa Cloudgaze} in Valanaar {n:0::Zerril Softbreeze}, the Cooking trainer in Shen'dar Village"] = "{n:0::Antelariaa Cloudgaze} в Валанааре {n:0::Zerril Softbreeze}, учитель кулинарии в деревне Шен'дар",
  ["{n:0:alliance:Erika Tate}, next to the trainer"] = "{n:0:alliance:Erika Tate}, рядом с учителем",
  ["{n:0:alliance:Emrul Riknussun}, next to the trainer"] = "{n:0:alliance:Emrul Riknussun}, рядом с учителем",
  ["{n:0:alliance:Fyldan}, next to the trainer"] = "{n:0:alliance:Fyldan}, рядом с учителем",
  ["{n:0:alliance:Brog Hamfist} in Goldshire"] = "{n:0:alliance:Brog Hamfist} в Златоземье",
  ["{n:0:alliance:Kreg Bilmn} in the Thunderbrew Distillery"] = "{n:0:alliance:Kreg Bilmn} в пивоварне Громоваров",
  ["{n:0:alliance:Nyoma} in Dolanaar"] = "{n:0:alliance:Nyoma} в Доланааре",
  ["Apprentice Cooking (1-50)"] = "Кулинария: Ученик (1-50)",
  ["{b}These are sold by Cooking Supply vendors near your trainer, don't buy them from the Auction House:{/b}"] = "{b}Это продают торговцы кулинарными товарами рядом с учителем, не покупай на аукционе:{/b}",
  ["Make around 55 from one of these recipes. The two fish are usually the cheapest."] = "Сделай около 55 штук по одному из этих рецептов. Две рыбы обычно самые дешевые.",
  ["Food"] = "Еда",
  ["Ingredients"] = "Ингредиенты",
  ["Recipe Source"] = "Источник рецепта",
  ["Mulgore: {n:0:horde:Harn Longcast} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Tirisfal Glades: {n:0:horde:Martine Tramblay} Undercity: {n:0:horde:Lizbeth Cromwell} Dun Morogh: {n:0:alliance:Gretta Ganter} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Loch Modan: {n:0:alliance:Khara Deepwater} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nyoma}"] = "Мулгор: {n:0:horde:Harn Longcast} Громовой Утес: {n:0:horde:Sewa Mistrunner} Тирисфальские леса: {n:0:horde:Martine Tramblay} Подгород: {n:0:horde:Lizbeth Cromwell} Дун Морог: {n:0:alliance:Gretta Ganter} Элвиннский лес: {n:0:alliance:Tharynn Bouden} Лок Модан: {n:0:alliance:Khara Deepwater} Штормград: {n:0:alliance:Catherine Leland} Тельдрассил: {n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Tirisfal Glades: {n:0:horde:Martine Tramblay} Ironforge: {n:0:alliance:Tansy Puddlefizz} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone}"] = "Дуротар: {n:0:horde:Zansoa} Тирисфальские леса: {n:0:horde:Martine Tramblay} Стальгорн: {n:0:alliance:Tansy Puddlefizz} Тельдрассил: {n:0:alliance:Nessa Shadowsong} Западный Край: {n:0:alliance:Kriggon Talsone}",
  ["Trainer"] = "Учитель",
  ["(Horde only) Make {s:15935:inv_misc_food_46:Crispy Bat Wing} if you have some {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}. The recipe is sold by {n:0:horde:Abigail Shiel} in Tirisfal Glades."] = "(Только Орда) Делай {s:15935:inv_misc_food_46:Crispy Bat Wing}, если у тебя есть {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}. Рецепт продает {n:0:horde:Abigail Shiel} в Тирисфальских лесах.",
  ["(Horde only) Make {s:6413:inv_misc_food_10:Scorpid Surprise} if you have some {i:5466:spell_nature_nullifypoison:Scorpid Stinger}. The recipe is sold by {n:0:horde:Grimtak} in Durotar."] = "(Только Орда) Делай {s:6413:inv_misc_food_10:Scorpid Surprise}, если у тебя есть {i:5466:spell_nature_nullifypoison:Scorpid Stinger}. Рецепт продает {n:0:horde:Grimtak} в Дуротаре.",
  ["(Alliance only) Make {s:6412:inv_misc_food_68:Kaldorei Spider Kabob} if you have some {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}. The recipe is a reward from {q:4161::Recipe of the Kaldorei}. You can get the quest from {n:0:alliance:Zarrin} in Teldrassil."] = "(Только Альянс) Делай {s:6412:inv_misc_food_68:Kaldorei Spider Kabob}, если у тебя есть {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}. Рецепт - награда за {q:4161::Recipe of the Kaldorei}. Задание можно взять у {n:0:alliance:Zarrin} в Тельдрассиле.",
  ["Journeyman Cooking (50-150)"] = "Кулинария: Подмастерье (50-150)",
  ["{b}Visit your trainer again and learn Journeyman Cooking{/b}, it requires Cooking 50."] = "{b}Снова зайди к учителю и выучи кулинарию уровня Подмастерье{/b}, для этого нужна Кулинария 50.",
  ["{b}Make sure to learn Journeyman Cooking before you start the next part{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 75 and keep cooking for nothing."] = "{b}Обязательно выучи кулинарию уровня Подмастерье, прежде чем начинать следующую часть{/b}, особенно если готовишь в АФК. Без нее на 75 очки навыка перестанут идти и ты будешь готовить впустую.",
  ["Make around 55 from any of the recipes below. The two fish are usually the cheapest. {s:8607:inv_misc_food_13:Smoked Bear Meat} turns yellow sooner than the rest, so make more of it, or cook it first if you have more than one type of meat."] = "Сделай около 55 штук по любому из рецептов ниже. Две рыбы обычно самые дешевые. {s:8607:inv_misc_food_13:Smoked Bear Meat} становится желтым раньше остальных, так что делай его больше или готовь первым, если у тебя несколько видов мяса.",
  ["Mulgore: {n:0:horde:Harn Longcast} Silverpine Forest: {n:0:horde:Killian Sanatha} Thunder Bluff: {n:0:horde:Naal Mistrunner} Undercity: {n:0:horde:Lizbeth Cromwell} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Ironforge: {n:0:alliance:Tansy Puddlefizz} Loch Modan: {n:0:alliance:Khara Deepwater} Teldrassil: {n:0:alliance:Nyoma}"] = "Мулгор: {n:0:horde:Harn Longcast} Серебряный бор: {n:0:horde:Killian Sanatha} Громовой Утес: {n:0:horde:Naal Mistrunner} Подгород: {n:0:horde:Lizbeth Cromwell} Элвиннский лес: {n:0:alliance:Tharynn Bouden} Стальгорн: {n:0:alliance:Tansy Puddlefizz} Лок Модан: {n:0:alliance:Khara Deepwater} Тельдрассил: {n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Orgrimmar: {n:0:horde:Shankys} Silverpine Forest: {n:0:horde:Killian Sanatha} Undercity: {n:0:horde:Ronald Burch} Darkshore: {n:0:alliance:Heldan Galesong} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone} Wetlands: {n:0:alliance:Stuart Fleming} The Barrens: {n:0::Kilxx}"] = "Дуротар: {n:0:horde:Zansoa} Оргриммар: {n:0:horde:Shankys} Серебряный бор: {n:0:horde:Killian Sanatha} Подгород: {n:0:horde:Ronald Burch} Темные берега: {n:0:alliance:Heldan Galesong} Штормград: {n:0:alliance:Catherine Leland} Тельдрассил: {n:0:alliance:Nessa Shadowsong} Западный Край: {n:0:alliance:Kriggon Talsone} Болотина: {n:0:alliance:Stuart Fleming} Степи: {n:0::Kilxx}",
  ["Silverpine Forest: {n:0:horde:Andrew Hilbert} Loch Modan: {n:0:alliance:Drac Roughcut}"] = "Серебряный бор: {n:0:horde:Andrew Hilbert} Лок Модан: {n:0:alliance:Drac Roughcut}",
  ["55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (Vendor)"] = "55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (Торговец)",
  ["The Barrens: {n:0:horde:Tari'qa} (Horde only) Reward from {q:2178::Easy Strider Living} (Alliance only)"] = "Степи: {n:0:horde:Tari'qa} (только Орда) Награда за {q:2178::Easy Strider Living} (только Альянс)",
  ["Make around 30-35 from one of these two."] = "Сделай около 30-35 штук по одному из этих двух.",
  ["30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (buy around 55, you will need 25 more at 130-150)"] = "30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (купи около 55, еще 25 понадобятся на 130-150)",
  ["Hillsbrad Foothills: {n:0:horde:Derak Nightfall} Thunder Bluff: {n:0:horde:Naal Mistrunner} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Undercity: {n:0:horde:Ronald Burch} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne} Stormwind City: {n:0:alliance:Catherine Leland} The Barrens: {n:0::Kilxx}"] = "Предгорья Хилсбрада: {n:0:horde:Derak Nightfall} Громовой Утес: {n:0:horde:Naal Mistrunner} Громовой Утес: {n:0:horde:Sewa Mistrunner} Подгород: {n:0:horde:Ronald Burch} Предгорья Хилсбрада: {n:0:alliance:Lindea Rabonne} Штормград: {n:0:alliance:Catherine Leland} Степи: {n:0::Kilxx}",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance only)"] = "Штормград: {n:0:alliance:Kendor Kabonka} (только Альянс)",
  ["Make around 20-25 from any of the recipes below."] = "Сделай около 20-25 штук по любому из рецептов ниже.",
  ["See above"] = "Смотри выше",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance) Arathi Highlands: {n:0:horde:Keena} (Horde)"] = "Штормград: {n:0:alliance:Kendor Kabonka} (Альянс) Нагорье Арати: {n:0:horde:Keena} (Орда)",
  ["The Barrens: {n:0:horde:Zargh} (Horde only)"] = "Степи: {n:0:horde:Zargh} (только Орда)",
  ["Expert Cooking (150-225)"] = "Кулинария: Умелец (150-225)",
  ["To learn Expert Cooking you need to reach Cooking 125, then buy the {i:16072:inv_misc_book_08:Expert Cookbook} from {n:0:horde:Wulan} (Horde) in Desolace at Shadowprey Village or from {n:0:alliance:Shandrina} (Alliance) in Ashenvale at Mystral Lake."] = "Чтобы выучить кулинарию уровня Умелец, нужно дойти до Кулинарии 125, а затем купить {i:16072:inv_misc_book_08:Expert Cookbook} у {n:0:horde:Wulan} (Орда) в Деревне Призрачной Охоты в Пустошах или у {n:0:alliance:Shandrina} (Альянс) у озера Мистраль в Ясеневом лесу.",
  ["Make around 25-30 from one of these three."] = "Сделай около 25-30 штук по одному из этих трех.",
  ["You can also keep making {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, but it's green from 160, so you need around 90 of them for these 25 points."] = "Можно и дальше делать {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, но со 160 он зеленый, так что на эти 25 очков понадобится около 90 штук.",
  ["Make around 55 from one of these. The Roast Raptor is usually the cheapest."] = "Сделай около 55 штук по одному из этих. Жареный ящер обычно самый дешевый.",
  ["Arathi Highlands: {n:0:alliance:Hammon Karwn} Arathi Highlands: {n:0:horde:Keena} Dustwallow Marsh: {n:0:horde:Ogg'marr}"] = "Нагорье Арати: {n:0:alliance:Hammon Karwn} Нагорье Арати: {n:0:horde:Keena} Пылевые топи: {n:0:horde:Ogg'marr}",
  ["Ashenvale: {n:0:horde:Wik'Tar} Orgrimmar: {n:0:horde:Shankys} Stranglethorn Vale: {n:0::Kelsey Yance} Undercity: {n:0:horde:Lizbeth Cromwell} Ironforge: {n:0:alliance:Tansy Puddlefizz} Wetlands: {n:0:alliance:Stuart Fleming} Desolace: {n:0:horde:Wulan} Darkshore: {n:0:alliance:Heldan Galesong} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne}"] = "Ясеневый лес: {n:0:horde:Wik'Tar} Оргриммар: {n:0:horde:Shankys} Тернистая долина: {n:0::Kelsey Yance} Подгород: {n:0:horde:Lizbeth Cromwell} Стальгорн: {n:0:alliance:Tansy Puddlefizz} Болотина: {n:0:alliance:Stuart Fleming} Пустоши: {n:0:horde:Wulan} Темные берега: {n:0:alliance:Heldan Galesong} Предгорья Хилсбрада: {n:0:alliance:Lindea Rabonne}",
  ["Reward from a quest in Hillsbrad Foothills NPC: {n:0:horde:Christoph Jeffcoat}, quest: {q:7321::Soothing Turtle Bisque} NPC: {n:0:alliance:Chef Jessen}, quest: {q:555::Soothing Turtle Bisque}"] = "Награда за задание в Предгорьях Хилсбрада NPC: {n:0:horde:Christoph Jeffcoat}, задание: {q:7321::Soothing Turtle Bisque} NPC: {n:0:alliance:Chef Jessen}, задание: {q:555::Soothing Turtle Bisque}",
  ["Artisan Cooking (225-300)"] = "Кулинария: Мастер (225-300)",
  ["Artisan Cooking is the reward of the {q:6610::Clamlette Surprise} quest. You need {b}level 35{/b} and {b}Cooking 225{/b} for it."] = "Кулинария уровня Мастер - награда за задание {q:6610::Clamlette Surprise}. Для него нужны {b}35-й уровень{/b} и {b}Кулинария 225{/b}.",
  ["Pick up the quest that sends you to Gadgetzan: Horde players take {q:6611::To Gadgetzan You Go!} from {n:0:horde:Zamja} in Orgrimmar, Alliance players take {q:6612::I Know A Guy...} from {n:0:alliance:Daryl Riknussun} in Ironforge."] = "Возьми задание, которое отправляет тебя в Прибамбасск: игроки Орды берут {q:6611::To Gadgetzan You Go!} у {n:0:horde:Zamja} в Оргриммаре, игроки Альянса берут {q:6612::I Know A Guy...} у {n:0:alliance:Daryl Riknussun} в Стальгорне.",
  ["Collect 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} and 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}Don't go to Gadgetzan before you have all of them{/b}, otherwise you make the trip twice."] = "Собери 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} и 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}Не иди в Прибамбасск, пока не соберешь все{/b}, иначе придется ехать дважды.",
  ["Find {n:0::Dirge Quikcleave} in Gadgetzan, take Clamlette Surprise from him and hand in the three items. He teaches you Artisan Cooking on the spot. While you are in Tanaris, go to Steamwheedle Port and {b}buy {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} from {n:0::Gikkix}{/b}, you need it in the next step."] = "Найди {n:0::Dirge Quikcleave} в Прибамбасске, возьми у него «Сюрприз из моллюсков» и сдай три предмета. Он сразу обучит тебя кулинарии уровня Мастер. Пока ты в Танарисе, зайди в Порт Картеля Хитрых Делишек и {b}купи {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} у {n:0::Gikkix}{/b}, он понадобится на следующем шаге.",
  ["Make around 140 from one of these two, buy the fish that is cheaper."] = "Сделай около 140 штук по одному из этих двух, покупай ту рыбу, что дешевле.",
  ["Tanaris: {n:0::Gikkix}"] = "Танарис: {n:0::Gikkix}",
  ["Stranglethorn Vale: {n:0::Kelsey Yance}"] = "Тернистая долина: {n:0::Kelsey Yance}",
  ["This WoW Forever First Aid leveling guide will show you the fastest way to level your First Aid skill from 1 to 300. You will also find every trainer location and where to train First Aid past 150 and 225."] = "Это руководство по прокачке первой помощи для WoW Forever покажет тебе самый быстрый способ поднять навык первой помощи с 1 до 300. Здесь же ты найдешь всех учителей и узнаешь, где учиться первой помощи после 150 и 225.",
  ["First Aid does not take up one of your two profession slots, so every character can learn it. Bandages heal you between fights, and in Forever First Aid also makes the healing potions that used to be Alchemy recipes, so it's worth leveling on every character. Below you will find the shopping list, the First Aid trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "Первая помощь не занимает один из двух слотов профессий, так что ее может выучить каждый персонаж. Бинты лечат тебя между боями, а в Forever первая помощь также делает лечебные зелья, которые раньше были рецептами алхимии, так что ее стоит качать на каждом персонаже. Ниже ты найдешь список покупок, учителей первой помощи по стартовым зонам и столицам, а также самые дешевые рецепты для каждого диапазона навыка.",
  ["First Aid Trainer Locations"] = "Где найти учителей первой помощи",
  ["Apprentice First Aid has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman First Aid, so you don't have to find a different trainer at 50."] = "У первой помощи уровня Ученик нет требований к уровню, так что ее можно выучить новым персонажем. Каждый учитель также обучает первой помощи уровня Подмастерье, так что на 50 не придется искать другого учителя.",
  ["Orgrimmar: {n:0:horde:Arnok}"] = "Оргриммар: {n:0:horde:Arnok}",
  ["Undercity: {n:0:horde:Mary Edras}"] = "Подгород: {n:0:horde:Mary Edras}",
  ["Thunder Bluff: {n:0:horde:Pand Stonebinder}"] = "Громовой Утес: {n:0:horde:Pand Stonebinder}",
  ["Every starting zone has a First Aid trainer, most of them are inside the inn."] = "В каждой стартовой зоне есть учитель первой помощи, обычно в таверне.",
  ["{n:0:horde:Rawrk} in the barracks in Razor Hill"] = "{n:0:horde:Rawrk} в казарме Колючего Холма",
  ["{n:0:horde:Vira Younghoof} inside the inn in Bloodhoof Village"] = "{n:0:horde:Vira Younghoof} в таверне в деревне Кровавого Копыта",
  ["{n:0:horde:Nurse Neela} inside the inn in Brill"] = "{n:0:horde:Nurse Neela} в таверне в Брилле",
  ["{n:0::Melasa Fairmend} in Valanaar, {n:0::Naleeia Tattermend} in Shen'dar Village"] = "{n:0::Melasa Fairmend} в Валанааре, {n:0::Naleeia Tattermend} в деревне Шен'дар",
  ["Stormwind City: {n:0:alliance:Shaina Fuller}"] = "Штормград: {n:0:alliance:Shaina Fuller}",
  ["Ironforge: {n:0:alliance:Nissa Firestone}"] = "Стальгорн: {n:0:alliance:Nissa Firestone}",
  ["Darnassus: {n:0:alliance:Dannelor}"] = "Дарнас: {n:0:alliance:Dannelor}",
  ["{n:0:alliance:Michelle Belle} upstairs in the inn in Goldshire"] = "{n:0:alliance:Michelle Belle} на втором этаже таверны в Златоземье",
  ["{n:0:alliance:Thamner Pol} in the Thunderbrew Distillery in Kharanos"] = "{n:0:alliance:Thamner Pol} в пивоварне Громоваров в Караносе",
  ["{n:0:alliance:Byancie} in Dolanaar, in the building north of the inn"] = "{n:0:alliance:Byancie} в Доланааре, в здании к северу от таверны",
  ["You can find every First Aid trainer for Horde and Alliance on my WoW Forever First Aid Trainers page."] = "Всех учителей первой помощи Орды и Альянса ты найдешь на моей странице «WoW Forever First Aid Trainers».",
  ["Apprentice First Aid (1-75)"] = "Первая помощь: Ученик (1-75)",
  ["If you have Linen Cloth or bought some, pick the {b}Bandages{/b} tab. If you bought herbs, pick the {b}Healing Potions{/b} tab."] = "Если у тебя есть льняной материал или ты его купил, выбери вкладку {b}Бинты{/b}. Если ты купил травы, выбери вкладку {b}Лечебные зелья{/b}.",
  ["Bandages"] = "Бинты",
  ["Healing Potions"] = "Лечебные зелья",
  ["86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Peacebloom, 86 Mild Spices, 86 Empty Vial"] = "86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Мироцвет, 86 Слабые специи, 86 Пустой флакон",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} are sold by Cooking supply vendors, {i:3371:inv_potion_84:Empty Vial} by Alchemy supply vendors. Open your faction below to see who sells them near your trainer:"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices} продают торговцы кулинарными товарами, {i:3371:inv_potion_84:Empty Vial} торговцы алхимическими товарами. Открой свою фракцию ниже, чтобы узнать, кто продает их рядом с твоим учителем:",
  ["spices: {n:0:horde:Xen'to} vials: {n:0:horde:Kor'geld}"] = "специи: {n:0:horde:Xen'to} флаконы: {n:0:horde:Kor'geld}",
  ["{n:0:horde:Felicia Doan} in the Trade Quarter"] = "{n:0:horde:Felicia Doan} в Торговом квартале",
  ["spices: {n:0:horde:Naal Mistrunner} vials: {n:0:horde:Mani Winterhoof}"] = "специи: {n:0:horde:Naal Mistrunner} флаконы: {n:0:horde:Mani Winterhoof}",
  ["{n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "{n:0:horde:Wunna Darkmane} в деревне Кровавого Копыта",
  ["{n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Abigail Shiel} в Брилле",
  ["{n:0::Iallion Featherfall} in Valanaar {n:0::Belandiel Farflight} in Shen'dar Village"] = "{n:0::Iallion Featherfall} в Валанааре {n:0::Belandiel Farflight} в деревне Шен'дар",
  ["{n:0:alliance:Edna Mullby} in the Trade District"] = "{n:0:alliance:Edna Mullby} в Торговом квартале",
  ["spices: {n:0:alliance:Emrul Riknussun} vials: {n:0:alliance:Gwina Stonebranch}, right next to the trainer"] = "специи: {n:0:alliance:Emrul Riknussun} флаконы: {n:0:alliance:Gwina Stonebranch}, прямо рядом с учителем",
  ["{n:0:alliance:Golorn Frostbeard} in Kharanos"] = "{n:0:alliance:Golorn Frostbeard} в Караносе",
  ["{n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "{n:0:alliance:Narret Shadowgrove} в Доланааре",
  ["50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Linen Cloth"] = "50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Льняной материал",
  ["49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Linen Cloth"] = "49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Льняной материал",
  ["Journeyman First Aid (75-150)"] = "Первая помощь: Подмастерье (75-150)",
  ["To train past 75, visit your trainer and learn Journeyman First Aid, it requires First Aid 50."] = "Чтобы учиться дальше 75, зайди к учителю и выучи первую помощь уровня Подмастерье, для этого нужна Первая помощь 50.",
  ["16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Linen Cloth"] = "16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Льняной материал",
  ["12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Wool Cloth"] = "12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Шерсть",
  ["If you have Wool Cloth, pick the {b}Bandages{/b} tab. If you have to buy everything, the {b}Healing Potions{/b} tab is cheaper."] = "Если у тебя есть шерсть, выбери вкладку {b}Бинты{/b}. Если все придется покупать, вкладка {b}Лечебные зелья{/b} дешевле.",
  ["43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Wool Cloth"] = "43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Шерсть",
  ["54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Wool Cloth"] = "54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Шерсть",
  ["For this tab you need 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} and 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Spices are sold by Cooking supply vendors, vials by Alchemy supply vendors and the bottles by barkeeps. The starting zone vendors don't sell Hot Spices or Leaded Vials, so buy them in a capital city. Open your faction below to see who sells them:"] = "Для этой вкладки нужны 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} и 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Специи продают торговцы кулинарными товарами, флаконы торговцы алхимическими товарами, а бутылки трактирщики. Торговцы в стартовых зонах не продают острые специи и освинцованные флаконы, так что покупай их в столице. Открой свою фракцию ниже, чтобы узнать, кто их продает:",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} and {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices} и {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}",
  ["Orgrimmar: {n:0:horde:Xen'to} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Naal Mistrunner}"] = "Оргриммар: {n:0:horde:Xen'to} Подгород: {n:0:horde:Felicia Doan} Громовой Утес: {n:0:horde:Naal Mistrunner}",
  ["Orgrimmar: {n:0:horde:Kor'geld} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Mani Winterhoof}"] = "Оргриммар: {n:0:horde:Kor'geld} Подгород: {n:0:horde:Felicia Doan} Громовой Утес: {n:0:horde:Mani Winterhoof}",
  ["Orgrimmar: {n:5611::Barkeep Morag} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "Оргриммар: {n:5611::Barkeep Morag} Пиратская Бухта: {n:2832::Nixxrax Fillamug}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Emrul Riknussun} Darnassus: {n:0:alliance:Mythrin'dir}"] = "Штормград: {n:0:alliance:Edna Mullby} Стальгорн: {n:0:alliance:Emrul Riknussun} Дарнас: {n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Gwina Stonebranch} Darnassus: {n:0:alliance:Mythrin'dir}"] = "Штормград: {n:0:alliance:Edna Mullby} Стальгорн: {n:0:alliance:Gwina Stonebranch} Дарнас: {n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:277::Roberto Pupellyverbos} and {n:1328::Elly Langston} Ironforge: {n:5570::Bruuk Barleybeard} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "Штормград: {n:277::Roberto Pupellyverbos} и {n:1328::Elly Langston} Стальгорн: {n:5570::Bruuk Barleybeard} Пиратская Бухта: {n:2832::Nixxrax Fillamug}",
  ["54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Spider Ichor, 54 Mild Spices, 54 Bottle of Dalaran Noir"] = "54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Паучий ихор, 54 Слабые специи, 54 Бутылка «Даларанского черного»",
  ["31x {s:1244433:inv_potion_51:Healing Potion} - 31 Bruiseweed, 31 Hot Spices, 31 Leaded Vial"] = "31x {s:1244433:inv_potion_51:Healing Potion} - 31 Синячник, 31 Острые специи, 31 Освинцованный флакон",
  ["Expert First Aid (150-225)"] = "Первая помощь: Умелец (150-225)",
  ["{b}Learn {s:7928:inv_misc_bandage_01:Silk Bandage} from your trainer before you leave{/b}, it's the last recipe the trainers teach."] = "{b}Выучи у учителя {s:7928:inv_misc_bandage_01:Silk Bandage}, прежде чем уходить{/b}, это последний рецепт, которому обучают учителя.",
  ["How to learn Expert First Aid"] = "Как выучить первую помощь уровня Умелец",
  ["To train past 150, buy the {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} book from {n:0:alliance:Deneb Walker} (Alliance) in Arathi Highlands or {n:0:horde:Balai Lok'Wein} (Horde) in Dustwallow Marsh. The book has {b}no level requirement{/b}, you only need First Aid 125."] = "Чтобы учиться дальше 150, купи книгу {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} у {n:0:alliance:Deneb Walker} (Альянс) в Нагорье Арати или у {n:0:horde:Balai Lok'Wein} (Орда) в Пылевых топях. У книги {b}нет требований к уровню{/b}, нужна только Первая помощь 125.",
  ["They also sell the next two manuals, so {b}buy all three{/b} while you are there, or get them from the Auction House if you are low level:"] = "Они же продают два следующих руководства, так что {b}купи все три{/b}, пока ты там, или возьми их на аукционе, если у тебя низкий уровень:",
  ["47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Silk Cloth"] = "47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Шелк",
  ["47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Silk Cloth"] = "47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Шелк",
  ["Use the Manual: Heavy Silk Bandage first to learn the recipe."] = "Сначала используй «Руководство: плотный шелковый бинт», чтобы выучить рецепт.",
  ["19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Mageweave Cloth"] = "19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Магическая ткань",
  ["Use the Manual: Mageweave Bandage first to learn the recipe."] = "Сначала используй «Руководство: бинт из магической ткани», чтобы выучить рецепт.",
  ["Artisan First Aid (225-300)"] = "Первая помощь: Мастер (225-300)",
  ["You can train First Aid past 225 by completing the Triage quest. It requires {b}First Aid 225{/b} and {b}level 35{/b}, even though the quest itself is level 45."] = "Чтобы учиться первой помощи дальше 225, выполни задание «Сортировка раненых». Для него нужны {b}Первая помощь 225{/b} и {b}35-й уровень{/b}, хотя само задание 45-го уровня.",
  ["{b}Bring everything you need in order to skill up to 275{/b}, as you will learn the next two bandages from the same doctor, so bring around 90 Mageweave Cloth and 20 Runecloth with you."] = "{b}Возьми с собой все, что нужно, чтобы дойти до 275{/b}: следующие два бинта ты выучишь у того же доктора, так что захвати около 90 магической ткани и 20 рунической ткани.",
  ["The {q:6622::Triage} quest is given by {n:0:horde:Doctor Gregory Victor} in Arathi Highlands at Hammerfall."] = "Задание {q:6622::Triage} дает {n:0:horde:Doctor Gregory Victor} в Молотопаде в Нагорье Арати.",
  ["Hammerfall, Arathi Highlands"] = "Молотопад, Нагорье Арати",
  ["The {q:6624::Triage} quest is given by {n:0:alliance:Doctor Gustaf VanHowzen} in Dustwallow Marsh at Theramore."] = "Задание {q:6624::Triage} дает {n:0:alliance:Doctor Gustaf VanHowzen} в Тераморе в Пылевых топях.",
  ["Foothold Citadel, Dustwallow Marsh"] = "Цитадель Опоры, Пылевые топи",
  ["You get a stack of triage bandages and have to save 15 patients, heal the critically injured ones first."] = "Ты получишь стопку бинтов для сортировки раненых, и нужно спасти 15 пациентов, сначала лечи тяжелораненых.",
  ["How to complete the Triage quest"] = "Как выполнить задание «Сортировка раненых»",
  ["Make sure you have about 10 minutes of spare time to do this with no interruptions."] = "Убедись, что у тебя есть минут 10 свободного времени, чтобы сделать это без перерывов.",
  ["Press CTRL + V to show the health bars over the patients, or turn on \"Show NPC names\" in the interface options."] = "Нажми CTRL + V, чтобы показать полоски здоровья над пациентами, или включи «Показывать имена NPC» в настройках интерфейса.",
  ["Zoom the camera out to third person, so you see as much of the room as you can."] = "Отдали камеру до вида от третьего лица, чтобы видеть как можно больше комнаты.",
  ["Put the Triage Bandages the doctor gave you on your action bar and use those, not your own bandages."] = "Вынеси на панель команд бинты, которые дал доктор, и используй их, а не свои бинты.",
  ["Stand in the middle of the room."] = "Встань в центре комнаты.",
  ["When you see another patient, left-click on them to pre-select them, and as soon as your current heal has finished click the bandages in your action bar and the pre-selected one will begin to heal. Saves valuable seconds this way."] = "Увидев следующего пациента, щелкни по нему левой кнопкой, чтобы заранее выбрать его, и как только текущее лечение закончится, нажми бинты на панели команд, и выбранный пациент начнет лечиться. Так экономятся драгоценные секунды.",
  ["When you have saved 15 patients, {b}turn in the quest immediately{/b}. I failed it on my druid because I waited, six patients died in the meantime and the quest went from completed to failed."] = "Спасши 15 пациентов, {b}сразу сдавай задание{/b}. Я провалил его на друиде, потому что подождал: за это время умерли шесть пациентов, и задание из выполненного стало проваленным.",
  ["29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Mageweave Cloth"] = "29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Магическая ткань",
  ["30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Mageweave Cloth"] = "30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Магическая ткань",
  ["The doctor teaches it at 240."] = "Доктор обучает ему на 240.",
  ["20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Runecloth"] = "20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Руническая ткань",
  ["The doctor teaches it at 260."] = "Доктор обучает ему на 260.",
  ["30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Golden Sansam, 90 Soothing Spices, 30 Crystal Vial"] = "30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Золотой сансам, 90 Успокаивающие специи, 30 Хрустальный флакон",
  ["The recipe is {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Check the Auction House first, and buy it there if it costs less than 8g."] = "Рецепт - {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Сначала проверь аукцион и купи его там, если он стоит меньше 8з.",
  ["If it costs more, you can buy it from {n:0::Pexmit} in Mount Hyjal for 8g, but he can be tricky to find."] = "Если дороже, его можно купить у {n:0::Pexmit} на горе Хиджал за 8з, но его бывает трудно найти.",
  ["Horde players can also get it from Ortak Lomgok in Elderwild, Mount Hyjal, as the reward for {q:96622::A Rest Without Pain}. You have to complete his {q:96616::Herbs for the Bruised and Weary} quest first."] = "Игроки Орды могут также получить его у Ортака Ломгока в Элдервайлде на горе Хиджал в награду за {q:96622::A Rest Without Pain}. Сначала нужно выполнить его задание {q:96616::Herbs for the Bruised and Weary}.",
  ["This WoW Forever Fishing leveling guide will show you the fastest way to level Fishing from 1 to 300. Fishing takes a lot of patience, you will have to catch a lot of fish to get from start to finish, but you don't need any materials, only a Fishing Pole and a few lures."] = "Это руководство по прокачке рыбной ловли для WoW Forever покажет тебе самый быстрый способ поднять рыбную ловлю с 1 до 300. Рыбная ловля требует много терпения, от начала до конца придется поймать кучу рыбы, но никаких материалов не нужно, только удочка и немного приманок.",
  ["Below you will find every Fishing trainer by starting zone and capital city, where to fish for each skill range, and how to learn Expert and Artisan Fishing. If you haven't leveled Cooking yet, use my Fishing and Cooking leveling guide instead, because the fish you catch will level your Cooking at the same time:"] = "Ниже ты найдешь всех учителей рыбной ловли по стартовым зонам и столицам, где рыбачить на каждом диапазоне навыка и как выучить рыбную ловлю уровней Умелец и Мастер. Если ты еще не прокачал кулинарию, используй вместо этого мое руководство по рыбной ловле и кулинарии, ведь пойманная рыба будет одновременно качать кулинарию:",
  ["Fishing Trainer Locations"] = "Где найти учителей рыбной ловли",
  ["Apprentice Fishing has no level requirement in Forever, so you can learn it on a fresh character. Every trainer also teaches Journeyman Fishing, so you don't have to find a different trainer at 50."] = "В Forever у рыбной ловли уровня Ученик нет требований к уровню, так что ее можно выучить новым персонажем. Каждый учитель также обучает рыбной ловле уровня Подмастерье, так что на 50 не придется искать другого учителя.",
  ["Orgrimmar: {n:0:horde:Lumak}"] = "Оргриммар: {n:0:horde:Lumak}",
  ["Undercity: {n:0:horde:Armand Cromwell}"] = "Подгород: {n:0:horde:Armand Cromwell}",
  ["Thunder Bluff: {n:0:horde:Kah Mistrunner}"] = "Громовой Утес: {n:0:horde:Kah Mistrunner}",
  ["Every starting zone has a Fishing trainer, and they all stand next to water, so you can start fishing right away."] = "В каждой стартовой зоне есть учитель рыбной ловли, и все они стоят у воды, так что рыбачить можно начинать сразу.",
  ["{n:0:horde:Lau'Tiki} on the coast at Sen'jin Village"] = "{n:0:horde:Lau'Tiki} на побережье у деревни Сен'джин",
  ["{n:0:horde:Uthan Stillwater} at Stonebull Lake, next to Bloodhoof Village"] = "{n:0:horde:Uthan Stillwater} у озера Каменного Быка, рядом с деревней Кровавого Копыта",
  ["{n:0:horde:Clyde Kellen} at Brightwater Lake, east of Brill"] = "{n:0:horde:Clyde Kellen} у озера Светлой Воды, к востоку от Брилла",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Fenn Fairweather} in Shen'dar Village"] = "{n:0::Baelann Swiftcurrent} в Валанааре, {n:0::Fenn Fairweather} в деревне Шен'дар",
  ["Stormwind City: {n:0:alliance:Arnold Leland}"] = "Штормград: {n:0:alliance:Arnold Leland}",
  ["Ironforge: {n:0:alliance:Grimnur Stonebrand}"] = "Стальгорн: {n:0:alliance:Grimnur Stonebrand}",
  ["Darnassus: {n:0:alliance:Astaia}"] = "Дарнас: {n:0:alliance:Astaia}",
  ["{n:0:alliance:Lee Brown} at Crystal Lake, east of Goldshire"] = "{n:0:alliance:Lee Brown} у Хрустального озера, к востоку от Златоземья",
  ["{n:0:alliance:Paxton Ganter} at Iceflow Lake, on the way to Gnomeregan"] = "{n:0:alliance:Paxton Ganter} у озера Ледяного Потока, по дороге в Гномреган",
  ["{n:0:alliance:Androl Oakhand} in Rut'theran Village, on the shore next to the dock"] = "{n:0:alliance:Androl Oakhand} в деревне Рут'теран, на берегу рядом с причалом",
  ["You can find every Fishing trainer for Horde and Alliance on my WoW Forever Fishing Trainers page."] = "Всех учителей рыбной ловли Орды и Альянса ты найдешь на моей странице «WoW Forever Fishing Trainers».",
  ["How to Fish in WoW Forever (1-75)"] = "Как рыбачить в WoW Forever (1-75)",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a few {i:6529:inv_misc_orb_03:Shiny Bauble} from a Fishing Supply or Trade Supply vendor. In the capital cities they stand next to the trainer, for every other zone open your faction below:"] = "Купи {i:6256:inv_fishingpole_02:Fishing Pole} и несколько {i:6529:inv_misc_orb_03:Shiny Bauble} у торговца рыболовными или ремесленными товарами. В столицах они стоят рядом с учителем, для всех остальных зон открой свою фракцию ниже:",
  ["{n:0:horde:Zansoa} in Sen'jin Village"] = "{n:0:horde:Zansoa} в деревне Сен'джин",
  ["{n:0:horde:Martine Tramblay} at the Death's Watch Waystation, south-east of Brill"] = "{n:0:horde:Martine Tramblay} на заставе Смертного Дозора, к юго-востоку от Брилла",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Belandiel Farflight} in Shen'dar Village"] = "{n:0::Baelann Swiftcurrent} в Валанааре, {n:0::Belandiel Farflight} в деревне Шен'дар",
  ["{n:0:horde:Shankys}, next to the Fishing trainer"] = "{n:0:horde:Shankys}, рядом с учителем рыбной ловли",
  ["{n:0:horde:Lizbeth Cromwell}, next to the Fishing trainer"] = "{n:0:horde:Lizbeth Cromwell}, рядом с учителем рыбной ловли",
  ["{n:0:horde:Sewa Mistrunner}, next to the Fishing trainer"] = "{n:0:horde:Sewa Mistrunner}, рядом с учителем рыбной ловли",
  ["{n:0:horde:Wik'Tar} in Zoram'gar Outpost"] = "{n:0:horde:Wik'Tar} на Заставе Зорам'гар",
  ["{n:0:horde:Katoom the Angler}, the Fishing trainer in Revantusk Village"] = "{n:0:horde:Katoom the Angler}, учитель рыбной ловли в деревне Сломанного Клыка",
  ["{n:0:alliance:Gretta Ganter} at Iceflow Lake"] = "{n:0:alliance:Gretta Ganter} у озера Ледяного Потока",
  ["{n:0:alliance:Nessa Shadowsong} in Rut'theran Village"] = "{n:0:alliance:Nessa Shadowsong} в деревне Рут'теран",
  ["{n:0:alliance:Catherine Leland}, next to the Fishing trainer"] = "{n:0:alliance:Catherine Leland}, рядом с учителем рыбной ловли",
  ["{n:0:alliance:Tansy Puddlefizz}, next to the Fishing trainer"] = "{n:0:alliance:Tansy Puddlefizz}, рядом с учителем рыбной ловли",
  ["{n:0:alliance:Voloren}, next to the Fishing trainer"] = "{n:0:alliance:Voloren}, рядом с учителем рыбной ловли",
  ["{n:0:alliance:Khara Deepwater} at the Loch"] = "{n:0:alliance:Khara Deepwater} у озера Лок",
  ["{n:0:alliance:Stuart Fleming} in Menethil Harbor"] = "{n:0:alliance:Stuart Fleming} в Гавани Менетилов",
  ["Redridge Mountains"] = "Красногорье",
  ["{n:0:alliance:Vernon Hale} at Lake Everstill"] = "{n:0:alliance:Vernon Hale} у озера Безмолвия",
  ["{n:0:alliance:Lindea Rabonne} in Southshore"] = "{n:0:alliance:Lindea Rabonne} в Южнобережье",
  ["Open the Professions window."] = "Открой окно профессий.",
  ["Click on the {b}hammer button{/b} in the row of buttons on the right side of your screen, {b}NOT the Fishing tab{/b}."] = "Нажми {b}кнопку с молотом{/b} в ряду кнопок справа на экране, {b}а НЕ вкладку рыбной ловли{/b}.",
  ["Drag the {s:7731:trade_fishing:Fishing} button from the Fishing box to your action bar."] = "Перетащи кнопку {s:7731:trade_fishing:Fishing} из блока рыбной ловли на панель команд.",
  ["Equip your Fishing Pole and apply the {i:6529:inv_misc_orb_03:Shiny Bauble} lure."] = "Возьми удочку и прицепи приманку {i:6529:inv_misc_orb_03:Shiny Bauble}.",
  ["Go to any starting zone and look for a lake, pond or river. Stand in front of the water and press the fishing button."] = "Иди в любую стартовую зону и найди озеро, пруд или реку. Встань лицом к воде и нажми кнопку рыбной ловли.",
  ["Mouse over the bobber in the water, and when it splashes, right-click on it."] = "Наведи курсор на поплавок в воде и, когда он плеснет, щелкни по нему правой кнопкой.",
  ["Fish until you reach Fishing 75."] = "Рыбачь, пока не дойдешь до Рыбной ловли 75.",
  ["{b}Starting zones:{/b} Dun Morogh, Durotar, Elwynn Forest, Mulgore, Teldrassil, Tirisfal Glades, Zephras Isle"] = "{b}Стартовые зоны:{/b} Дун Морог, Дуротар, Элвиннский лес, Мулгор, Тельдрассил, Тирисфальские леса, Остров Зефрас",
  ["{b}Remember, starting zones do not include capital cities!{/b}"] = "{b}Помни: столицы не считаются стартовыми зонами!{/b}",
  ["If you can't find the Fishing button, I show it with pictures in my how to fish in WoW Forever guide."] = "Если не можешь найти кнопку рыбной ловли, я показываю ее на картинках в своем руководстве о том, как рыбачить в WoW Forever.",
  ["Go back to your trainer and learn Journeyman Fishing. It requires {b}Fishing 50{/b} and {b}level 10{/b}."] = "Вернись к учителю и выучи рыбную ловлю уровня Подмастерье. Нужны {b}Рыбная ловля 50{/b} и {b}10-й уровень{/b}.",
  ["Fish until 150 in one of the capital cities:"] = "Рыбачь до 150 в одной из столиц:",
  ["You can fish in any of these zones too: The Barrens, Darkshore, Ironforge, Loch Modan, Silverpine Forest, Westfall."] = "Можно рыбачить и в любой из этих зон: Степи, Темные берега, Стальгорн, Лок Модан, Серебряный бор, Западный Край.",
  ["If the fish keep getting away, buy {i:6530:inv_misc_monstertail_03:Nightcrawlers} from a Fishing Supply vendor. They need Fishing 50."] = "Если рыба продолжает срываться, купи {i:6530:inv_misc_monstertail_03:Nightcrawlers} у торговца рыболовными товарами. Для них нужна Рыбная ловля 50.",
  ["You can learn Expert Fishing from the {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} book (requires {b}level 20{/b} and {b}Fishing 125{/b}) sold by {n:0::Old Man Heming} at Booty Bay in Stranglethorn Vale. He is in the middle of Booty Bay at the very bottom, near the fishing sign. You can also buy the book from the Auction House."] = "Рыбную ловлю уровня Умелец можно выучить по книге {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} (нужны {b}20-й уровень{/b} и {b}Рыбная ловля 125{/b}), которую продает {n:0::Old Man Heming} в Пиратской Бухте в Тернистой долине. Он в центре Пиратской Бухты, в самом низу, у вывески рыбной лавки. Книгу можно также купить на аукционе.",
  ["Buy a bunch of {i:6532:inv_misc_gem_variety_02:Bright Baubles} from Old Man Heming before you leave."] = "Перед уходом купи у Старика Хеминга побольше {i:6532:inv_misc_gem_variety_02:Bright Baubles}.",
  ["Go to {b}Dustwallow Marsh{/b}, apply {i:6532:inv_misc_gem_variety_02:Bright Baubles} to your Fishing Pole and fish until 225."] = "Иди в {b}Пылевые топи{/b}, прицепи к удочке {i:6532:inv_misc_gem_variety_02:Bright Baubles} и рыбачь до 225.",
  ["I recommend fishing in Dustwallow because the Artisan Fishing quest starts there, but you can fish in these zones too: Alterac Mountains, Arathi Highlands, Desolace, Stranglethorn Vale, Swamp of Sorrows, and Thousand Needles."] = "Советую рыбачить в Пылевых топях, потому что там начинается задание на рыбную ловлю уровня Мастер, но можно рыбачить и в этих зонах: Альтеракские горы, Нагорье Арати, Пустоши, Тернистая долина, Болото Печали и Тысяча Игл.",
  ["Learning Artisan Fishing"] = "Как выучить рыбную ловлю уровня Мастер",
  ["To train Fishing past 225, you must complete the quest {q:6607::Nat Pagle, Angler Extreme} from {n:0::Nat Pagle} in Dustwallow Marsh."] = "Чтобы учиться рыбной ловле дальше 225, нужно выполнить задание {q:6607::Nat Pagle, Angler Extreme} от {n:0::Nat Pagle} в Пылевых топях.",
  ["It requires {b}level 35{/b} and {b}Fishing 225{/b}."] = "Для него нужны {b}35-й уровень{/b} и {b}Рыбная ловля 225{/b}.",
  ["To complete the quest, you have to catch 4 quest fish in four different zones:"] = "Чтобы выполнить задание, нужно поймать 4 рыбы для задания в четырех разных зонах:",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Фералас",
  ["Use {i:6532:inv_misc_gem_variety_02:Bright Baubles} when you are fishing in {b}Feralas{/b} to stop the fish from getting away. You don't need any lures in the other zones because your Fishing skill is high enough by then."] = "Используй {i:6532:inv_misc_gem_variety_02:Bright Baubles}, когда рыбачишь в {b}Фераласе{/b}, чтобы рыба не срывалась. В других зонах приманка не нужна, к тому времени навык рыбной ловли уже достаточно высокий.",
  ["Nat Pagle, Angler Extreme quest"] = "Задание «Нат Пэйгл, рыболов-экстремал»",
  ["After you completed the quest, fish in any of these zones:"] = "Выполнив задание, рыбачь в любой из этих зон:",
  ["Feralas"] = "Фералас",
  ["Western Plaguelands"] = "Западные Чумные земли",
  ["You will have to use {i:6532:inv_misc_gem_variety_02:Bright Baubles} in these zones to stop the fish from getting away!"] = "В этих зонах придется использовать {i:6532:inv_misc_gem_variety_02:Bright Baubles}, чтобы рыба не срывалась!",
  ["This WoW Forever Lockpicking leveling guide will show you the fastest way to level Lockpicking from 1 to 300, with the best place to pick locks for each skill range."] = "Это руководство по прокачке взлома замков для WoW Forever покажет тебе самый быстрый способ поднять взлом замков с 1 до 300 и лучшие места для взлома на каждом диапазоне навыка.",
  ["Max Lockpicking Skill by Level"] = "Максимальный навык взлома замков по уровню",
  ["{b}Your Lockpicking skill can't go higher than 5 times your level{/b}, so you have to level your character to level Lockpicking. This is the level you need for each part of the guide:"] = "{b}Навык взлома замков не может быть выше твоего уровня, умноженного на 5{/b}, так что для прокачки взлома замков нужно качать персонажа. Вот какой уровень нужен для каждой части руководства:",
  ["Your level"] = "Твой уровень",
  ["Max Lockpicking skill"] = "Макс. навык взлома замков",
  ["I originally made this guide with my rogue in Classic. In WoW Forever I'm leveling a hunter, so a friend of mine checks the spots on his rogue, and he confirmed the Horde 1-100 part. Readers told me where they leveled from 150 to 300. I'm assuming the rest is the same as in Classic, but I will confirm it later. If something looks off, send me feedback."] = "Изначально я делал это руководство на своем разбойнике в Classic. В WoW Forever я качаю охотника, поэтому места проверяет мой друг на своем разбойнике, и он подтвердил часть 1-100 для Орды. Читатели рассказали мне, где качались со 150 до 300. Я предполагаю, что остальное такое же, как в Classic, но подтвержу это позже. Если что-то выглядит неправильно, напиши мне.",
  ["Go to the ship near Ratchet in The Barrens. The Buccaneer's Strongboxes there respawn after a few seconds, so even two rogues can skill up there at the same time. {b}They are inside the ship{/b}, at the spot marked on the map below."] = "Иди на корабль у Кабестана в Степях. Пиратские сундуки там возрождаются через несколько секунд, так что качаться там могут даже два разбойника одновременно. {b}Они внутри корабля{/b}, в месте, отмеченном на карте ниже.",
  ["There is another chest at the bottom of the ship called The Jewel of the Southsea. Don't open it if you are low level, because it spawns a mob that will kill you."] = "На дне корабля есть еще один сундук - «Жемчужина Южных морей». Не открывай его, если у тебя низкий уровень: из него появляется монстр, который тебя убьет.",
  ["There are a bunch of Practice Lockboxes in Redridge Mountains, north of Lake Everstill. They respawn really fast, so you can get to 100 there easily."] = "В Красногорье, к северу от озера Безмолвия, есть куча тренировочных сейфов. Они возрождаются очень быстро, так что там легко дойти до 100.",
  ["Go to Zoram Strand in Ashenvale and look for Waterlogged Footlockers along the shore, on land."] = "Иди на берег Зорам в Ясеневом лесу и ищи промокшие сундучки вдоль берега, на суше.",
  ["Go to Angor Fortress in Badlands. There are two kinds of footlockers there, the Battered Footlockers upstairs need 150, and the Dented Footlockers downstairs need {b}175{/b}."] = "Иди в Крепость Ангор в Бесплодных землях. Там два вида сундучков: для потрепанных сундучков наверху нужно 150, а для помятых сундучков внизу {b}175{/b}.",
  ["The footlockers downstairs give a skill point every time until 215, so you can stay here until 225."] = "Сундучки внизу дают очко навыка каждый раз до 215, так что можно оставаться здесь до 225.",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give any skill."] = "Не трать время на обшаривание карманов у местных монстров: их коробки слишком низкого уровня, чтобы давать навык.",
  ["Go to The Slag Pit, the cave in the middle of Searing Gorge, and pick the footlockers there. The ones on the upper part give skill points all the way to 300. They stay yellow until 290 and turn green after that, so the last 10 points take longer."] = "Иди в Шлаковую яму, пещеру в центре Тлеющего ущелья, и вскрывай сундучки там. Те, что в верхней части, дают очки навыка вплоть до 300. Они остаются желтыми до 290, а после становятся зелеными, так что последние 10 очков идут дольше.",
  ["{b}There are two kinds of Dented Footlockers in the Slag Pit{/b}, with the same name. The ones on the lower part need 200 and the ones on the upper part need 225. Pick both until the lower ones stop giving skill points, then stay on the upper part."] = "{b}В Шлаковой яме два вида помятых сундучков{/b} с одинаковым названием. Для тех, что в нижней части, нужно 200, для тех, что в верхней, 225. Вскрывай и те и другие, пока нижние не перестанут давать очки навыка, а затем оставайся в верхней части.",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give much skill."] = "Не трать время на обшаривание карманов у местных монстров: их коробки слишком низкого уровня, чтобы давать много навыка.",
  ["This WoW Forever camping guide will show you how camping works, how to make a campfire and every camp item and buff of every profession."] = "Это руководство по лагерям для WoW Forever покажет тебе, как работают лагеря, как сделать костер, а также все предметы для лагеря и баффы каждой профессии.",
  ["Three night elves sitting at a campfire in Dolanaar, Teldrassil, in WoW Forever"] = "Три ночных эльфа сидят у костра в Доланааре, Тельдрассил, в WoW Forever",
  ["How Camping Works"] = "Как работают лагеря",
  ["Someone puts down a campfire, and everyone around it can place a camp item of their own profession. {b}Sit (/sit) next to the fire for a minute{/b}, you will see a buff start counting down. Then you get Camp Benefits, one buff with everything the camp items give, for an hour."] = "Кто-то ставит костер, и каждый рядом может поставить предмет для лагеря своей профессии. {b}Посиди (/sit) у костра минуту{/b}, и увидишь, как начнется отсчет баффа. Затем ты получишь «Преимущества лагеря» - один бафф со всем, что дают предметы лагеря, на час.",
  ["{b}Each player can place one camp item{/b}, and it puts all your camp items on a 1 hour cooldown. A campfire holds 3, 5 or 10 camp items, depending on how big it is (see How to Make a Campfire below). The buffs are weaker class buffs and don't stack with them."] = "{b}Каждый игрок может поставить один предмет для лагеря{/b}, и после этого все твои предметы для лагеря уходят на перезарядку на 1 час. Костер вмещает 3, 5 или 10 предметов для лагеря в зависимости от размера (смотри «Как сделать костер» ниже). Баффы - это ослабленные классовые баффы, и с ними они не складываются.",
  ["The intro quests in the starting zones, The Great Outdoors and Camping 101, are optional, the buffs work without them. The quest givers' fires always give the Camp Tent's rested experience."] = "Вводные задания в стартовых зонах, The Great Outdoors и Camping 101, не обязательны, баффы работают и без них. Костры у тех, кто выдает эти задания, всегда дают бонус к опыту от палатки лагеря.",
  ["How to Make a Campfire"] = "Как сделать костер",
  ["Learn Cooking from any Cooking trainer, the Basic Campfire Kit comes with it at skill 1. {i:4470:inv_tradeskillitem_01:Simple Wood} is sold by the trade and general goods vendors in most towns. Open your Professions window (the hammer and pick button in the menu bar), craft the kit from 1 Simple Wood under Cooking, then use it from your bags to place the campfire."] = "Выучи кулинарию у любого учителя кулинарии, набор для простого костра идет вместе с ней на навыке 1. {i:4470:inv_tradeskillitem_01:Simple Wood} продают торговцы ремесленными товарами и товарами повседневного спроса в большинстве городов. Открой окно профессий (кнопка с молотом и киркой в панели меню), сделай набор из 1 простой древесины в разделе кулинарии, а затем используй его из сумки, чтобы поставить костер.",
  ["{b}Tip:{/b} you don't have to carry Flint and Tinder and wood around any more, craft a stack of Basic Campfire Kits at home and carry only those, they take one bag slot. You can also hand them to others."] = "{b}Совет:{/b} больше не нужно таскать с собой огниво и древесину, сделай дома стопку наборов для простого костра и носи только их, они занимают одну ячейку сумки. Их также можно отдавать другим.",
  ["The bigger campfires hold more camp items, but they need a Blueprint."] = "Костры побольше вмещают больше предметов для лагеря, но для них нужен чертеж.",
  ["The Expert Campfire Kit needs more Cooking to use than to learn (220 against 200). It's usually the other way around, so maybe it's a bug."] = "Для использования набора для костра умельца нужно больше кулинарии, чем для изучения (220 против 200). Обычно бывает наоборот, так что, возможно, это ошибка.",
  ["Learn at"] = "Изучение на",
  ["Use at"] = "Использование на",
  ["Camp items"] = "Предметы для лагеря",
  ["Made from"] = "Из чего делается",
  ["Comes with Cooking"] = "Идет вместе с кулинарией",
  ["{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Dropped by: {n:3673::Lord Serpentis} in Wailing Caverns"] = "{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Добыча: {n:3673::Lord Serpentis} в Пещерах Стенаний",
  ["{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} I don't know yet where it drops"] = "{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} Пока не знаю, где он падает",
  ["Camp Items"] = "Предметы для лагеря",
  ["Every profession has three camp items, at skill 20, 140 and 300 (Cooking has two), and each one replaces the one before. The tier 1 item comes from your profession trainer, {b}tier 2 and 3 need a Blueprint{/b}, a recipe item. The tier 2 and 3 blueprints drop from bosses, most of them in dungeons, the tabs show which one. Only the Herbalism one at 300 is not known yet."] = "У каждой профессии три предмета для лагеря: на навыке 20, 140 и 300 (у кулинарии два), и каждый заменяет предыдущий. Предмет 1-го уровня дает учитель профессии, {b}для 2-го и 3-го уровня нужен чертеж{/b} - предмет-рецепт. Чертежи 2-го и 3-го уровня падают с боссов, в основном в подземельях, во вкладках указано, с каких. Неизвестен пока только предмет травничества на 300.",
  ["{b}Every item also gives the buff of the tier 1 item of its profession{/b}, so you never have to choose between a buff and a crafting station. A Master Forge still gives the Strength buff of the Sharpening Wheel. Whether a tier 3 item also gives what the tier 2 item gives (an anvil from a Master Forge) is not confirmed yet. The tabs only list what each tier adds."] = "{b}Каждый предмет также дает бафф предмета 1-го уровня своей профессии{/b}, так что выбирать между баффом и ремесленной станцией никогда не придется. Великая кузня по-прежнему дает бафф к силе от точильного круга. Дает ли предмет 3-го уровня то же, что и предмет 2-го уровня (наковальню от Великой кузни), пока не подтверждено. Во вкладках указано только то, что добавляет каждый уровень.",
  ["Alchemy"] = "Алхимия",
  ["Blacksmithing"] = "Кузнечное дело",
  ["Enchanting"] = "Наложение чар",
  ["Engineering"] = "Инженерное дело",
  ["Leatherworking"] = "Кожевничество",
  ["Tailoring"] = "Портняжное дело",
  ["Skinning"] = "Снятие шкур",
  ["First Aid"] = "Первая помощь",
  ["Camp Item"] = "Предмет для лагеря",
  ["What It Does"] = "Что делает",
  ["Mana regeneration buff, doesn't stack with Blessing of Wisdom"] = "Бафф к восполнению маны, не складывается с Благословением мудрости",
  ["Trainer or the Camping 101 quest"] = "Учитель или задание Camping 101",
  ["A Fermenter, needed for a few Alchemy recipes"] = "Бродильный чан, нужен для нескольких рецептов алхимии",
  ["{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Добыча: {n:250657::Rath'mael} в Руинах Лордерона",
  ["An Alchemy Lab, needed for some Alchemy recipes"] = "Алхимическая лаборатория, нужна для некоторых рецептов алхимии",
  ["{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} Добыча: {n:10508::Ras Frostwhisper} в Некроситете",
  ["Strength buff, doesn't stack with Strength of Earth Totem"] = "Бафф к силе, не складывается с Тотемом силы земли",
  ["An anvil"] = "Наковальня",
  ["{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} Dropped by: {n:1763::Gilnid} in The Deadmines"] = "{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} Добыча: {n:1763::Gilnid} в Мертвых копях",
  ["A Master Forge, needed for many Blacksmithing recipes"] = "Великая кузня, нужна для многих рецептов кузнечного дела",
  ["{i:273113:inv_garrison_blueprints3:Blueprint: Master Forge} Dropped by: {n:8983::Golem Lord Argelmach} in Blackrock Depths"] = "{i:273113:inv_garrison_blueprints3:Blueprint: Master Forge} Добыча: {n:8983::Golem Lord Argelmach} в Глубинах Черной горы",
  ["Armor, all stats and resistances buff, doesn't stack with Mark of the Wild"] = "Бафф к броне, всем характеристикам и сопротивлениям, не складывается со Знаком дикой природы",
  ["Better disenchanting"] = "Улучшенное распыление",
  ["{i:273103:inv_garrison_blueprints3:Blueprint: Arcane Salvager} Dropped by: {n:246020::Shade of the Archmage} in the City of Dalaran"] = "{i:273103:inv_garrison_blueprints3:Blueprint: Arcane Salvager} Добыча: {n:246020::Shade of the Archmage} в городе Даларан",
  ["An Arcane Forge, needed for some Enchanting recipes"] = "Чародейская кузня, нужна для некоторых рецептов наложения чар",
  ["{i:273116:inv_garrison_blueprints3:Blueprint: Arcane Forge} Dropped by: {n:261809::Nanaya} in Kalimdor"] = "{i:273116:inv_garrison_blueprints3:Blueprint: Arcane Forge} Добыча: {n:261809::Nanaya} в Калимдоре",
  ["Summons the {n:242498::Reagent Bot}, a vendor with class reagents and profession supplies for everyone at the camp"] = "Призывает {n:242498::Reagent Bot} - торговца классовыми реагентами и товарами для профессий для всех в лагере",
  ["Repairs for everyone at the camp"] = "Починка для всех в лагере",
  ["{i:273092:inv_garrison_blueprints3:Blueprint: Repair Bot} Dropped by: {n:643::Sneed} in The Deadmines"] = "{i:273092:inv_garrison_blueprints3:Blueprint: Repair Bot} Добыча: {n:643::Sneed} в Мертвых копях",
  ["An Anarchist's Workbench, needed for some Engineering recipes"] = "Верстак анархиста, нужен для некоторых рецептов инженерного дела",
  ["{i:273117:inv_garrison_blueprints3:Blueprint: Anarchist's Workbench} Dropped by: {n:11058::Ezra Grimm} in Stratholme"] = "{i:273117:inv_garrison_blueprints3:Blueprint: Anarchist's Workbench} Добыча: {n:11058::Ezra Grimm} в Стратхольме",
  ["Rested experience up to 5% of a level, once an hour (a debuff blocks it until then)"] = "Бонус к опыту за отдых до 5% уровня, раз в час (до тех пор его блокирует дебафф)",
  ["A Tanning Rack, needed for many Leatherworking recipes"] = "Дубильная стойка, нужна для многих рецептов кожевничества",
  ["{i:273096:inv_garrison_blueprints3:Blueprint: Tanning Rack} Dropped by: {n:3886::Razorclaw the Butcher} in Shadowfang Keep"] = "{i:273096:inv_garrison_blueprints3:Blueprint: Tanning Rack} Добыча: {n:3886::Razorclaw the Butcher} в Крепости Темного Клыка",
  ["A Sewing Machine, needed for many Leatherworking recipes"] = "Швейная машина, нужна для многих рецептов кожевничества",
  ["{i:273121:inv_garrison_blueprints3:Blueprint: Sewing Machine} Dropped by: {n:10432::Vectus} in Scholomance"] = "{i:273121:inv_garrison_blueprints3:Blueprint: Sewing Machine} Добыча: {n:10432::Vectus} в Некроситете",
  ["Spirit buff for players of your faction, doesn't stack with Divine Spirit. Horde and Alliance each have their own banner"] = "Бафф к духу для игроков твоей фракции, не складывается с Божественным духом. У Орды и Альянса свои знамена",
  ["A Spinning Wheel, needed for many Tailoring recipes"] = "Прялка, нужна для многих рецептов портняжного дела",
  ["{i:273099:inv_garrison_blueprints3:Blueprint: Spinning Wheel} Dropped by: {n:246017::Unstable Sentinel} in the City of Dalaran"] = "{i:273099:inv_garrison_blueprints3:Blueprint: Spinning Wheel} Добыча: {n:246017::Unstable Sentinel} в городе Даларан",
  ["A Loom, needed for many Tailoring recipes"] = "Ткацкий станок, нужен для многих рецептов портняжного дела",
  ["{i:273124:inv_garrison_blueprints3:Blueprint: Loom} Dropped by: {n:10436::Baroness Anastari} in Stratholme"] = "{i:273124:inv_garrison_blueprints3:Blueprint: Loom} Добыча: {n:10436::Baroness Anastari} в Стратхольме",
  ["Intellect buff, doesn't stack with Arcane Intellect"] = "Бафф к интеллекту, не складывается с Чародейским интеллектом",
  ["A Greenhouse that grows herbs from seeds you plant"] = "Теплица, в которой из посаженных семян растут травы",
  ["{i:273106:inv_garrison_blueprints3:Blueprint: Greenhouse} Dropped by: {n:260325::Shadetooth} in Excavation Site: Wetlands"] = "{i:273106:inv_garrison_blueprints3:Blueprint: Greenhouse} Добыча: {n:260325::Shadetooth} в Месте раскопок: Болотина",
  ["A Seed Hybridizer that multiplies seeds or combines them into rarer ones"] = "Гибридизатор семян, который размножает семена или объединяет их в более редкие",
  ["Melee Attack Power buff, doesn't stack with Blessing of Might"] = "Бафф к силе атаки в ближнем бою, не складывается с Благословением могущества",
  ["Spawns a common mining node over time, and gives the Lodestone buff too"] = "Со временем создает обычное месторождение руды, а также дает бафф «Магнетит»",
  ["{i:273097:inv_garrison_blueprints3:Blueprint: Rock Garden} Dropped by: {n:260326::Relic Guardian} in Excavation Site: Wetlands"] = "{i:273097:inv_garrison_blueprints3:Blueprint: Rock Garden} Добыча: {n:260326::Relic Guardian} в Месте раскопок: Болотина",
  ["A Molten Foundry, needed for Smelt Heavy Thorium"] = "Плавильня, нужна для выплавки тяжелого тория",
  ["{i:273122:inv_garrison_blueprints3:Blueprint: Molten Foundry} Dropped by: {n:9156::Ambassador Flamelash} in Blackrock Depths"] = "{i:273122:inv_garrison_blueprints3:Blueprint: Molten Foundry} Добыча: {n:9156::Ambassador Flamelash} в Глубинах Черной горы",
  ["+2% crit chance, doesn't stack with Moonkin Aura"] = "+2% к шансу крит. удара, не складывается с Аурой лунного совуха",
  ["A book anyone can read to learn Track Beasts"] = "Книга, прочитав которую любой может выучить «Выслеживание зверей»",
  ["{i:273098:inv_garrison_blueprints3:Blueprint: Field Guide} Dropped by: {n:3671::Lady Anacondra} in Wailing Caverns"] = "{i:273098:inv_garrison_blueprints3:Blueprint: Field Guide} Добыча: {n:3671::Lady Anacondra} в Пещерах Стенаний",
  ["A workbench with 1 trap"] = "Верстак с 1 капканом",
  ["{i:273109:inv_garrison_blueprints3:Blueprint: Trapper's Workbench} Dropped by: {n:10430::The Beast} in Upper Blackrock Spire and {n:3974::Houndmaster Loksey} in Scarlet Monastery"] = "{i:273109:inv_garrison_blueprints3:Blueprint: Trapper's Workbench} Добыча: {n:10430::The Beast} в Верхней части пика Черной горы и {n:3974::Houndmaster Loksey} в Монастыре Алого ордена",
  ["Cooking has no tier 1 camp item, its first one is the campfire (see How to Make a Campfire above)."] = "У кулинарии нет предмета для лагеря 1-го уровня, первый ее предмет - костер (смотри «Как сделать костер» выше).",
  ["Stamina food for everyone at the camp"] = "Еда на выносливость для всех в лагере",
  ["{i:273102:inv_garrison_blueprints3:Blueprint: Cookie's Feast} Dropped by: {n:645::Cookie} in The Deadmines"] = "{i:273102:inv_garrison_blueprints3:Blueprint: Cookie's Feast} Добыча: {n:645::Cookie} в Мертвых копях",
  ["An Iron Oven, needed for the most advanced Cooking recipes"] = "Железная печь, нужна для самых сложных рецептов кулинарии",
  ["{i:273115:inv_garrison_blueprints3:Blueprint: Iron Oven} Dropped by: {n:9736::Quartermaster Zigris} in Lower Blackrock Spire"] = "{i:273115:inv_garrison_blueprints3:Blueprint: Iron Oven} Добыча: {n:9736::Quartermaster Zigris} в Нижней части пика Черной горы",
  ["Stamina buff, doesn't stack with Power Word: Fortitude"] = "Бафф к выносливости, не складывается со Словом силы: Стойкость",
  ["Healing potions and anti-venom"] = "Лечебные зелья и противоядие",
  ["{i:273105:inv_garrison_blueprints3:Blueprint: Toxin Study} Dropped by: {n:4278::Commander Springvale} in Shadowfang Keep"] = "{i:273105:inv_garrison_blueprints3:Blueprint: Toxin Study} Добыча: {n:4278::Commander Springvale} в Крепости Темного Клыка",
  ["Healing potions and poultices"] = "Лечебные зелья и припарки",
  ["{i:273118:inv_garrison_blueprints3:Blueprint: Plague Doctor's Laboratory} Dropped by: {n:11261::Doctor Theolen Krastinov} in Scholomance"] = "{i:273118:inv_garrison_blueprints3:Blueprint: Plague Doctor's Laboratory} Добыча: {n:11261::Doctor Theolen Krastinov} в Некроситете",
  ["+8% all stats, doesn't stack with Blessing of Kings"] = "+8% ко всем характеристикам, не складывается с Благословением королей",
  ["Uncommon fish for 1 hour and Fishing lures"] = "Необычная рыба на 1 час и рыболовные приманки",
  ["{i:273141:inv_garrison_blueprints3:Blueprint: Fishing Rack} Dropped by: {n:6243::Gelihast} in Blackfathom Deeps"] = "{i:273141:inv_garrison_blueprints3:Blueprint: Fishing Rack} Добыча: {n:6243::Gelihast} в Непроглядной Пучине",
  ["Rare fish for 1 hour and Fishing lures"] = "Редкая рыба на 1 час и рыболовные приманки",
  ["{i:273119:inv_garrison_blueprints3:Blueprint: Fishing Hut} Dropped by: {n:5710::Jammal'an the Prophet} in the Sunken Temple"] = "{i:273119:inv_garrison_blueprints3:Blueprint: Fishing Hut} Добыча: {n:5710::Jammal'an the Prophet} в Затонувшем храме",
  ["Crafting Stations: Tanning Rack, Loom and More"] = "Ремесленные станции: дубильная стойка, ткацкий станок и другие",
  ["A lot of recipes in WoW Forever need a crafting station nearby, like a Tanning Rack, a Spinning Wheel or a Loom. {b}I haven't found any of them out in the world{/b}, they only come from camps, so for a lot of higher level crafting you need a camp. The easiest way is a camp that already has the station, anyone at the fire can use it."] = "Многим рецептам в WoW Forever нужна ремесленная станция поблизости, например дубильная стойка, прялка или ткацкий станок. {b}В открытом мире я ни одной не нашел{/b}, они бывают только в лагерях, так что для многих рецептов высокого уровня нужен лагерь. Проще всего найти лагерь, где такая станция уже стоит, пользоваться ею может любой у костра.",
  ["To place one yourself:"] = "Чтобы поставить ее самому:",
  ["Get your profession to the skill in the table below."] = "Подними профессию до навыка из таблицы ниже.",
  ["Get the station's Blueprint and learn it. The table shows where it drops, if we know it."] = "Достань чертеж станции и выучи его. В таблице указано, где он падает, если мы это знаем.",
  ["Craft the station, put down a campfire and use the station from your bags next to it."] = "Сделай станцию, поставь костер и используй станцию из сумки рядом с ним.",
  ["Station"] = "Станция",
  ["Profession"] = "Профессия",
  ["Blueprint"] = "Чертеж",
  ["Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "Добыча: {n:250657::Rath'mael} в Руинах Лордерона",
  ["Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "Добыча: {n:10508::Ras Frostwhisper} в Некроситете",
  ["Dropped by: {n:8983::Golem Lord Argelmach} in Blackrock Depths"] = "Добыча: {n:8983::Golem Lord Argelmach} в Глубинах Черной горы",
  ["Dropped by: {n:261809::Nanaya} in Kalimdor"] = "Добыча: {n:261809::Nanaya} в Калимдоре",
  ["Dropped by: {n:11058::Ezra Grimm} in Stratholme"] = "Добыча: {n:11058::Ezra Grimm} в Стратхольме",
  ["Dropped by: {n:3886::Razorclaw the Butcher} in Shadowfang Keep"] = "Добыча: {n:3886::Razorclaw the Butcher} в Крепости Темного Клыка",
  ["Dropped by: {n:10432::Vectus} in Scholomance"] = "Добыча: {n:10432::Vectus} в Некроситете",
  ["Dropped by: {n:246017::Unstable Sentinel} in the City of Dalaran"] = "Добыча: {n:246017::Unstable Sentinel} в городе Даларан",
  ["Dropped by: {n:10436::Baroness Anastari} in Stratholme"] = "Добыча: {n:10436::Baroness Anastari} в Стратхольме",
  ["Dropped by: {n:9156::Ambassador Flamelash} in Blackrock Depths"] = "Добыча: {n:9156::Ambassador Flamelash} в Глубинах Черной горы",
  ["Dropped by: {n:9736::Quartermaster Zigris} in Lower Blackrock Spire"] = "Добыча: {n:9736::Quartermaster Zigris} в Нижней части пика Черной горы",
  ["Merchant's Favor is a new currency in WoW Forever. You get it by filling Waylaid Crates with materials and handing them in at your faction's camp, Durotar Supply and Logistics for Horde and the Azeroth Commerce Authority for Alliance, and you spend it on the recipes, mount, pet, tabard and titles the camp vendors sell. Many recipes and the mount, pet and tabard also need reputation with the camp, which you get from Craftsman's Writs. This WoW Forever Merchant's Favor guide will show you where the camps are, how to earn Merchant's Favor and reputation, and every recipe the vendors sell."] = "Благосклонность торговцев - новая валюта в WoW Forever. Ее получают, заполняя потерянные ящики материалами и сдавая их в лагерь своей фракции: Durotar Supply and Logistics у Орды и Azeroth Commerce Authority у Альянса. Тратится она на рецепты, маунта, питомца, гербовую накидку и звания, которые продают торговцы лагеря. Для многих рецептов, а также маунта, питомца и накидки нужна еще и репутация с лагерем, которую дают заказы ремесленника. Это руководство по благосклонности торговцев для WoW Forever покажет тебе, где находятся лагеря, как зарабатывать благосклонность торговцев и репутацию, и все рецепты, которые продают торговцы.",
  ["How It Works"] = "Как это работает",
  ["Waylaid Crates drop randomly in the open world and in dungeons, and you can also buy them on the Auction House. You fill a crate with the materials it asks for and hand it in at your camp. For that you get Merchant's Favor, the currency you buy the recipes with."] = "Потерянные ящики случайно падают в открытом мире и в подземельях, а еще их можно купить на аукционе. Ты заполняешь ящик материалами, которые он требует, и сдаешь его в своем лагере. За это ты получаешь благосклонность торговцев - валюту, на которую покупаются рецепты.",
  ["Many recipes also need reputation with the camp. You earn reputation by doing Craftsman's Writs. You get a writ, craft the item it asks for and bring it to the customer."] = "Для многих рецептов нужна также репутация с лагерем. Репутацию зарабатывают заказами ремесленника: получаешь заказ, делаешь требуемый предмет и относишь его заказчику.",
  ["Where the Camps Are"] = "Где находятся лагеря",
  ["The Horde camp belongs to Durotar Supply and Logistics, and the Alliance camp belongs to the Azeroth Commerce Authority. Each camp has a recipe vendor for every crafting profession and Cooking, and both camps sell the same recipes (see Recipes by Profession below)."] = "Лагерь Орды принадлежит Durotar Supply and Logistics, а лагерь Альянса - Azeroth Commerce Authority. В каждом лагере есть торговец рецептами для каждой ремесленной профессии и кулинарии, и оба лагеря продают одни и те же рецепты (смотри «Рецепты по профессиям» ниже).",
  ["Three Corners, Redridge Mountains"] = "Три Угла, Красногорье",
  ["How to Earn Merchant's Favor"] = "Как заработать благосклонность торговцев",
  ["You earn Merchant's Favor by filling Waylaid Crates with materials and bringing them to your camp."] = "Благосклонность торговцев зарабатывается заполнением потерянных ящиков материалами и доставкой их в свой лагерь.",
  ["Merchant's Favor is per character, so every character has to earn its own."] = "Благосклонность торговцев своя у каждого персонажа, так что каждому персонажу придется зарабатывать ее самому.",
  ["Filling a Waylaid Crate"] = "Как заполнить потерянный ящик",
  ["{b}Find a Waylaid Crate.{/b} They drop randomly in the open world and in dungeons, and {b}you can also buy them on the Auction House{/b}. Each one asks for one kind of material, for example {i:248684:inv_crate_07:Waylaid Crate: Apprentice Textiles}."] = "{b}Найди потерянный ящик.{/b} Они случайно падают в открытом мире и в подземельях, а еще {b}их можно купить на аукционе{/b}. Каждый требует один вид материала, например {i:248684:inv_crate_07:Waylaid Crate: Apprentice Textiles}.",
  ["Right-click it and fill it with one of the bundles it lists, for example 40 Linen Cloth or 20 Light Leather (see Waylaid Crates and Rewards below). You get a Sealed crate, and that one binds to you."] = "Щелкни по нему правой кнопкой и заполни одним из перечисленных наборов, например 40 льняного материала или 20 легкой кожи (смотри «Потерянные ящики и награды» ниже). Ты получишь запечатанный ящик, и он становится персональным.",
  ["Bring the Sealed crate to {n:0::Dokimi} at the Horde camp or {n:0::Marcy Baker} at the Alliance camp. You get Merchant's Favor and some silver for it."] = "Отнеси запечатанный ящик к {n:0::Dokimi} в лагере Орды или к {n:0::Marcy Baker} в лагере Альянса. За него ты получишь благосклонность торговцев и немного серебра.",
  ["Waylaid Crates and Rewards"] = "Потерянные ящики и награды",
  ["When you fill a Waylaid Crate, it turns into a Sealed crate of the same rank and color. You hand that one in at your camp for the Merchant's Favor in the last column. There are also blue Sealed crates and a Sealed Elite Crate, but I don't know yet what they give."] = "Когда заполняешь потерянный ящик, он превращается в запечатанный ящик того же ранга и цвета. Его ты сдаешь в своем лагере за благосклонность торговцев из последнего столбца. Есть также синие запечатанные ящики и запечатанный элитный ящик, но что они дают, я пока не знаю.",
  ["The Textiles, Ore, Herbs and Curiosities crates take raw materials, and the Fabrics, Ingots and Parts crates take crafted ones."] = "Ящики с тканью, рудой, травами и диковинками принимают сырье, а ящики с отрезами, слитками и деталями - изготовленные материалы.",
  ["{b}A crate needs only one of the bundles in its row, not all of them.{/b}"] = "{b}Ящику нужен только один из наборов в его строке, а не все.{/b}",
  ["Apprentice"] = "Ученик",
  ["Journeyman"] = "Подмастерье",
  ["Expert"] = "Умелец",
  ["Artisan"] = "Мастер",
  ["You need level 10 to open these."] = "Чтобы открыть их, нужен 10-й уровень.",
  ["You also get {m:2:s:} {m:50:c:} for a white crate and {m:5:s:} for a green one."] = "Также ты получаешь {m:2:s:} {m:50:c:} за белый ящик и {m:5:s:} за зеленый.",
  ["Crate"] = "Ящик",
  ["Fill it with one of these"] = "Заполни одним из этого",
  ["Reward"] = "Награда",
  ["You also get {m:5:s:} for a white crate and {m:10:s:} for a green one."] = "Также ты получаешь {m:5:s:} за белый ящик и {m:10:s:} за зеленый.",
  ["You need level 20 to open these."] = "Чтобы открыть их, нужен 20-й уровень.",
  ["You also get {m:7:s:} {m:50:c:} for a white crate and {m:15:s:} for a green one."] = "Также ты получаешь {m:7:s:} {m:50:c:} за белый ящик и {m:15:s:} за зеленый.",
  ["You need level 35 to open these."] = "Чтобы открыть их, нужен 35-й уровень.",
  ["Not known yet"] = "Пока неизвестно",
  ["How to Earn Durotar Supply and Azeroth Commerce Authority Reputation"] = "Как заработать репутацию с Durotar Supply и Azeroth Commerce Authority",
  ["{b}Handing in Sealed crates doesn't give reputation.{/b} Reputation with Durotar Supply and Logistics or the Azeroth Commerce Authority comes from Craftsman's Writs, crafting orders that you deliver to a customer somewhere in the world. After reaching Friendly, empty Waylaid Crates give reputation too (see Crate Returns after Friendly below)."] = "{b}Сдача запечатанных ящиков не дает репутации.{/b} Репутацию с Durotar Supply and Logistics или Azeroth Commerce Authority дают заказы ремесленника - ремесленные заказы, которые нужно доставить заказчику где-то в мире. После достижения дружелюбия репутацию дают и пустые потерянные ящики (смотри «Возврат ящиков после дружелюбия» ниже).",
  ["The first time you fill a crate or start a writ, you also get a {i:280180:inv_misc_note_03:Shipping Label}. It starts a quest to your camp, which gives 2,000 reputation and 50 Merchant's Favor."] = "Когда впервые заполняешь ящик или начинаешь заказ, ты также получаешь {i:280180:inv_misc_note_03:Shipping Label}. Он начинает задание, ведущее в твой лагерь, которое дает 2 000 репутации и 50 благосклонности торговцев.",
  ["Craftsman's Writs"] = "Заказы ремесленника",
  ["A Journeyman writ gives 75 reputation, an Expert writ 125 and an Artisan writ 200. {b}You can do each writ once a day{/b}, and as many different writs a day as you want."] = "Заказ подмастерья дает 75 репутации, заказ умельца 125, а заказ мастера 200. {b}Каждый заказ можно выполнять раз в день{/b}, а разных заказов в день - сколько угодно.",
  ["{b}Get a Craftsman's Writ.{/b} In the open world and in dungeons they drop as a {i:262888:inv_misc_note_02:Sealed Journeyman's Writ}, {i:262889:inv_misc_note_02:Sealed Expert's Writ} or {i:262890:inv_misc_note_02:Sealed Artisan's Writ}, an envelope with a random writ of that rank inside. {b}You can also buy writs on the Auction House.{/b}"] = "{b}Достань заказ ремесленника.{/b} В открытом мире и в подземельях они падают в виде {i:262888:inv_misc_note_02:Sealed Journeyman's Writ}, {i:262889:inv_misc_note_02:Sealed Expert's Writ} или {i:262890:inv_misc_note_02:Sealed Artisan's Writ} - конверта со случайным заказом этого ранга внутри. {b}Заказы можно также купить на аукционе.{/b}",
  ["Right-click the writ to start its quest, for example {i:264047:inv_misc_note_01:Craftsman's Writ: Lesser Wizard's Robe}."] = "Щелкни по заказу правой кнопкой, чтобы начать его задание, например {i:264047:inv_misc_note_01:Craftsman's Writ: Lesser Wizard's Robe}.",
  ["Make the item it asks for or buy it on the Auction House. You don't need the profession yourself."] = "Сделай требуемый предмет или купи его на аукционе. Самому владеть профессией не нужно.",
  ["Bring the item to the customer, your map shows where. The customer takes the item and the writ, and you get the reputation and a Coin Pouch with some silver. Writs don't give Merchant's Favor. {b}On the beta, the customer had no question mark over their head.{/b} I think it was a bug, so if you don't see one, right-click them anyway and the window to hand in the writ opens."] = "Отнеси предмет заказчику, где он, показано на карте. Заказчик забирает предмет и заказ, а ты получаешь репутацию и кошелек с серебром. Благосклонность торговцев заказы не дают. {b}На бете над заказчиком не было вопросительного знака.{/b} Думаю, это была ошибка, так что если не видишь знака, все равно щелкни по нему правой кнопкой, и откроется окно сдачи заказа.",
  ["Crate Returns after Friendly"] = "Возврат ящиков после дружелюбия",
  ["At Friendly, you unlock the Uncertified Scribe in your camp, {n:0:horde:Kurvelk Shadowhoof} at the Horde camp and {n:0:alliance:Dianne Softstep} at the Alliance camp. Both sell the same two items:"] = "При дружелюбии в твоем лагере открывается Неаттестованный писарь: {n:0:horde:Kurvelk Shadowhoof} в лагере Орды и {n:0:alliance:Dianne Softstep} в лагере Альянса. Оба продают одни и те же два предмета:",
  ["Reputation"] = "Репутация",
  ["What it does"] = "Что делает",
  ["Friendly"] = "Дружелюбие",
  ["Turns an empty Waylaid Crate into 50 reputation, see the steps below."] = "Превращает пустой потерянный ящик в 50 репутации, смотри шаги ниже.",
  ["Honored"] = "Уважение",
  ["Turns a Craftsman's Writ into a random writ of the same rank."] = "Превращает заказ ремесленника в случайный заказ того же ранга.",
  ["{b}Buy a {i:262902:inv_10_inscription2_repcontracts_scroll_02_uprez_color5:Forged Delivery Receipt}{/b} from the Uncertified Scribe."] = "{b}Купи {i:262902:inv_10_inscription2_repcontracts_scroll_02_uprez_color5:Forged Delivery Receipt}{/b} у Неаттестованного писаря.",
  ["Buy a Waylaid Crate on the Auction House. The receipt seems to work on any of them, so buy the cheapest one."] = "Купи потерянный ящик на аукционе. Квитанция, похоже, работает с любым, так что покупай самый дешевый.",
  ["Use the receipt on the crate. You get a {i:262917:inv_crate_01:Notarized Shipping Container}."] = "Используй квитанцию на ящике. Ты получишь {i:262917:inv_crate_01:Notarized Shipping Container}.",
  ["Hand the container to the same NPC who takes your Sealed crates. You get the reputation and 1 silver."] = "Отдай контейнер тому же NPC, который принимает запечатанные ящики. Ты получишь репутацию и 1 серебряную монету.",
  ["Recipes by Profession"] = "Рецепты по профессиям",
  ["Both camps, Durotar Supply and Logistics (Horde) and the Azeroth Commerce Authority (Alliance), sell the same recipes for Merchant's Favor. This is what each profession gets:"] = "Оба лагеря, Durotar Supply and Logistics (Орда) и Azeroth Commerce Authority (Альянс), продают за благосклонность торговцев одни и те же рецепты. Вот что получает каждая профессия:",
  ["{b}Alchemy:{/b} potions and elixirs."] = "{b}Алхимия:{/b} зелья и эликсиры.",
  ["{b}Blacksmithing:{/b} mail and plate sets for tanks, melee, healers and paladins, and three weapons."] = "{b}Кузнечное дело:{/b} кольчужные и латные комплекты для танков, бойцов ближнего боя, лекарей и паладинов, а также три оружия.",
  ["{b}Cooking:{/b} six smoothies that give Spirit."] = "{b}Кулинария:{/b} шесть смузи, которые дают дух.",
  ["{b}Enchanting:{/b} necklace, weapon and armor enchants, relics (idols, totems and librams) and caster weapons (staves, off-hands and wands)."] = "{b}Наложение чар:{/b} чары на ожерелья, оружие и броню, реликвии (идолы, тотемы и манускрипты) и оружие заклинателей (посохи, предметы для левой руки и жезлы).",
  ["{b}Engineering:{/b} bombs, thrown weapons, goggles, belts, trinkets and gadgets."] = "{b}Инженерное дело:{/b} бомбы, метательное оружие, очки, пояса, аксессуары и устройства.",
  ["{b}Leatherworking:{/b} leather and mail sets for every role, and two armor kits."] = "{b}Кожевничество:{/b} кожаные и кольчужные комплекты для любой роли и две накладки для доспехов.",
  ["{b}Tailoring:{/b} cloth sets for every spell school and for healers, and two reagent bags."] = "{b}Портняжное дело:{/b} тканевые комплекты для каждой школы магии и для лекарей, а также две сумки для реагентов.",
  ["{b}The armor and weapons you craft from these recipes bind on pickup{/b}, so you can only make them for yourself."] = "{b}Броня и оружие, сделанные по этим рецептам, становятся персональными при получении{/b}, так что делать их можно только для себя.",
  ["{n:0:horde:Apothecary Durelle} at the Horde camp and {n:0:alliance:Nina Surefire} at the Alliance camp sell 28 Alchemy recipes."] = "{n:0:horde:Apothecary Durelle} в лагере Орды и {n:0:alliance:Nina Surefire} в лагере Альянса продают 28 рецептов алхимии.",
